def linux_memory_gib() -> tuple[float, float]:
    """Return this process's RSS and host available memory on Linux."""

    rss_kib = float("nan")
    available_kib = float("nan")
    try:
        with Path("/proc/self/status").open() as stream:
            for line in stream:
                if line.startswith("VmRSS:"):
                    rss_kib = float(line.split()[1])
                    break
        with Path("/proc/meminfo").open() as stream:
            for line in stream:
                if line.startswith("MemAvailable:"):
                    available_kib = float(line.split()[1])
                    break
    except (OSError, IndexError, ValueError):
        pass
    scale = 1024.0 * 1024.0
    return rss_kib / scale, available_kib / scale


def clear_jax_stage_caches() -> tuple[float, float, float, float, int]:
    """Clear process-global JAX staging caches between different domains."""

    rss_before_gib, available_before_gib = linux_memory_gib()
    jax.clear_caches()
    collected = gc.collect()
    rss_after_gib, available_after_gib = linux_memory_gib()
    return (
        rss_before_gib,
        rss_after_gib,
        available_before_gib,
        available_after_gib,
        int(collected),
    )


def stage_reexec_argv(
    argv: list[str], *, checkpoint: Path, next_stage_name: str
) -> list[str]:
    """Build a stage-boundary resume argv without reset-only options."""

    value_options = {"--resume-from", "--resume-start-stage"}
    reset_only_flags = {
        "--trainer-stage-reexec",
        "--fixed-contact-cartesian-same-stage-memory-recovery",
        "--fixed-contact-cartesian-u76-memory-recovery",
        "--fixed-contact-cartesian-v86-local-u50-memory-recovery",
        "--fixed-contact-cartesian-v88-mid-u250-memory-recovery",
        "--fixed-contact-cartesian-v90-u120-memory-recovery",
        "--fixed-contact-cartesian-v91-u90-validation-memory-recovery",
        "--fixed-contact-cartesian-v93-u8010-memory-recovery",
        "--fixed-contact-cartesian-v94-u8472-memory-recovery",
        "--fixed-contact-cartesian-v95-u8310-rootcause-repair",
        "--fixed-contact-cartesian-v96-u455-rootcause-repair",
        "--fixed-contact-cartesian-v97-u1846-center-repair",
        "--fixed-contact-cartesian-v98-u1540-xy-validation-repair",
        "--fixed-contact-cartesian-v99-u500-motion-repair",
        "--fixed-contact-cartesian-v100-u1978-hard-corner-repair",
        "--fixed-contact-cartesian-v101-u1978-hard-lane-focus-repair",
        "--fixed-contact-cartesian-v102-u7139-motion-apex-repair",
        "--fixed-contact-cartesian-v103-u3500-joint-quality-repair",
        "--fixed-contact-cartesian-v104-u7139-conjunction-repair",
        "--fixed-contact-cartesian-v105-u3500-joint-quality-repair",
        "--fixed-contact-cartesian-v106-u7139-dense-quality-repair",
        "--fixed-contact-cartesian-v107-u99-entropy-repair",
        "--fixed-contact-cartesian-v108-u128-quality-credit-repair",
        "--fixed-contact-cartesian-v109-u99-motion-apex-transition-repair",
        "--fixed-contact-cartesian-v110-u128-quality-credit-repair",
        "--fixed-contact-cartesian-v111-u99-apex-conjunction-stable-repair",
        "--fixed-contact-cartesian-v112-u99-gentle-exploration-repair",
        "--fixed-contact-cartesian-v113-u99-apex-stable-repair",
        "--fixed-contact-cartesian-v114-u89-joint-credit-repair",
        "--fixed-contact-cartesian-v115-u35-joint-credit-repair",
        "--fixed-contact-cartesian-v116-u54-joint-credit-repair",
        "--fixed-contact-cartesian-v117-u39-uniform-xy-repair",
        "--fixed-contact-cartesian-v118-u54-low-lr-repair",
        "--fixed-contact-cartesian-v119-u39-low-lr-uniform-xy-repair",
        "--fixed-contact-cartesian-v120-u42-uniform-xy-repair",
        "--fixed-contact-cartesian-v121-u58-hard-lane-focus-repair",
        "--fixed-contact-cartesian-v122-u42-selected-reproof",
        "--fixed-contact-cartesian-v123-u58-angular-repair",
        "--fixed-contact-cartesian-v124-u40-hard-lane-repair",
        "--fixed-contact-cartesian-v125-u40-hard-lane-repair",
        "--fixed-contact-cartesian-v126-u120-angular-repair",
        "--fixed-contact-cartesian-v127-u40-joint-repair",
        "--fixed-contact-cartesian-v128-u42-low-x-repair",
        "--fixed-contact-cartesian-v129-u128-transition-repair",
        "--fixed-contact-cartesian-v130-u1500-exact-corner-repair",
        "--fixed-contact-cartesian-v131-s0-cycle-repair",
        "--fixed-contact-cartesian-v133-recurrent-deadline-repair",
        "--fixed-contact-cartesian-v135-feasible-outcome-repair",
        "--fixed-contact-cartesian-v136-contact-first-repair",
        "--fixed-contact-cartesian-v137-constraint-alignment-repair",
        "--fixed-contact-cartesian-v138-arrival-constraint-repair",
        "--fixed-contact-cartesian-v139-feasible-update-guard",
        "--resume-curriculum-state",
        "--reset-critic-on-resume",
        "--reset-optimizer-on-resume",
        "--cmdp-reset-cost-state-on-resume",
    }
    result: list[str] = []
    index = 0
    while index < len(argv):
        argument = argv[index]
        option = argument.split("=", 1)[0]
        if option in value_options:
            index += 1 if "=" in argument else 2
            continue
        if option in reset_only_flags:
            index += 1
            continue
        result.append(argument)
        index += 1
    result.extend(
        [
            "--resume-from",
            str(checkpoint),
            "--resume-start-stage",
            next_stage_name,
            "--trainer-stage-reexec",
        ]
    )
    return result


def same_stage_reexec_argv(
    argv: list[str], *, checkpoint: Path, stage_name: str
) -> list[str]:
    """Build an exact same-stage resume that retains convergence history."""

    result = stage_reexec_argv(
        argv,
        checkpoint=checkpoint,
        next_stage_name=stage_name,
    )
    result.append("--resume-curriculum-state")
    return result


def bounded_stage_history(
    history: list[dict[str, object]], max_rows: int
) -> list[dict[str, object]]:
    """Return at most the newest ``max_rows`` without changing legacy mode."""

    if int(max_rows) <= 0 or len(history) <= int(max_rows):
        return list(history)
    return list(history[-int(max_rows):])


def stage_metric_history(
    history: list[dict[str, object]], warmup_updates: int
) -> list[dict[str, object]]:
    """Select post-warmup metrics correctly even when old rows were trimmed."""

    return [
        row
        for row in history
        if int(float(row.get("stage_update", 0.0))) > int(warmup_updates)
    ]


def curriculum_continuity_checkpoint_extra(
    history: list[dict[str, object]],
    *,
    max_rows: int,
    last_advance_eval_update: int,
    best_stage_score: float,
    committed_transaction_history: list[dict[str, object]] | None = None,
) -> dict[str, object]:
    """Serialize a bounded convergence tail and its non-window accumulators."""

    if int(max_rows) <= 0:
        return {}
    extra = {
        "stage_history_tail": bounded_stage_history(history, max_rows),
        "last_advance_eval_update": int(last_advance_eval_update),
        "best_stage_score": float(best_stage_score),
    }
    if committed_transaction_history is not None:
        extra["committed_stage_history_tail"] = bounded_stage_history(
            committed_transaction_history,
            max_rows,
        )
    return extra


def frozen_stage_reexec_script(
    *, current_script: Path, save_dir: Path, require_frozen: bool
) -> Path:
    """Resolve and authenticate the run-frozen trainer used at stage reexec."""

    if not require_frozen:
        return current_script.resolve()
    relative_path = Path(
        "pingpong_controller/tools/rl_sim/train_juggle_mjx_curriculum.py"
    )
    save_dir = save_dir.resolve()
    current_script = current_script.resolve()
    snapshot_root = save_dir / "source_snapshot"
    for parent in current_script.parents:
        if parent.name != "source_snapshot":
            continue
        try:
            parent.relative_to(save_dir)
        except ValueError:
            break
        if current_script == (parent / relative_path).resolve():
            # A manual recovery runs directly from a newly authenticated
            # nested snapshot.  Keep that repaired source pinned at every
            # later same-stage/stage-boundary reexec instead of falling back
            # to the run's older root snapshot.
            snapshot_root = parent
        break
    candidate = snapshot_root / relative_path
    manifest_path = snapshot_root / "source_snapshot_manifest.json"
    if not candidate.is_file() or not manifest_path.is_file():
        raise SystemExit(
            "[mjx_curriculum] frozen stage reexec requires the trainer and "
            f"manifest under {snapshot_root}"
        )
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        expected_sha256 = str(
            manifest["files"][relative_path.as_posix()]["sha256"]
        )
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as exc:
        raise SystemExit(
            "[mjx_curriculum] frozen stage reexec manifest lacks the trainer hash"
        ) from exc
    actual_sha256 = hashlib.sha256(candidate.read_bytes()).hexdigest()
    if actual_sha256 != expected_sha256:
        raise SystemExit(
            "[mjx_curriculum] frozen stage reexec trainer SHA-256 mismatch: "
            f"expected {expected_sha256}, got {actual_sha256}"
        )
    return candidate.resolve()


