def _measured_qvel_rmp_vertical_v62_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float],
) -> list[CurriculumStage]:
    """Rebalance only existing rewards toward full, physical 14-hit cycles.

    Formula-level analysis of all 122 V55 components and V57's frozen
    full-episode populations showed that the existing V56 absolute-apex,
    physical-lift, contact-height and true-counted-cadence functions already
    rank the desired full 14-hit behavior above the low/fast 15+ mode.  V62
    therefore returns to V57, not V58--V61, and adds no reward component.

    The confirmed vertical-strike antagonist is disabled.  Once the source
    already acquires roughly fourteen hits, redundant count/contact-quality
    event scale is reduced and the existing counted-cadence score is made
    more selective.  Dense survival, termination, view, motion-safety,
    physical height targets, control and the complete nominal-small-wide DR
    order remain unchanged.
    """

    v57 = _measured_qvel_rmp_vertical_v57_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    changed_fields = {
        "racket_up_drift_penalty_weight": 0.0,
        "center_flat_hit_reward_weight": 1.2,
        "hit_count_floor_reward_weight": 0.5,
        "hit_reward_base": 0.75,
        "hit_cadence_target_interval": 0.390,
        "hit_cadence_sigma": 0.035,
        "hit_cadence_reward_weight": 2.0,
    }
    result: list[CurriculumStage] = []
    for source in v57:
        candidate_cfg = replace(source.cfg, **changed_fields)
        result.append(
            replace(
                source,
                name=source.name.replace("rmp57_", "rmp62_", 1),
                cfg=candidate_cfg,
                notes=(
                    "V62 existing-reward-only rebalance: no new reward "
                    "channel is enabled. Disable the confirmed up-drift "
                    "antagonist; reduce redundant center/count/base-hit "
                    "event scale to 1.2/0.5/0.75; strengthen the existing "
                    "true-counted 0.390 s cadence score to weight 2.0 with "
                    "0.035 s sigma. Preserve every V57 absolute-apex, "
                    "physical-lift, contact-height, survival, view, safety, "
                    "control, PPO-environment and DR-order value. "
                    + source.notes
                ),
            )
        )

    if len(result) != 28:
        raise ValueError(f"V62 expected 28 stages, got {len(result)}")
    for source, candidate in zip(v57, result, strict=True):
        restored_cfg = replace(
            candidate.cfg,
            **{name: getattr(source.cfg, name) for name in changed_fields},
        )
        if restored_cfg != source.cfg:
            raise ValueError("V62 may rebalance only seven existing rewards")
        if source.cfg.racket_up_drift_penalty_weight != 6.0:
            raise ValueError("V62 expects V57 up-drift weight 6.0")
        if source.cfg.post_hit_joint_apex_lift_reward_weight != 0.0:
            raise ValueError("V62 prohibits V58 joint dense reward")
        if source.cfg.full_episode_joint_height_reward_weight != 0.0:
            raise ValueError("V62 prohibits V60 terminal joint reward")
        if source.cfg.hit_adaptive_reflected_velocity_penalty_weight != 0.0:
            raise ValueError("V62 prohibits V61 reflected-velocity reward")
    if result[0].name != "rmp62_joint_apex_lift_repair_nominal_execution":
        raise ValueError("V62 must begin in the V57 nominal execution domain")
    if result[19].name != "rmp62_complete_nonexecution_full_episode_polish":
        raise ValueError("V62 must preserve V57 full polish at Stage 20")
    if result[20].name != "rmp62_rmp_internal_micro_6p25":
        raise ValueError("V62 may widen execution DR only after Stage 20")
    return result


