def _measured_qvel_rmp_vertical_v88_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float],
) -> list[CurriculumStage]:
    """Build strict spatial/hold margins separately before their joint task.

    Frozen V86 update-224 ablations attributed independent survival losses to
    the widest episode-target XY support and the measured 8%/2.2% RMP-target
    publication-hold tail.  The historical course introduced those axes in
    order but required only 0.90/0.82 intermediate survival, so it never built
    the 0.95/0.90 margin on either axis before combining them.  V88 retains
    the complete V85 task and PPO horizon while inserting two strict-margin
    lessons immediately before the unchanged full-domain Stage-24 commit.
    """

    source = _measured_qvel_rmp_vertical_v85_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    if len(source) != 32:
        raise ValueError(f"V88 expected 32 V85 source stages, got {len(source)}")

    result = [
        replace(
            stage,
            name=stage.name.replace("rmp85_", "rmp88_", 1),
            notes=(
                "V88 factorized-risk continuation; unchanged completed "
                "source lesson. " + stage.notes
            ),
        )
        for stage in source[:23]
    ]
    full_template = source[23]
    reward_updates = {
        "early_termination_remaining_horizon_penalty": (
            full_template.cfg.early_termination_remaining_horizon_penalty
        ),
        "full_episode_completion_reward": (
            full_template.cfg.full_episode_completion_reward
        ),
        "full_episode_completion_min_hits": (
            full_template.cfg.full_episode_completion_min_hits
        ),
        "low_hit_penalty_weight": full_template.cfg.low_hit_penalty_weight,
    }
    wide_no_hold_cfg = replace(source[17].cfg, **reward_updates)
    hold_bridge_cfg = replace(
        source[16].cfg,
        dr_rmp_target_update_hold_probability=(
            full_template.cfg.dr_rmp_target_update_hold_probability
        ),
        dr_rmp_target_update_hold_tail_probability=(
            full_template.cfg.dr_rmp_target_update_hold_tail_probability
        ),
        **reward_updates,
    )
    result.extend(
        (
            replace(
                full_template,
                name="rmp88_wide_xy_no_hold_margin",
                cfg=wide_no_hold_cfg,
                notes=(
                    "V88 isolated spatial-risk margin: widest episode-target "
                    "XY support, normal in-view observation noise and no "
                    "target-publication hold. The full Stage-24 reward and "
                    "strict 0.95/0.90 survival contract are active."
                ),
            ),
            replace(
                full_template,
                name="rmp88_hold8_bridge_xy_margin",
                cfg=hold_bridge_cfg,
                notes=(
                    "V88 isolated timing-risk margin: bridge XY support with "
                    "the final measured 8%/2.2% target-publication hold and "
                    "2--9-tick tail. The full Stage-24 reward and strict "
                    "0.95/0.90 survival contract are active."
                ),
            ),
            replace(
                full_template,
                name="rmp88_complete_nonexecution_factorized_commit",
                notes=(
                    "V88 joint-risk commit: restore the exact V85 Stage-24 "
                    "wide-XY plus measured target-hold domain after both "
                    "isolated axes have strict survival margin. "
                    + full_template.notes
                ),
            ),
        )
    )
    result.extend(
        replace(
            stage,
            name=stage.name.replace("rmp85_", "rmp88_", 1),
            notes=(
                "V88 post-factorization continuation; source lesson is "
                "otherwise unchanged. " + stage.notes
            ),
        )
        for stage in source[24:]
    )

    for source_stage, candidate in zip(source[:23], result[:23], strict=True):
        if replace(
            candidate,
            name=source_stage.name,
            notes=source_stage.notes,
        ) != source_stage:
            raise ValueError("V88 may not reinterpret completed V85 lessons")
    for source_stage, candidate in zip(source[24:], result[26:], strict=True):
        if replace(
            candidate,
            name=source_stage.name,
            notes=source_stage.notes,
        ) != source_stage:
            raise ValueError("V88 may not reinterpret post-commit V85 lessons")
    if len(result) != 34:
        raise ValueError(f"V88 expected 34 stages, got {len(result)}")
    if result[23].name != "rmp88_wide_xy_no_hold_margin":
        raise ValueError("V88 formal continuation must enter Stage 24")
    if any(
        stage.target_mean_len_frac != 0.95
        or stage.target_episode_truncation_rate != 0.90
        for stage in result[23:26]
    ):
        raise ValueError("V88 factorized margin gates drifted")
    return result


