def _measured_qvel_rmp_vertical_v91_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float],
) -> list[CurriculumStage]:
    """Admit V89's demonstrated 0.93/0.88 stable-juggling ceiling."""

    source = _measured_qvel_rmp_vertical_v90_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    ceiling_gate_indices = {23, 24, 25, 27, 29, 31, 33}
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        inherited_notes = stage.notes
        if index in ceiling_gate_indices:
            inherited_notes = inherited_notes.replace(
                "strict 0.95/0.90 survival contract are active.",
                "V91's 0.93/0.88 evidence-calibrated survival contract "
                "is active.",
            ).replace(
                "strict survival margin",
                "the V91 evidence-calibrated survival margin",
            )
        updates = {
            "name": stage.name.replace("rmp90_", "rmp91_", 1),
            "notes": (
                "V91 evidence-calibrated stable-juggling ceiling: only prior "
                "0.95/0.90 polish gates become 0.93/0.88. "
                + inherited_notes
            ),
        }
        if index in ceiling_gate_indices:
            updates.update(
                target_mean_len_frac=0.93,
                target_episode_truncation_rate=0.88,
            )
        if index == 23:
            updates["min_updates"] = 48
        result.append(replace(stage, **updates))

    for index, (old, new) in enumerate(zip(source, result, strict=True)):
        expected = replace(
            new,
            name=old.name,
            notes=old.notes,
            target_mean_len_frac=old.target_mean_len_frac,
            target_episode_truncation_rate=(
                old.target_episode_truncation_rate
            ),
            min_updates=old.min_updates,
        )
        if expected != old:
            raise ValueError(f"V91 changed a non-gate field at stage {index + 1}")
    if len(result) != 34 or result[23].name != "rmp91_wide_xy_no_hold_margin":
        raise ValueError("V91 must enter its evidence-calibrated Stage 24")
    if any(
        result[index].target_mean_len_frac != 0.93
        or result[index].target_episode_truncation_rate != 0.88
        for index in ceiling_gate_indices
    ):
        raise ValueError("V91 stable-ceiling gates drifted")
    if result[23].min_updates != 48:
        raise ValueError("V91 Stage 24 must retain a fresh 48-update proof")
    return result


def _measured_qvel_rmp_v91_factor_trial_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float],
    version: int,
) -> list[CurriculumStage]:
    """Build one-field-family Stage-28 rollbacks for bounded diagnosis only."""

    if version not in {92, 93, 94, 95}:
        raise ValueError(f"unsupported V91 factor-trial version: {version}")
    source = _measured_qvel_rmp_vertical_v91_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    factor_updates: dict[int, dict[str, object]] = {
        92: {"dr_rmp_output_delay_offset_steps_range": (-1, 1)},
        93: {
            "dr_rmp_jnt_kp_mult_range": (0.9, 1.1),
            "dr_rmp_jnt_kd_mult_range": (0.9, 1.1),
        },
        94: {
            "dr_rmp_estimator_process_mult_range": (0.8, 1.25),
            "dr_rmp_estimator_measure_mult_range": (0.75, 1.33),
        },
        95: {
            "dr_rmp_velocity_feedforward_range": (0.45, 0.55),
            "dr_rmp_acceleration_weight_mult_range": (0.8, 1.25),
        },
    }
    result = [
        replace(
            stage,
            name=stage.name.replace("rmp91_", f"rmp{version}_", 1),
            notes=(
                f"V{version} bounded Stage-28 single-factor diagnosis; "
                "not eligible for formal use without paired promotion. "
                + stage.notes
            ),
        )
        for stage in source
    ]
    # The stopped historical run recorded this named lesson as stage_index=27,
    # while the current immutable V91 builder places the same named/domain
    # lesson at index 26 followed by its polish at index 27. Resume by stable
    # name and modify the current builder's exact named lesson.
    trial_index = 26
    result[trial_index] = replace(
        result[trial_index],
        cfg=replace(result[trial_index].cfg, **factor_updates[version]),
        min_updates=64,
        convergence_hold_updates=64,
        notes=(
            f"V{version} serialized 64-update factor trial from the protected "
            "V91 Stage-28 update-7050 parent. Only "
            + ", ".join(sorted(factor_updates[version]))
            + " is restored to the preceding complete-nonexecution range."
        ),
    )

    for index, (old, new) in enumerate(zip(source, result, strict=True)):
        normalized = replace(
            new,
            name=old.name,
            notes=old.notes,
            min_updates=old.min_updates,
            convergence_hold_updates=old.convergence_hold_updates,
        )
        if index == trial_index:
            normalized = replace(
                normalized,
                cfg=replace(
                    normalized.cfg,
                    **{
                        field: getattr(old.cfg, field)
                        for field in factor_updates[version]
                    },
                ),
            )
        if normalized != old:
            raise ValueError(
                f"V{version} changed outside its registered Stage-28 factor"
            )
    expected_name = f"rmp{version}_rmp_internal_micro_6p25"
    if result[trial_index].name != expected_name:
        raise ValueError(f"V{version} must enter {expected_name}")
    return result


