def _measured_qvel_rmp_vertical_v96_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float],
) -> list[CurriculumStage]:
    """Promote the paired V93 Kp/Kd rollback into a formal continuation."""

    source = _measured_qvel_rmp_vertical_v91_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result = [
        replace(
            stage,
            name=stage.name.replace("rmp91_", "rmp96_", 1),
            notes=(
                "V96 paired-promoted Kp/Kd DR continuation; reward, gates, "
                "observations, control and every other domain field remain "
                "V91-exact. "
                + stage.notes
            ),
        )
        for stage in source
    ]
    promoted_index = 26
    result[promoted_index] = replace(
        result[promoted_index],
        cfg=replace(
            result[promoted_index].cfg,
            dr_rmp_jnt_kp_mult_range=(0.9, 1.1),
            dr_rmp_jnt_kd_mult_range=(0.9, 1.1),
        ),
        notes=(
            "V96 formal Stage-28 continuation from the selected V93 "
            "64-update checkpoint. Paired 512-lane seeds promoted only the "
            "RMP Kp/Kd multiplier ranges to [0.9, 1.1]."
        ),
    )
    for index, (old, new) in enumerate(zip(source, result, strict=True)):
        normalized = replace(new, name=old.name, notes=old.notes)
        if index == promoted_index:
            normalized = replace(
                normalized,
                cfg=replace(
                    normalized.cfg,
                    dr_rmp_jnt_kp_mult_range=(
                        old.cfg.dr_rmp_jnt_kp_mult_range
                    ),
                    dr_rmp_jnt_kd_mult_range=(
                        old.cfg.dr_rmp_jnt_kd_mult_range
                    ),
                ),
            )
        if normalized != old:
            raise ValueError(
                f"V96 changed outside its promoted Stage-28 Kp/Kd ranges "
                f"at stage {index + 1}"
            )
    if result[promoted_index].name != "rmp96_rmp_internal_micro_6p25":
        raise ValueError("V96 must enter rmp96_rmp_internal_micro_6p25")
    return result


def _measured_qvel_rmp_vertical_v97_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Move the selected V96 policy through fixed-base and 4.0 g lessons.

    The four inserted lessons isolate the pending simulation priorities in
    order: aligned fixed base, the 1 mm placed-ball reset geometry, exact
    4.0 g nominal mass, then the validated centered small mass interval.
    Every control, observation, reward, contact and non-mass DR field remains
    V96-exact.
    """

    if measured_ball_mass_range_kg is None:
        raise ValueError(
            "V97 measured ball-mass DR requires a validated centered range"
        )
    mass_low, mass_high = sorted(
        float(value) for value in measured_ball_mass_range_kg
    )
    mass_center = 0.5 * (mass_low + mass_high)
    mass_half_width = 0.5 * (mass_high - mass_low)
    if not np.isclose(mass_center, 0.004, rtol=0.0, atol=1.0e-12):
        raise ValueError(
            "V97 measured ball-mass DR must be centered on exactly 0.004 kg"
        )
    if not np.isclose(
        mass_half_width,
        0.0001,
        rtol=0.0,
        atol=1.0e-12,
    ):
        raise ValueError(
            "V97 measured ball-mass DR half-width must equal the validated "
            "0.0001 kg contract"
        )

    source = _measured_qvel_rmp_vertical_v96_stages(
        stages,
        measured_ball_mass_range_kg=(0.0030, 0.0040),
    )
    source_index = 27
    if len(source) != 34:
        raise ValueError(f"V97 expected 34 V96 source stages, got {len(source)}")
    if source[source_index].name != "rmp96_rmp_internal_micro_6p25_polish":
        raise ValueError("V97 source polish-stage identity changed")

    def fixed_cfg(
        source_cfg: MjxJuggleConfig,
        mass_range_kg: tuple[float, float],
        *,
        place_ball_on_racket: bool,
    ) -> MjxBaseModeConfig:
        values = dict(source_cfg.__dict__)
        values["dr_ball_mass_range"] = mass_range_kg
        if place_ball_on_racket and source_cfg.ball_reset_mode == "racket_launch":
            values["racket_launch_surface_gap_range_m"] = (0.001, 0.001)
        return MjxBaseModeConfig(
            **values,
            simulation_base_mode="aligned_fixed",
        )

    source_stage = source[source_index]
    bridge_gates = {
        "target_mean_len_frac": 0.92,
        "target_episode_truncation_rate": 0.84,
        "convergence_hold_updates": 16,
    }
    fixed_stage = replace(
        source_stage,
        name="rmp97_base_fixed_bridge",
        cfg=fixed_cfg(
            source_stage.cfg,
            source_stage.cfg.dr_ball_mass_range,
            place_ball_on_racket=False,
        ),
        notes=(
            "V97 priority-1 bridge: align the support geometry and constrain "
            "all six base pose DOFs at the calibrated initial pose. Legacy "
            "ball mass, reset geometry, contact, reward, observation and "
            "control values remain V96 polish-stage exact. "
            + source_stage.notes
        ),
        **bridge_gates,
    )
    placed_stage = replace(
        source_stage,
        name="rmp97_ball_placed_on_racket_bridge",
        cfg=fixed_cfg(
            source_stage.cfg,
            source_stage.cfg.dr_ball_mass_range,
            place_ball_on_racket=True,
        ),
        notes=(
            "V97 reset-geometry bridge: retain the fixed base and place the "
            "ball bottom 1 mm above the sampled racket surface. Legacy mass "
            "and all contact, reward, observation and control values remain "
            "unchanged. "
            + source_stage.notes
        ),
        **bridge_gates,
    )
    nominal_stage = replace(
        source_stage,
        name="rmp97_ball_4g_nominal_bridge",
        cfg=fixed_cfg(
            source_stage.cfg,
            (0.004, 0.004),
            place_ball_on_racket=True,
        ),
        notes=(
            "V97 priority-2 mass-only bridge: on the accepted fixed-base "
            "domain use exactly 0.004 kg. The unchanged normalized inertia "
            "factor scales physical inertia with m*r^2; every non-mass "
            "domain and training field remains unchanged. "
            + source_stage.notes
        ),
        **bridge_gates,
    )
    measured_stage = replace(
        source_stage,
        name="rmp97_ball_4g_measured_dr_consolidate",
        cfg=fixed_cfg(
            source_stage.cfg,
            (mass_low, mass_high),
            place_ball_on_racket=True,
        ),
        notes=(
            "V97 measured-mass consolidation: uniformly sample the validated "
            f"centered interval [{mass_low:.9f}, {mass_high:.9f}] kg. The "
            "existing dr_ball_mass metric logs sampled episode mass; original "
            "V96 polish-stage gates and all non-mass values remain unchanged. "
            + source_stage.notes
        ),
    )

    result = list(source[:source_index]) + [
        fixed_stage,
        placed_stage,
        nominal_stage,
        measured_stage,
    ]
    for stage in source[source_index + 1 :]:
        result.append(
            replace(
                stage,
                name=stage.name.replace("rmp96_", "rmp97_", 1),
                cfg=fixed_cfg(
                    stage.cfg,
                    (mass_low, mass_high),
                    place_ball_on_racket=True,
                ),
                notes=(
                    "V97 committed fixed-base/4.0 g path: retain the aligned "
                    "six-DOF base lock, 1 mm racket-launch gap and validated "
                    "centered mass interval while preserving the V96 lesson. "
                    + stage.notes
                ),
            )
        )

    for old, candidate in zip(
        source[source_index + 1 :], result[source_index + 4 :], strict=True
    ):
        candidate_cfg = dict(candidate.cfg.__dict__)
        if candidate_cfg.pop("simulation_base_mode", None) != "aligned_fixed":
            raise ValueError("V97 tail escaped its fixed-base contract")
        candidate_cfg["dr_ball_mass_range"] = old.cfg.dr_ball_mass_range
        if old.cfg.ball_reset_mode == "racket_launch":
            if candidate_cfg["racket_launch_surface_gap_range_m"] != (
                0.001,
                0.001,
            ):
                raise ValueError("V97 tail escaped its 1 mm reset gap")
            candidate_cfg["racket_launch_surface_gap_range_m"] = (
                old.cfg.racket_launch_surface_gap_range_m
            )
        if candidate_cfg != old.cfg.__dict__:
            raise ValueError(
                "V97 tail changed outside base mode, ball mass and reset gap"
            )
        if replace(
            candidate,
            name=old.name,
            cfg=old.cfg,
            notes=old.notes,
        ) != old:
            raise ValueError("V97 changed a committed V96 tail gate")
    return result


