def _measured_qvel_rmp_vertical_v100_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Version the one-eval-lane transactional tolerance experiment."""

    source = _measured_qvel_rmp_vertical_v99_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    recovery_index = 31
    if len(source) != 37:
        raise ValueError(f"V100 expected 37 V99 source stages, got {len(source)}")
    if source[recovery_index].name != "rmp99_rmp_internal_commit_12p5":
        raise ValueError("V100 source Stage-32 identity changed")
    result = list(source[:recovery_index])
    result.extend(
        replace(
            stage,
            name=stage.name.replace("rmp99_", "rmp100_", 1),
            notes=(
                "V100 transactional recovery preserves the V99 stage and "
                "hard safety contracts; its launcher alone permits at most "
                "one 256-lane unit of secondary-gap movement. "
                + stage.notes
            ),
        )
        for stage in source[recovery_index:]
    )
    for old, candidate in zip(
        source[recovery_index:],
        result[recovery_index:],
        strict=True,
    ):
        if replace(candidate, name=old.name, notes=old.notes) != old:
            raise ValueError("V100 changed a V99 stage outside identity/notes")
    return result


