def validate_fixed_contact_plane_v1_from_scratch(
    *,
    resume_path: str | Path | None,
    resume_curriculum_state: bool,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> None:
    """Reject checkpoint migration and an unregistered 4.0 g mass interval."""

    if resume_path is not None or bool(resume_curriculum_state):
        raise ValueError(
            "fixed-contact-plane v1 is a new 80-D separated current/future "
            "dynamic-target course and "
            "must start "
            "from scratch"
        )
    if measured_ball_mass_range_kg is None:
        raise ValueError(
            "fixed-contact-plane v1 requires the measured 0.004 kg interval"
        )
    measured = tuple(sorted(float(value) for value in measured_ball_mass_range_kg))
    if len(measured) != 2 or not np.allclose(
        measured, (0.0039, 0.0041), atol=1.0e-12, rtol=0.0
    ):
        raise ValueError(
            "fixed-contact-plane v1 requires the registered 0.004 kg "
            "centered interval [0.0039, 0.0041] kg"
        )


def _fixed_contact_plane_vision_robust_qvel_rmp_v1_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Build the independent S0--S5 fixed-contact-plane training course."""

    validate_fixed_contact_plane_v1_from_scratch(
        resume_path=None,
        resume_curriculum_state=False,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    measured_mass_range = (0.0039, 0.0041)
    # V97 Stage 32 is used only as the registered control/PPO-domain template.
    # No actor, critic, optimizer, convergence history, or checkpoint is
    # restored across the new 80-D observation/reward boundary.
    source = _measured_qvel_rmp_vertical_v97_stages(
        stages,
        measured_ball_mass_range_kg=measured_mass_range,
    )[31]
    source_values = dict(source.cfg.__dict__)
    source_values.update(
        simulation_base_mode="aligned_fixed",
        action_command_mode="velocity",
        policy_integration_feedback_source="measured",
        recovered_rmp_motion_mode=True,
        recovered_rmp_direct_qvel_target=True,
        recovered_rmp_bounded_qvel_reference=True,
        include_qvel_reference_error_obs=False,
        right_arm_pd_profile="recovered_rmp_rmpmd_v2",
        actuator_cmd_filter=False,
        actuator_cmd_tau=0.0,
        actuator_cmd_gain=1.0,
        actuator_compensation_mode="none",
        actuator_lead_compensation=False,
        arm_post_compensation_limiter=False,
        arm_servo_target_limiter=False,
        arm_servo_target_tracking_planner=False,
        arm_servo_planner_before_actuator_model=False,
        arm_actual_state_limiter=False,
        arm_actual_target_tracking_governor=False,
        ball_racket_collision_geometry="finite_mesh16",
        ball_racket_pair_override_enabled=True,
        ball_racket_pair_solref=V33_CONTACT_PAIR_SOLREF,
        ball_racket_pair_solreffriction=V33_CONTACT_PAIR_SOLREFFRICTION,
        ball_racket_pair_solimp=V33_CONTACT_PAIR_SOLIMP,
        ball_racket_pair_friction=V33_CONTACT_PAIR_FRICTION,
        ball_racket_pair_margin_m=0.0,
        ball_racket_pair_gap_m=0.0,
        ball_racket_pair_condim=3,
        ball_racket_contact_boundary_mode="robot_dynamic",
        fixed_contact_actor_observation_schema=(
            "fixed_contact_plane_v1_separate_current_future_80d"
        ),
        fixed_contact_target=ContactTargetConfig(
            target_apex_z_m=1.40,
            max_post_ball_vxy_m_s=0.20,
            max_lateral_displacement_per_bounce_m=0.050,
            max_tilt_deg=3.0,
            max_time_to_contact_s=1.0,
            gravity_m_s2=9.8,
        ),
        dr_racket_radius_offset_m=0.0,
        # Keep the ball-property update path active even in the clean stages:
        # the shared XML still contains the legacy 2.7 g nominal. Exact
        # singleton ranges below compile a true 4.0 g spherical ball without
        # adding stochastic DR before S5.
        domain_randomization=True,
        dr_randomize_ball=True,
        dr_gravity_z_range=(-9.81, -9.81),
        dr_ball_mass_range=(0.004, 0.004),
        dr_ball_normalized_inertia_range=(0.4, 0.4),
        dr_ball_spin_x_range_rad_s=(0.0, 0.0),
        dr_ball_spin_y_range_rad_s=(0.0, 0.0),
        dr_ball_spin_z_range_rad_s=(0.0, 0.0),
        dr_randomize_contact=False,
        dr_randomize_actuator=False,
        dr_action_scale_mult_range=(1.0, 1.0),
        dr_randomize_pd=False,
        dr_randomize_recovered_rmp=False,
        dr_randomize_racket_mount=False,
        dr_racket_pos_offset_m=0.0,
        dr_racket_rot_offset_rad=0.0,
        dr_randomize_ball_obs_frame=False,
        dr_ball_obs_pos_bias_base_m=(0.0, 0.0, 0.0),
        dr_ball_obs_rot_bias_deg=(0.0, 0.0, 0.0),
        dr_ball_obs_vel_bias_base_m_s=(0.0, 0.0, 0.0),
        dr_ball_obs_scale_range=(1.0, 1.0),
        ball_obs_rate_hz=90.0,
        ball_obs_fractional_rate=True,
        ball_obs_pos_noise_std=0.0,
        ball_obs_vel_noise_std=0.0,
        ball_obs_dropout_prob=0.0,
        ball_obs_dropout_burst_prob=0.0,
        ball_obs_require_camera_visible=False,
        ball_obs_require_view_bounds=False,
        ball_obs_require_view_z_high=False,
        ball_obs_age_tracks_stale=True,
        high_latency_obs=False,
        enable_delay_conditioning=False,
        include_tau_act_norm=False,
        include_command_state=False,
        include_active_command_error=False,
        include_phase_features=False,
        # QVEL is clipped to the registered seven-joint physical velocity
        # vector on every stage.  The delta cost is also part of the fixed
        # reward allowlist, including S0.
        arm_action_limiter=True,
        action_velocity_scale=1.0,
        action_delta_penalty_weight=0.0015,
        hit_min_count_interval=0.30,
        hit_reward_cap_mode="fixed",
        hit_reward_count_cap=12,
        # The fixed-contact reward below assigns one bounded event credit per
        # valid contact; it deliberately does not inherit the legacy
        # count-growing combo.  Keep the cap field aligned defensively even
        # though hit_reward_combo is zero in this profile.
        hit_reward_base=1.0,
        hit_reward_combo=0.0,
        hit_combo_count_cap=12,
        hit_reward_cap_target_interval=0.499,
        hit_cadence_target_interval=0.499,
        # Do not inherit the late V97 missed-publication population into S0.
        dr_rmp_target_update_hold_probability=0.0,
        dr_rmp_target_update_hold_tail_probability=0.0,
        # The fixed-contact reward is an explicit allowlist in _reward().
        # Disable the two positive terminal credits that are added outside
        # that function so the inherited V97 template cannot silently add a
        # second apex/episode objective to this new course.
        full_episode_completion_reward=0.0,
        full_episode_joint_height_reward_weight=0.0,
        rel_height_bonus_weight=0.0,
        post_hit_survival_reward_weight=0.0,
        horizon_sec=6.0,
        episode_racket_anchor_z_range_m=(0.0, 0.0),
        ball_view_x_bounds_m=(-0.35, 0.35),
        ball_view_y_bounds_m=(-0.70, -0.28),
        ball_view_z_bounds_m=(1.00, 1.45),
        terminate_on_ball_view_bounds=True,
        terminate_on_ball_view_x_bounds=True,
        terminate_on_ball_view_y_bounds=True,
        terminate_on_ball_view_z_low=True,
        terminate_on_ball_view_z_high=False,
        asymmetric_critic=True,
        critic_complete_dr_privileged=True,
        critic_command_history_steps=12,
    )

    phase_specs = (
        ("s0_tracking", (-0.30, 0.30), (-0.18, 0.18), True, 0, 0.0, 0.0),
        ("s1_center_single", (0.0, 0.0), (0.0, 0.0), False, 1, 0.0, 0.0),
        ("s2_xy_single", (-0.30, 0.30), (-0.18, 0.18), False, 1, 0.0, 0.0),
        ("s3_center_multi", (0.0, 0.0), (0.0, 0.0), False, 0, 0.20, 1.0),
        ("s4_xy_recovery", (-0.30, 0.30), (-0.18, 0.18), False, 0, 0.20, 1.0),
        ("s5_vision_dr", (-0.30, 0.30), (-0.18, 0.18), False, 0, 0.20, 1.0),
    )
    lesson_names = ("bridge", "commit", "consolidate")
    result: list[CurriculumStage] = []
    for phase_index, (
        phase,
        target_x,
        target_y,
        collision_disabled,
        terminate_hits,
        quality_floor_mix,
        return_weight,
    ) in enumerate(phase_specs):
        for lesson_index, lesson in enumerate(lesson_names):
            lesson_target_x = target_x
            lesson_target_y = target_y
            if lesson_index == 0 and phase_index in (0, 2, 4):
                lesson_target_x = (-0.15, 0.15)
                lesson_target_y = (-0.09, 0.09)
            values = dict(source_values)
            values.update(
                fixed_contact_training_phase=phase,
                fixed_contact_disable_ball_racket_collision=collision_disabled,
                fixed_contact_quality_reward_weight=(
                    0.0 if phase_index == 0 else 1.0
                ),
                fixed_contact_quality_joint_floor_mix=quality_floor_mix,
                fixed_contact_return_reward_weight=return_weight,
                fixed_contact_survival_reward_weight=(
                    0.0 if phase_index < 3 else 0.02
                ),
                fixed_contact_tracking_potential_weight=(
                    1.0 if phase_index == 0 else 0.0
                ),
                fixed_contact_final_brake_weight=(
                    0.25 if phase_index == 0 else 0.0
                ),
                horizon_sec=(0.50 if phase_index == 0 else 6.0),
                episode_target_x_range_m=lesson_target_x,
                episode_target_y_range_m=lesson_target_y,
                fixed_contact_xy_bin_sampling_enabled=(
                    phase_index in (0, 2, 4, 5)
                ),
                terminate_after_confirmed_hits=terminate_hits,
                ball_reset_mode="falling_contact",
                falling_reset_time_to_contact_range_s=(0.22, 0.36),
                falling_reset_apex_height_range_m=(0.285, 0.325),
                falling_reset_vxy_max=(0.0 if phase_index < 2 else 0.20),
                falling_reset_contact_xy_jitter=(
                    0.0 if phase_index < 2 else 0.010
                ),
                fixed_contact_high_ball_predictor_enabled=(phase_index == 5),
                early_termination_remaining_horizon_penalty=(
                    0.0 if phase_index == 0 else 30.0
                ),
            )
            if phase_index == 5:
                # Consolidation is an unchanged-domain repeat of commit.
                noise_scale = (0.50, 1.0, 1.0)[lesson_index]
                values.update(
                    dr_ball_mass_range=measured_mass_range,
                    dr_randomize_pd=True,
                    dr_randomize_recovered_rmp=True,
                    dr_damping_mult_range=(0.95, 1.05),
                    dr_armature_mult_range=(0.95, 1.05),
                    dr_randomize_racket_mount=True,
                    dr_racket_pos_offset_m=0.002,
                    dr_racket_rot_offset_rad=float(np.deg2rad(0.5)),
                    dr_racket_radius_offset_m=0.0,
                    dr_randomize_contact=True,
                    dr_ball_friction_range=(
                        0.90 * float(V33_CONTACT_PAIR_FRICTION[0]),
                        1.10 * float(V33_CONTACT_PAIR_FRICTION[0]),
                    ),
                    dr_racket_friction_range=(
                        0.90 * float(V33_CONTACT_PAIR_FRICTION[0]),
                        1.10 * float(V33_CONTACT_PAIR_FRICTION[0]),
                    ),
                    dr_ball_solref_time_range=(
                        0.95 * float(V33_CONTACT_PAIR_SOLREF[0]),
                        1.05 * float(V33_CONTACT_PAIR_SOLREF[0]),
                    ),
                    dr_ball_solref_damping_range=(
                        0.95 * float(V33_CONTACT_PAIR_SOLREF[1]),
                        1.05 * float(V33_CONTACT_PAIR_SOLREF[1]),
                    ),
                    dr_rmp_target_update_hold_probability=(
                        (0.050, 0.080, 0.080)[lesson_index]
                    ),
                    dr_rmp_target_update_hold_tail_probability=(
                        (0.011, 0.022, 0.022)[lesson_index]
                    ),
                    dr_rmp_target_update_hold_tail_steps_range=(2, 9),
                    dr_randomize_ball_obs_frame=True,
                    ball_obs_pos_noise_std=0.008 * noise_scale,
                    ball_obs_vel_noise_std=0.080 * noise_scale,
                    ball_obs_require_view_z_high=True,
                    # Treat the registered 1.45 m top as the hard outer
                    # envelope while randomizing the effective optical edge
                    # inward.  This makes nominal 1.40 m arcs exercise the
                    # same high-FOV handover used by the real predictor,
                    # instead of relying on accidental apex overshoot.
                    ball_obs_view_z_high_missing_range_m=(
                        (1.43, 1.45)
                        if lesson_index == 0
                        else (1.40, 1.45)
                    ),
                    ball_obs_view_bounds_missing_prob=1.0,
                    dr_ball_obs_pos_bias_base_m=(
                        0.007 * noise_scale,
                        0.007 * noise_scale,
                        0.007 * noise_scale,
                    ),
                    dr_ball_obs_rot_bias_deg=(0.0, 0.0, 0.0),
                    dr_ball_obs_vel_bias_base_m_s=(
                        0.070 * noise_scale,
                        0.070 * noise_scale,
                        0.100 * noise_scale,
                    ),
                    dr_ball_obs_scale_range=(
                        1.0 - 0.012 * noise_scale,
                        1.0 + 0.012 * noise_scale,
                    ),
                    lost_ball_timeout_ms=500.0,
                    # Start below the randomized optical edge.  The predictor
                    # must collect its causal history on the post-impact
                    # rising arc rather than fail-safe immediately at reset.
                    falling_reset_apex_height_range_m=(0.20, 0.24),
                )
            cfg = MjxFixedContactPlaneVisionConfig(**values)
            hit1_targets = (None, (0.80, 0.92, 0.95), (0.75, 0.85, 0.90))
            hit1_target = (
                hit1_targets[phase_index][lesson_index]
                if phase_index in (1, 2)
                else None
            )
            hit3_target = (
                (0.75, 0.85, 0.90)[lesson_index]
                if phase_index >= 3
                else None
            )
            if phase_index == 3:
                # Centered multi-hit first acquires three contacts, then
                # introduces nominal full-orbit survival progressively.
                hit12_target = (None, 0.50, 0.80)[lesson_index]
                mean_hits_target = (3.0, 8.0, 10.0)[lesson_index]
                mean_len_target = (0.30, 0.70, 0.88)[lesson_index]
                truncation_target = (0.20, 0.55, 0.80)[lesson_index]
            elif phase_index >= 4:
                # Wide/vision bridges require useful multi-hit recovery but
                # do not demand the 12-hit endpoint on first exposure.  The
                # commit/consolidation gates match the 12-event reward cap.
                hit12_target = (None, 0.75, 0.80)[lesson_index]
                mean_hits_target = (4.0, 9.0, 9.6)[lesson_index]
                mean_len_target = (0.38, 0.80, 0.90)[lesson_index]
                truncation_target = (0.20, 0.70, 0.90)[lesson_index]
            else:
                hit12_target = None
                mean_hits_target = 0.0 if phase_index == 0 else 0.90
                mean_len_target = 0.0
                truncation_target = None
            fixed_xy_bin_success_hit_count = (
                1
                if phase_index == 2
                else (
                    (3 if lesson_index == 0 else 12)
                    if phase_index in (4, 5)
                    else 0
                )
            )
            fixed_xy_bin_success_rate = (
                hit1_target
                if phase_index == 2
                else (
                    (0.60, 0.75, 0.80)[lesson_index]
                    if phase_index in (4, 5)
                    else None
                )
            )
            result.append(
                CurriculumStage(
                    name=f"s{phase_index}_{phase.removeprefix(f's{phase_index}_')}_{lesson}",
                    total_steps=source.total_steps,
                    cfg=cfg,
                    notes=(
                        "Independent fixed-contact-plane v1 course. The actor "
                        "starts from random initialization; V97 Stage 32 "
                        "contributes configuration/PPO defaults only. Fixed "
                        "seed evaluation must use every registered XY bin."
                    ),
                    target_mean_hits=mean_hits_target,
                    target_mean_len_frac=mean_len_target,
                    target_hit1_rate=hit1_target,
                    target_hit3_rate=hit3_target,
                    target_hit12_rate=hit12_target,
                    max_recent_mean_hit_racket_vxy=(
                        0.05 if phase_index >= 1 else None
                    ),
                    max_recent_hit_racket_angular_speed_rad_s=(
                        0.50 if phase_index >= 1 else None
                    ),
                    min_recent_fixed_contact_quality_components=(
                        None
                        if phase_index == 0
                        else (
                            (0.40,) * 5
                            if lesson_index == 0
                            else (float(np.exp(-0.5)),) * 5
                        )
                    ),
                    min_recent_fixed_contact_final_brake_score=(
                        (0.20, 0.40, 0.40)[lesson_index]
                        if phase_index == 0
                        else None
                    ),
                    fixed_contact_xy_bin_success_hit_count=(
                        fixed_xy_bin_success_hit_count
                    ),
                    min_advance_fixed_contact_xy_bin_success_rate=(
                        fixed_xy_bin_success_rate
                    ),
                    target_racket_up_cos=(
                        float(np.cos(np.deg2rad(5.0)))
                        if phase_index >= 1
                        else None
                    ),
                    max_recent_hit_next_contact_anchor_err=(
                        0.030 if phase_index == 3 else None
                    ),
                    min_recent_mean_hit_apex_abs_z_m=(
                        1.38 if phase_index >= 3 else None
                    ),
                    max_recent_mean_hit_apex_abs_z_m=(
                        1.42 if phase_index >= 3 else None
                    ),
                    target_min_hit_interval_s=(
                        0.44 if phase_index >= 3 else None
                    ),
                    target_max_hit_interval_s=(
                        0.56 if phase_index >= 3 else None
                    ),
                    hit_interval_gate_source=(
                        "counted_hit_event"
                        if phase_index >= 3
                        else "episode_duration_per_hit"
                    ),
                    target_episode_truncation_rate=truncation_target,
                    min_updates=30,
                    convergence_hold_updates=(8, 12, 16)[lesson_index],
                    max_updates=None,
                )
            )
    return result


def validate_fixed_contact_plane_v2_from_scratch(
    *,
    resume_path: str | Path | None,
    resume_curriculum_state: bool,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> None:
    """Keep V2 independent from the failed V1 policy and optimizer state."""

    validate_fixed_contact_plane_v1_from_scratch(
        resume_path=resume_path,
        resume_curriculum_state=resume_curriculum_state,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v2_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair S0 reward credit and fixed-workspace termination semantics."""

    validate_fixed_contact_plane_v2_from_scratch(
        resume_path=None,
        resume_curriculum_state=False,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source = _fixed_contact_plane_vision_robust_qvel_rmp_v1_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    s0_gates = (
        (0.35, 0.55, 0.45, 0.35, 0.35),
        (0.55, 0.65, 0.55, 0.50, 0.50),
        (0.65, 0.75, 0.65, 0.60, 0.60),
    )
    s0_xy_curriculum = (
        ((-0.10, -0.10), (0.03, 0.03), 1.00, 0.000, False),
        ((0.0, 0.0), (0.0, 0.0), 1.00, 0.000, True),
        ((-0.30, 0.30), (-0.18, 0.18), 0.35, 0.015, True),
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        phase_index = index // 3
        lesson_index = index % 3
        s0 = phase_index == 0
        (
            s0_target_x,
            s0_target_y,
            s0_center_probability,
            s0_jitter_m,
            s0_bin_sampling,
        ) = s0_xy_curriculum[lesson_index]
        cfg = replace(
            stage.cfg,
            fixed_contact_reward_mode="fixed_contact_additive_s0_v2",
            fixed_contact_workspace_termination_penalty_enabled=True,
            # The racket mesh uses size[0] as its one-millimetre half
            # thickness; size[1:3] are the 75 mm in-plane radii.  V1 used
            # size[1] along the site normal and displaced the represented
            # upper surface by 75 mm.
            fixed_contact_racket_surface_size_axis=0,
            # A collision-disabled falling-ball tracking lesson cannot earn a
            # hit.  Charging V1's no-hit miss event made the intended behavior
            # about two orders of magnitude worse than the largest obtainable
            # tracking credit and created an incentive to terminate elsewhere.
            termination_miss_penalty_requires_hit=(
                True if s0 else stage.cfg.termination_miss_penalty_requires_hit
            ),
            # Trial A (256 envs, 120 updates) learned the easy Z, pose and
            # braking components but left the requested XY lane unchanged.
            # Keep the absolute XY score as the settle objective and add this
            # bounded, telescoping progress credit so every step toward the
            # dynamic contact point has an immediate signed advantage.
            fixed_contact_tracking_potential_weight=(20.0 if s0 else 0.0),
            fixed_contact_final_brake_weight=0.0,
            # Trial C showed a stable four-of-five solution whose final XY
            # error remained about 0.11 m: the old 0.12 m reward sigma still
            # paid strongly there despite the unchanged 0.04 m gate sigma.
            # Tighten only this failed component and raise its opportunity
            # relative to the already-solved Z/pose/braking objectives.
            fixed_contact_s0_xy_reward_weight=(4.0 if s0 else 0.0),
            fixed_contact_s0_z_reward_weight=(0.50 if s0 else 0.0),
            fixed_contact_s0_pose_reward_weight=(0.75 if s0 else 0.0),
            fixed_contact_s0_vxy_reward_weight=(1.25 if s0 else 0.0),
            fixed_contact_s0_omega_reward_weight=(0.75 if s0 else 0.0),
            fixed_contact_s0_xy_reward_sigma_m=0.060,
            fixed_contact_s0_z_reward_sigma_m=0.040,
            fixed_contact_s0_pose_reward_sigma_rad=float(np.deg2rad(10.0)),
            fixed_contact_s0_vxy_reward_sigma_m_s=0.250,
            fixed_contact_s0_omega_reward_sigma_rad_s=1.50,
            fixed_contact_s0_xy_gate_sigma_m=0.040,
            fixed_contact_s0_z_gate_sigma_m=0.020,
            fixed_contact_s0_pose_gate_sigma_rad=float(np.deg2rad(5.0)),
            fixed_contact_s0_vxy_gate_sigma_m_s=0.120,
            fixed_contact_s0_omega_gate_sigma_rad_s=1.00,
            # Random initialization first learns to settle at the warm-reset
            # neighbourhood, then move to the registered center, and only
            # then target-condition over the complete S0 workspace. Trials
            # A--F showed that starting directly at the center or a 3x3 grid
            # left the seven-DOF policy in a short-of-target local optimum.
            episode_target_x_range_m=(
                s0_target_x if s0 else stage.cfg.episode_target_x_range_m
            ),
            episode_target_y_range_m=(
                s0_target_y if s0 else stage.cfg.episode_target_y_range_m
            ),
            fixed_contact_xy_bin_sampling_enabled=(
                s0_bin_sampling
                if s0
                else stage.cfg.fixed_contact_xy_bin_sampling_enabled
            ),
            fixed_contact_xy_center_probability=(
                s0_center_probability
                if s0
                else stage.cfg.fixed_contact_xy_center_probability
            ),
            fixed_contact_xy_bin_jitter_m=(
                s0_jitter_m
                if s0
                else stage.cfg.fixed_contact_xy_bin_jitter_m
            ),
        )
        result.append(
            replace(
                stage,
                cfg=cfg,
                notes=(
                    "Fixed-contact-plane V2 preserves V1 observation, "
                    "control, physics and S1--S5 task rewards. It repairs "
                    "fixed XYZ workspace termination credit and replaces "
                    "S0's vanishing product reward with five additive "
                    "component signals. "
                    + stage.notes
                ),
                min_recent_fixed_contact_final_brake_score=None,
                min_recent_fixed_contact_s0_components=(
                    s0_gates[lesson_index] if s0 else None
                ),
            )
        )
    return result


def validate_fixed_contact_plane_v3_from_scratch(
    *,
    resume_path: str | Path | None,
    resume_curriculum_state: bool,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> None:
    """Keep the timed-intercept experiment independent from V1/V2 state."""

    validate_fixed_contact_plane_v2_from_scratch(
        resume_path=resume_path,
        resume_curriculum_state=resume_curriculum_state,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v3_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach deadline-conditioned contact readiness before any collision."""

    validate_fixed_contact_plane_v3_from_scratch(
        resume_path=None,
        resume_curriculum_state=False,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source = _fixed_contact_plane_vision_robust_qvel_rmp_v2_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    template = source[0]
    # Targets are registered-center offsets in metres.  The first six lessons
    # replace V2's single 104 mm jump with 25 mm increments.  Later lessons
    # expand absolute support while the final lesson restores the real
    # 220--360 ms deadline before collision can be enabled.
    timed_specs = (
        (
            "s0_timed_anchor_hold",
            (-0.100, -0.100),
            (0.0300, 0.0300),
            (0.45, 0.55),
            False,
            0.65,
            (0.45, 0.55, 0.45, 0.40, 0.40),
            0.10,
        ),
        (
            "s0_timed_step_025",
            (-0.075, -0.075),
            (0.0225, 0.0225),
            (0.42, 0.52),
            False,
            0.62,
            (0.45, 0.55, 0.45, 0.40, 0.40),
            0.12,
        ),
        (
            "s0_timed_step_050",
            (-0.050, -0.050),
            (0.0150, 0.0150),
            (0.40, 0.50),
            False,
            0.60,
            (0.48, 0.58, 0.48, 0.42, 0.42),
            0.15,
        ),
        (
            "s0_timed_step_075",
            (-0.025, -0.025),
            (0.0075, 0.0075),
            (0.38, 0.48),
            False,
            0.58,
            (0.50, 0.60, 0.50, 0.45, 0.45),
            0.18,
        ),
        (
            "s0_timed_center_long",
            (0.0, 0.0),
            (0.0, 0.0),
            (0.36, 0.46),
            False,
            0.56,
            (0.55, 0.65, 0.55, 0.50, 0.50),
            0.25,
        ),
        (
            "s0_timed_center_real",
            (0.0, 0.0),
            (0.0, 0.0),
            (0.22, 0.36),
            False,
            0.50,
            (0.55, 0.65, 0.55, 0.50, 0.50),
            0.30,
        ),
        (
            "s0_timed_inner_grid",
            (-0.15, 0.15),
            (-0.09, 0.09),
            (0.32, 0.44),
            True,
            0.54,
            (0.52, 0.62, 0.52, 0.48, 0.48),
            0.20,
        ),
        (
            "s0_timed_mid_grid",
            (-0.22, 0.22),
            (-0.14, 0.14),
            (0.38, 0.50),
            True,
            0.60,
            (0.50, 0.60, 0.50, 0.45, 0.45),
            0.15,
        ),
        (
            "s0_timed_full_grid_long",
            (-0.30, 0.30),
            (-0.18, 0.18),
            (0.45, 0.55),
            True,
            0.65,
            (0.48, 0.58, 0.48, 0.42, 0.42),
            0.12,
        ),
        (
            "s0_timed_full_grid_real",
            (-0.30, 0.30),
            (-0.18, 0.18),
            (0.22, 0.36),
            True,
            0.50,
            (0.45, 0.55, 0.45, 0.40, 0.40),
            0.10,
        ),
    )
    timed_stages: list[CurriculumStage] = []
    for (
        name,
        target_x,
        target_y,
        contact_time,
        bin_sampling,
        horizon_s,
        component_gates,
        ready_fraction,
    ) in timed_specs:
        cfg = replace(
            template.cfg,
            fixed_contact_reward_mode="fixed_contact_timed_intercept_v3",
            fixed_contact_tracking_potential_weight=4.0,
            fixed_contact_final_window_s=0.100,
            fixed_contact_s0_xy_reward_weight=1.50,
            fixed_contact_s0_z_reward_weight=0.25,
            fixed_contact_s0_pose_reward_weight=0.25,
            fixed_contact_s0_vxy_reward_weight=1.50,
            fixed_contact_s0_omega_reward_weight=0.75,
            fixed_contact_s0_xy_reward_sigma_m=0.100,
            fixed_contact_s0_z_reward_sigma_m=0.040,
            fixed_contact_s0_pose_reward_sigma_rad=float(np.deg2rad(10.0)),
            fixed_contact_s0_vxy_reward_sigma_m_s=0.150,
            fixed_contact_s0_omega_reward_sigma_rad_s=1.00,
            fixed_contact_s0_final_xy_reward_weight=8.0,
            fixed_contact_s0_final_z_reward_weight=1.0,
            fixed_contact_s0_final_pose_reward_weight=1.5,
            fixed_contact_s0_final_xy_reward_sigma_m=0.020,
            fixed_contact_s0_final_z_reward_sigma_m=0.010,
            fixed_contact_s0_final_pose_reward_sigma_rad=float(
                np.deg2rad(3.0)
            ),
            fixed_contact_s0_readiness_bonus_weight=5.0,
            fixed_contact_s0_ready_max_xy_error_m=0.020,
            fixed_contact_s0_ready_max_z_error_m=0.010,
            fixed_contact_s0_ready_max_pose_error_rad=float(np.deg2rad(3.0)),
            fixed_contact_s0_ready_max_vxy_m_s=0.080,
            fixed_contact_s0_ready_max_omega_rad_s=0.75,
            fixed_contact_s0_xy_gate_sigma_m=0.015,
            fixed_contact_s0_z_gate_sigma_m=0.008,
            fixed_contact_s0_pose_gate_sigma_rad=float(np.deg2rad(2.0)),
            fixed_contact_s0_vxy_gate_sigma_m_s=0.060,
            fixed_contact_s0_omega_gate_sigma_rad_s=0.50,
            episode_target_x_range_m=target_x,
            episode_target_y_range_m=target_y,
            fixed_contact_xy_bin_sampling_enabled=bin_sampling,
            fixed_contact_xy_center_probability=(0.35 if bin_sampling else 1.0),
            fixed_contact_xy_bin_jitter_m=0.0,
            falling_reset_time_to_contact_range_s=contact_time,
            horizon_sec=horizon_s,
        )
        timed_stages.append(
            replace(
                template,
                name=name,
                cfg=cfg,
                notes=(
                    "V3 collision-off timed-intercept prerequisite.  Broad "
                    "approach shaping remains additive, while tight "
                    "deadline rewards and a simultaneous physical-readiness "
                    "fraction prevent partial approach from graduating."
                ),
                min_recent_fixed_contact_s0_components=component_gates,
                min_recent_fixed_contact_s0_ready_fraction=ready_fraction,
                convergence_hold_updates=(12 if "real" in name else 8),
                min_updates=30,
                max_updates=None,
            )
        )
    return timed_stages + source[3:]


def validate_fixed_contact_plane_v4_from_scratch(
    *,
    resume_path: str | Path | None,
    resume_curriculum_state: bool,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> None:
    """Keep the direct collision-on A/B branch independent from V1--V3."""

    validate_fixed_contact_plane_v3_from_scratch(
        resume_path=resume_path,
        resume_curriculum_state=resume_curriculum_state,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v4_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Train collision-on juggling from full-workspace racket resets.

    Absolute reset coverage and required per-contact displacement are separate
    variables: every lesson samples the complete empirically reachable 6x6
    rectangular grid and continuously jitters between its nodes, while
    the initial falling contact expands only from zero to a bounded 42 mm
    diagonal displacement.  The dynamic ContactTarget retains its independent
    50 mm per-bounce center-return cap.
    """

    validate_fixed_contact_plane_v4_from_scratch(
        resume_path=None,
        resume_curriculum_state=False,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source = _fixed_contact_plane_vision_robust_qvel_rmp_v2_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source_stages = (
        *source[3:6],
        *source[9:12],
        *source[15:18],
    )
    names = (
        "direct_full_grid_single_aligned",
        "direct_full_grid_single_near",
        "direct_full_grid_single_bounded",
        "direct_full_grid_multi_bridge",
        "direct_full_grid_multi_commit",
        "direct_full_grid_multi_full",
        "direct_full_grid_vision_bridge",
        "direct_full_grid_vision_commit",
        "direct_full_grid_vision_full",
    )
    contact_jitter_m = (
        0.000,
        0.015,
        0.030,
        0.010,
        0.020,
        0.030,
        0.020,
        0.025,
        0.030,
    )
    incoming_vxy_m_s = (
        0.00,
        0.05,
        0.10,
        0.05,
        0.10,
        0.20,
        0.20,
        0.20,
        0.20,
    )
    contact_time_ranges_s = (
        (0.40, 0.52),
        (0.30, 0.44),
        (0.22, 0.36),
        (0.30, 0.44),
        (0.24, 0.38),
        (0.22, 0.36),
        (0.22, 0.36),
        (0.22, 0.36),
        (0.22, 0.36),
    )
    component_gates = (
        (0.35, 0.45, 0.35, 0.25, 0.30),
        (0.40, 0.50, 0.40, 0.30, 0.35),
        (0.45, 0.55, 0.45, 0.35, 0.40),
        (0.40, 0.50, 0.40, 0.30, 0.35),
        (0.45, 0.55, 0.45, 0.35, 0.40),
        (0.50, 0.60, 0.50, 0.40, 0.45),
        (0.40, 0.50, 0.40, 0.30, 0.35),
        (0.45, 0.55, 0.45, 0.35, 0.40),
        (0.50, 0.60, 0.50, 0.40, 0.45),
    )
    ready_fractions = (0.04, 0.06, 0.08, 0.05, 0.08, 0.10, 0.05, 0.08, 0.10)
    xy_bin_hit_counts = (1, 1, 1, 3, 12, 12, 3, 12, 12)
    xy_bin_success_rates = (0.45, 0.55, 0.65, 0.45, 0.55, 0.70, 0.45, 0.55, 0.70)
    hit1_rates = (0.70, 0.80, 0.88, None, None, None, None, None, None)
    hit3_rates = (None, None, None, 0.65, 0.80, 0.90, 0.60, 0.78, 0.88)
    hit12_rates = (None, None, None, None, 0.45, 0.75, None, 0.45, 0.75)
    mean_hits = (0.70, 0.80, 0.88, 3.0, 7.5, 9.6, 3.0, 7.5, 9.6)
    mean_len = (0.0, 0.0, 0.0, 0.30, 0.65, 0.88, 0.30, 0.65, 0.88)
    truncation_rates = (None, None, None, 0.15, 0.50, 0.82, 0.15, 0.50, 0.82)
    quality_reward_weights = (6.0, 6.0, 6.0, 4.0, 4.0, 4.0, 4.0, 4.0, 4.0)
    miss_penalty_weights = (8.0, 8.0, 8.0, 20.0, 20.0, 20.0, 30.0, 30.0, 30.0)
    result: list[CurriculumStage] = []
    for index, (source_stage, name) in enumerate(
        zip(source_stages, names, strict=True)
    ):
        cfg = replace(
            source_stage.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_reward_mode="fixed_contact_timed_intercept_v3",
            fixed_contact_disable_ball_racket_collision=False,
            episode_target_x_range_m=(-0.30, 0.20),
            episode_target_y_range_m=(-0.12, 0.18),
            fixed_contact_xy_bin_sampling_enabled=True,
            fixed_contact_xy_center_probability=0.20,
            fixed_contact_xy_bin_jitter_m=0.050,
            fixed_contact_xy_equal_bin_evaluation=False,
            falling_reset_racket_follow_contact_y=False,
            falling_reset_racket_follow_episode_target_xy=True,
            falling_reset_contact_xy_jitter=contact_jitter_m[index],
            falling_reset_contact_clip_to_fixed_workspace=True,
            falling_reset_vxy_max=incoming_vxy_m_s[index],
            falling_reset_time_to_contact_range_s=contact_time_ranges_s[index],
            terminate_after_confirmed_hits=(1 if index < 3 else 0),
            early_termination_remaining_horizon_penalty=(
                miss_penalty_weights[index]
            ),
            fixed_contact_quality_reward_weight=(
                quality_reward_weights[index]
            ),
            fixed_contact_tracking_potential_weight=4.0,
            fixed_contact_final_window_s=0.100,
            fixed_contact_s0_xy_reward_weight=2.00,
            fixed_contact_s0_z_reward_weight=2.00,
            fixed_contact_s0_pose_reward_weight=2.00,
            fixed_contact_s0_vxy_reward_weight=4.00,
            fixed_contact_s0_omega_reward_weight=3.00,
            fixed_contact_s0_xy_reward_sigma_m=0.100,
            fixed_contact_s0_z_reward_sigma_m=0.040,
            fixed_contact_s0_pose_reward_sigma_rad=float(np.deg2rad(10.0)),
            fixed_contact_s0_vxy_reward_sigma_m_s=0.150,
            fixed_contact_s0_omega_reward_sigma_rad_s=1.00,
            fixed_contact_s0_final_xy_reward_weight=8.0,
            fixed_contact_s0_final_z_reward_weight=5.0,
            fixed_contact_s0_final_pose_reward_weight=5.0,
            fixed_contact_s0_final_xy_reward_sigma_m=0.020,
            fixed_contact_s0_final_z_reward_sigma_m=0.010,
            fixed_contact_s0_final_pose_reward_sigma_rad=float(
                np.deg2rad(3.0)
            ),
            fixed_contact_s0_readiness_bonus_weight=10.0,
            fixed_contact_s0_ready_max_xy_error_m=0.020,
            fixed_contact_s0_ready_max_z_error_m=0.010,
            fixed_contact_s0_ready_max_pose_error_rad=float(np.deg2rad(3.0)),
            fixed_contact_s0_ready_max_vxy_m_s=0.080,
            fixed_contact_s0_ready_max_omega_rad_s=0.75,
            fixed_contact_s0_xy_gate_sigma_m=0.015,
            fixed_contact_s0_z_gate_sigma_m=0.008,
            fixed_contact_s0_pose_gate_sigma_rad=float(np.deg2rad(2.0)),
            fixed_contact_s0_vxy_gate_sigma_m_s=0.060,
            fixed_contact_s0_omega_gate_sigma_rad_s=0.50,
        )
        result.append(
            replace(
                source_stage,
                name=name,
                cfg=cfg,
                notes=(
                    "V4 collision-on A/B course. Every reset initializes the "
                    "racket from a dense pose-preserving IK table across the "
                    "complete reachable 6x6 absolute workspace grid. Initial "
                    "relative contact displacement "
                    "is separately bounded, and every stage retains dense "
                    "target approach, pose, velocity and readiness reward."
                ),
                target_mean_hits=mean_hits[index],
                target_mean_len_frac=mean_len[index],
                target_hit1_rate=hit1_rates[index],
                target_hit3_rate=hit3_rates[index],
                target_hit12_rate=hit12_rates[index],
                target_episode_truncation_rate=truncation_rates[index],
                min_recent_fixed_contact_s0_components=component_gates[index],
                min_recent_fixed_contact_s0_ready_fraction=(
                    ready_fractions[index]
                ),
                fixed_contact_xy_bin_success_hit_count=(
                    xy_bin_hit_counts[index]
                ),
                min_advance_fixed_contact_xy_bin_success_rate=(
                    xy_bin_success_rates[index]
                ),
                min_updates=30,
                convergence_hold_updates=(8, 12, 16)[index % 3],
                max_updates=None,
            )
        )
    return result


def validate_fixed_contact_plane_v5_from_scratch(
    *,
    resume_path: str | Path | None,
    resume_curriculum_state: bool,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> None:
    """Keep the target-conditioned GPU0 repair independent from V1--V4."""

    validate_fixed_contact_plane_v3_from_scratch(
        resume_path=resume_path,
        resume_curriculum_state=resume_curriculum_state,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v5_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach target-conditioned readiness through nested random supports."""

    validate_fixed_contact_plane_v5_from_scratch(
        resume_path=None,
        resume_curriculum_state=False,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source = _fixed_contact_plane_vision_robust_qvel_rmp_v2_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    template = source[0]
    conditioned_specs = (
        (
            "s0_conditioned_local_random",
            (-0.14, -0.09),
            (0.00, 0.05),
            (0.45, 0.55),
            False,
            0.65,
            (0.40, 0.55, 0.40, 0.35, 0.35),
            0.08,
        ),
        (
            "s0_conditioned_near_random",
            (-0.18, -0.04),
            (-0.04, 0.08),
            (0.42, 0.52),
            False,
            0.62,
            (0.42, 0.56, 0.42, 0.36, 0.36),
            0.10,
        ),
        (
            "s0_conditioned_center_bridge",
            (-0.18, 0.04),
            (-0.08, 0.10),
            (0.40, 0.50),
            False,
            0.60,
            (0.44, 0.58, 0.44, 0.38, 0.38),
            0.12,
        ),
        (
            "s0_conditioned_inner_grid",
            (-0.18, 0.15),
            (-0.09, 0.10),
            (0.36, 0.48),
            True,
            0.58,
            (0.46, 0.60, 0.46, 0.40, 0.40),
            0.14,
        ),
        (
            "s0_conditioned_mid_grid",
            (-0.22, 0.22),
            (-0.14, 0.14),
            (0.38, 0.50),
            True,
            0.60,
            (0.46, 0.60, 0.46, 0.40, 0.40),
            0.14,
        ),
        (
            "s0_conditioned_full_grid_long",
            (-0.30, 0.30),
            (-0.18, 0.18),
            (0.45, 0.55),
            True,
            0.65,
            (0.44, 0.58, 0.44, 0.38, 0.38),
            0.12,
        ),
        (
            "s0_conditioned_full_grid_real",
            (-0.30, 0.30),
            (-0.18, 0.18),
            (0.22, 0.36),
            True,
            0.50,
            (0.42, 0.56, 0.42, 0.36, 0.36),
            0.10,
        ),
    )
    conditioned_stages: list[CurriculumStage] = []
    for (
        name,
        target_x,
        target_y,
        contact_time,
        bin_sampling,
        horizon_s,
        component_gates,
        ready_fraction,
    ) in conditioned_specs:
        cfg = replace(
            template.cfg,
            fixed_contact_reward_mode="fixed_contact_timed_intercept_v3",
            fixed_contact_tracking_potential_weight=10.0,
            fixed_contact_final_window_s=0.100,
            fixed_contact_s0_xy_reward_weight=2.00,
            fixed_contact_s0_z_reward_weight=2.00,
            fixed_contact_s0_pose_reward_weight=2.00,
            fixed_contact_s0_vxy_reward_weight=4.00,
            fixed_contact_s0_omega_reward_weight=3.00,
            fixed_contact_s0_xy_reward_sigma_m=0.100,
            fixed_contact_s0_z_reward_sigma_m=0.040,
            fixed_contact_s0_pose_reward_sigma_rad=float(np.deg2rad(10.0)),
            fixed_contact_s0_vxy_reward_sigma_m_s=0.150,
            fixed_contact_s0_omega_reward_sigma_rad_s=1.00,
            fixed_contact_s0_final_xy_reward_weight=8.0,
            fixed_contact_s0_final_z_reward_weight=5.0,
            fixed_contact_s0_final_pose_reward_weight=5.0,
            fixed_contact_s0_final_xy_reward_sigma_m=0.020,
            fixed_contact_s0_final_z_reward_sigma_m=0.010,
            fixed_contact_s0_final_pose_reward_sigma_rad=float(
                np.deg2rad(3.0)
            ),
            fixed_contact_s0_readiness_bonus_weight=10.0,
            fixed_contact_s0_ready_max_xy_error_m=0.020,
            fixed_contact_s0_ready_max_z_error_m=0.010,
            fixed_contact_s0_ready_max_pose_error_rad=float(np.deg2rad(3.0)),
            fixed_contact_s0_ready_max_vxy_m_s=0.080,
            fixed_contact_s0_ready_max_omega_rad_s=0.75,
            fixed_contact_s0_xy_gate_sigma_m=0.015,
            fixed_contact_s0_z_gate_sigma_m=0.008,
            fixed_contact_s0_pose_gate_sigma_rad=float(np.deg2rad(2.0)),
            fixed_contact_s0_vxy_gate_sigma_m_s=0.060,
            fixed_contact_s0_omega_gate_sigma_rad_s=0.50,
            episode_target_x_range_m=target_x,
            episode_target_y_range_m=target_y,
            fixed_contact_xy_bin_sampling_enabled=bin_sampling,
            fixed_contact_xy_center_probability=(0.25 if bin_sampling else 1.0),
            fixed_contact_xy_bin_jitter_m=(0.015 if bin_sampling else 0.0),
            falling_reset_time_to_contact_range_s=contact_time,
            horizon_sec=horizon_s,
        )
        conditioned_stages.append(
            replace(
                template,
                name=name,
                cfg=cfg,
                notes=(
                    "V5 collision-off target-conditioned prerequisite. Each "
                    "episode samples a target from a nested support that "
                    "contains the preceding lesson, preventing a constant "
                    "action from solving the curriculum while preserving "
                    "the physical simultaneous-readiness gate."
                ),
                min_recent_fixed_contact_s0_components=component_gates,
                min_recent_fixed_contact_s0_ready_fraction=ready_fraction,
                convergence_hold_updates=(12 if "real" in name else 8),
                min_updates=30,
                max_updates=None,
            )
        )
    return conditioned_stages + source[3:]


def _fixed_contact_plane_vision_robust_qvel_rmp_v6_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Align direct-juggling contact-speed credit with its physical gate."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v4_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("direct_", "direct_v6_", 1)
        cfg = replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            hit_racket_vxy_soft_limit_m_s=0.050,
            hit_racket_vxy_penalty_weight=2.0,
            hit_racket_vxy_penalty_scale_m_s=0.050,
            fixed_contact_s0_vxy_reward_weight=6.0,
        )
        result.append(
            replace(
                stage,
                name=name,
                cfg=cfg,
                notes=(
                    f"{stage.notes} V6 reward-gate repair: the contact-event "
                    "racket-vxy soft limit now equals the unchanged 0.05 m/s "
                    "graduation gate, and its penalty plus dense final-window "
                    "credit are strengthened."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v7_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Preserve V5 while continuing its Stage-2 policy with quieter PPO."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v5_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=f"v7_{stage.name}",
            notes=(
                f"{stage.notes} V7 preserves this environment, reward and "
                "gate exactly; only the launcher-level PPO/exploration "
                "settings change for the pinned V5 precision continuation."
            ),
        )
        for stage in source
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v8_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Insert one nested target-support bridge before V5's large jump."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v5_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed = [
        replace(
            stage,
            name=f"v8_{stage.name}",
            notes=f"{stage.notes} Preserved exactly by V8.",
        )
        for stage in source
    ]
    bridge_source = source[0]
    bridge_cfg = replace(
        bridge_source.cfg,
        episode_target_x_range_m=(-0.16, -0.07),
        episode_target_y_range_m=(-0.02, 0.07),
        falling_reset_time_to_contact_range_s=(0.44, 0.54),
        horizon_sec=0.64,
    )
    bridge = replace(
        bridge_source,
        name="v8_s0_conditioned_support_bridge",
        cfg=bridge_cfg,
        notes=(
            "V8 GPU0 precision bridge. It expands V5 Stage-1 target area "
            "from 0.0025 to 0.0081 m^2 before the unchanged 0.0168 m^2 "
            "Stage-2 support. Reward, physical readiness and Stage-1 gates "
            "remain unchanged."
        ),
    )
    return [renamed[0], bridge, *renamed[1:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v9_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Cap impossible transfer floors only for one-hit success lessons."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v6_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        short_success = int(stage.cfg.terminate_after_confirmed_hits) > 0
        result.append(
            replace(
                stage,
                name=stage.name.replace("direct_v6_", "direct_v9_", 1),
                notes=(
                    f"{stage.notes} V9 preserves this task and enables the "
                    "stage-target cap on the global transfer minimum only "
                    "when success terminates the episode after one hit."
                ),
                advance_transfer_cap_min_hits_at_stage_target=short_success,
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v10_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Sharpen only the dense XY signal in collision-off precision lessons."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v8_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        cfg = stage.cfg
        if cfg.fixed_contact_disable_ball_racket_collision:
            cfg = replace(
                cfg,
                fixed_contact_s0_xy_reward_sigma_m=0.060,
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v8_", "v10_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V10 changes only the collision-off dense "
                    "XY reward sigma from 0.100 m to 0.060 m so the sole "
                    "failed precision component retains gradient near the "
                    "unchanged 0.015 m gate scale."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v11_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Factor the failed V8 bridge-to-near jump into X then Y expansion."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v8_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed = [
        replace(
            stage,
            name=stage.name.replace("v8_", "v11_", 1),
            notes=f"{stage.notes} Preserved exactly by V11.",
        )
        for stage in source
    ]
    bridge_source = source[1]
    bridge_cfg = replace(
        bridge_source.cfg,
        episode_target_x_range_m=(-0.18, -0.04),
    )
    bridge = replace(
        bridge_source,
        name="v11_s0_conditioned_x_support_bridge",
        cfg=bridge_cfg,
        notes=(
            "V11 factorized-support bridge. Starting from the passed V8 "
            "0.0081 m^2 bridge, it expands only X to the unchanged V5 "
            "near-support range while holding Y fixed. The following stage "
            "then expands only Y. Reward, gates, observation, control, "
            "physics and DR are unchanged."
        ),
    )
    return [renamed[0], renamed[1], bridge, *renamed[2:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Continue V11 and split the remaining Y expansion in half."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v11_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed = [
        replace(
            stage,
            name=stage.name.replace("v11_", "v12_", 1),
            notes=f"{stage.notes} Preserved exactly by V12.",
        )
        for stage in source
    ]
    bridge_source = source[2]
    bridge_cfg = replace(
        bridge_source.cfg,
        episode_target_y_range_m=(-0.03, 0.075),
    )
    bridge = replace(
        bridge_source,
        name="v12_s0_conditioned_y_support_bridge",
        cfg=bridge_cfg,
        notes=(
            "V12 second factorized-support bridge. X remains at the full "
            "near-support range while Y expands halfway from the V8 bridge "
            "to the original V5 near-support range. Reward, gates, "
            "observation, control, physics and DR are unchanged."
        ),
    )
    return [renamed[0], renamed[1], renamed[2], bridge, *renamed[3:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v13_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Give collision-off target conditioning a stronger final XY signal."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        cfg = stage.cfg
        if cfg.fixed_contact_disable_ball_racket_collision:
            cfg = replace(
                cfg,
                fixed_contact_s0_final_xy_reward_weight=16.0,
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v12_", "v13_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V13 changes only the collision-off final-"
                    "window XY reward weight from 8.0 to 16.0. This makes "
                    "target-conditioned precision more valuable than the "
                    "observed stable center-of-support compromise while "
                    "preserving every gate and physical contract."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v14_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Replace the half-Y bridge's center shortcut with balanced endpoints."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        cfg = stage.cfg
        if index == 3:
            cfg = replace(
                cfg,
                fixed_contact_xy_bin_sampling_enabled=True,
                fixed_contact_xy_center_probability=0.0,
                fixed_contact_xy_bin_jitter_m=0.0,
                fixed_contact_eval_grid_x_m=(
                    -0.18,
                    -0.145,
                    -0.11,
                    -0.075,
                    -0.04,
                ),
                fixed_contact_eval_grid_y_m=(-0.03, 0.075),
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v12_", "v14_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V14 preserves reward, gates and physics. "
                    "In the half-Y bridge only, it uniformly samples ten "
                    "Cartesian combinations spanning five X values and both "
                    "Y endpoints with no center prior or jitter. The next "
                    "lesson restores the original continuous near support."
                    if index == 3
                    else f"{stage.notes} Preserved exactly by V14."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v15_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Scale only the seven target-conditioning inputs by ten."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=stage.name.replace("v12_", "v15_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_actor_observation_schema=(
                    FIXED_CONTACT_ACTOR_OBSERVATION_SCHEMA_V15
                ),
            ),
            notes=(
                f"{stage.notes} V15 changes only the versioned actor input "
                "encoding: the contact-position error and the two target-XY "
                "offset pairs are multiplied by 10 before the unchanged "
                "80-D actor. Absolute target/racket state, reward, gates, "
                "sampling, control, physics and DR are unchanged."
            ),
        )
        for stage in source
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v16_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Pair tenfold target scaling with an equivalent input-layer migration."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=stage.name.replace("v12_", "v16_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_actor_observation_schema=(
                    FIXED_CONTACT_ACTOR_OBSERVATION_SCHEMA_V16
                ),
            ),
            notes=(
                f"{stage.notes} V16 multiplies the seven direct target-"
                "conditioning channels by 10 and inversely migrates their "
                "actor/critic input weights, so the inherited policy/value "
                "functions are unchanged before PPO resumes. Adam moments "
                "are transformed into the new coordinates. Reward, gates, "
                "sampling, control, physics and DR are unchanged."
            ),
        )
        for stage in source
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v17_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Raise only collision-off target-progress shaping to task scale."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        cfg = stage.cfg
        if cfg.fixed_contact_disable_ball_racket_collision:
            cfg = replace(
                cfg,
                fixed_contact_tracking_potential_weight=100.0,
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v12_", "v17_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V17 changes only collision-off target-"
                    "progress potential weight from 10 to 100. A net 1 cm "
                    "approach is therefore worth about 1 reward, while the "
                    "telescoping form prevents back-and-forth reward farming. "
                    "Terminal precision, velocity/orientation gates, actor "
                    "schema, sampling, control, physics and DR are unchanged."
                    if stage.cfg.fixed_contact_disable_ball_racket_collision
                    else f"{stage.notes} Preserved exactly by V17."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v18_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Split V12's rejected Y-support jump into four nested micro-rungs."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed = [
        replace(
            stage,
            name=stage.name.replace("v12_", "v18_", 1),
            notes=f"{stage.notes} Preserved exactly by V18.",
        )
        for stage in source
    ]
    bridge_source = source[3]
    y_ranges = (
        (-0.0225, 0.07125),
        (-0.0250, 0.07250),
        (-0.0275, 0.07375),
        (-0.0300, 0.07500),
    )
    micro_stages = [
        replace(
            bridge_source,
            name=f"v18_s0_conditioned_y_micro_{index}",
            cfg=replace(
                bridge_source.cfg,
                episode_target_y_range_m=y_range,
            ),
            notes=(
                f"V18 nested Y-support rung {index}/4: Y={y_range} m. "
                "Each rung expands the preceding width by about four percent "
                "while retaining the original 15 mm precision, simultaneous "
                "readiness, reward, observation, control, physics and DR "
                "contracts."
            ),
        )
        for index, y_range in enumerate(y_ranges, start=1)
    ]
    return [*renamed[:3], *micro_stages, *renamed[4:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v19_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair the S0 time budget while preserving the juggling course.

    V5--V18 declared several 0.36--0.55 s positioning lessons, but the shared
    descending-only reset silently clipped all of them to roughly 0.24 s for
    the registered 1.40 m orbit.  V19 lets collision-off S0 resets start on
    the rising half of that *same* orbit, so the actor receives the declared
    time to move and brake.  Collision-on single/multi-hit stages are bitwise
    unchanged.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v18_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        cfg = stage.cfg
        if cfg.fixed_contact_disable_ball_racket_collision:
            time_lo, time_hi = (
                float(value)
                for value in cfg.falling_reset_time_to_contact_range_s
            )
            cfg = replace(
                cfg,
                fixed_contact_reward_mode=(
                    "fixed_contact_full_flight_timed_intercept_v19"
                ),
                # A 1.40 m apex over the 1.095 m ball-center contact plane
                # gives a 0.499 s same-height flight.  Keep a small numerical
                # margin instead of sampling an impossible 0.50--0.55 s tail.
                falling_reset_time_to_contact_range_s=(
                    time_lo,
                    min(time_hi, 0.49),
                ),
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v18_", "v19_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V19 repairs the collision-off reset time "
                    "budget by allowing a physically consistent rising-arc "
                    "start on the unchanged 1.40 m orbit. Collision-on "
                    "juggling stages are unchanged."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v20_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Align collision-off learning signals and gates with deployment use.

    V19 proved that the corrected full-flight reset budget is realized, but
    its narrow positive Gaussian rewards still improved return without
    reducing the five physical readiness errors.  V20 adds normalized robust
    costs that keep a finite slope far outside each gate.  Position, height
    and pose are shaped throughout the approach; horizontal and angular speed
    are charged only inside the final deadline window.  The precision gate is
    evaluated on the deterministic policy mean instead of exploration-noisy
    PPO samples.  Collision-on stages remain unchanged.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v19_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        cfg = stage.cfg
        collision_off = bool(
            cfg.fixed_contact_disable_ball_racket_collision
        )
        if collision_off:
            cfg = replace(
                cfg,
                fixed_contact_reward_mode=(
                    "fixed_contact_gate_aligned_readiness_v20"
                ),
                fixed_contact_s0_gate_aligned_position_weight=2.0,
                fixed_contact_s0_gate_aligned_motion_weight=1.0,
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v19_", "v20_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V20 adds non-saturating costs normalized "
                    "by the five physical readiness limits and moves S0 "
                    "graduation to a deterministic policy-mean probe."
                    if collision_off
                    else f"{stage.notes} Preserved exactly by V20."
                ),
                fixed_contact_s0_gate_use_advance_eval=collision_off,
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v21_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Factor S0 into stable holding and increasing acquisition distance.

    V19 fixed the unrealized deadline and V20 fixed saturated reward/gate
    alignment, yet the inherited policy remained in the same high-speed local
    optimum.  The remaining confound was curriculum structure: every reset
    simultaneously demanded a workspace move and a precise stop.  V21 first
    initializes the racket at the sampled target using the existing
    pose-preserving IK table, then increases the warm-to-target distance in
    four steps.  No online teacher, observation, action, control, physics or
    collision-on change is introduced.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v20_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed = [
        replace(
            stage,
            name=stage.name.replace("v20_", "v21_", 1),
            notes=f"{stage.notes} Preserved exactly by V21.",
        )
        for stage in source
    ]
    acquisition_source = source[3]
    acquisition_specs = (
        ("v21_s0_acquire_hold_at_target", 1.00),
        ("v21_s0_acquire_distance_25", 0.75),
        ("v21_s0_acquire_distance_50", 0.50),
        ("v21_s0_acquire_distance_75", 0.25),
        ("v21_s0_acquire_distance_100", 0.00),
    )
    acquisition_stages = [
        replace(
            acquisition_source,
            name=name,
            cfg=replace(
                acquisition_source.cfg,
                falling_reset_racket_follow_episode_target_xy=True,
                falling_reset_racket_follow_episode_target_xy_blend=blend,
            ),
            notes=(
                "V21 S0 acquisition-distance lesson. The existing "
                "pose-preserving workspace IK reset supplies "
                f"{blend:.0%} of the warm-to-target joint displacement, so "
                f"the policy must acquire and brake over the remaining "
                f"{1.0 - blend:.0%}. All V20 physical rewards and "
                "deterministic readiness gates are retained."
            ),
        )
        for name, blend in acquisition_specs
    ]
    return [*renamed[:3], *acquisition_stages, *renamed[4:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v22_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Train target readiness first, then the same recurrent juggling task.

    V22 is intentionally from scratch.  It separates absolute workspace
    coverage from per-bounce motion: every reset samples the full reachable
    workspace and starts the racket at that absolute target, while the first
    three collision-off lessons grow only the local intercept displacement
    from zero to 30 mm per axis.  Collision is then enabled without a one-hit
    terminal shortcut, and horizons grow from one second to the full six-
    second/roughly-twelve-hit task.
    """

    validate_fixed_contact_plane_v4_from_scratch(
        resume_path=None,
        resume_curriculum_state=False,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    direct = _fixed_contact_plane_vision_robust_qvel_rmp_v4_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    common_cfg_updates: dict[str, object] = {
        "fixed_contact_reward_mode": "fixed_contact_outcome_constrained_v22",
        "fixed_contact_actor_observation_schema": (
            FIXED_CONTACT_ACTOR_OBSERVATION_SCHEMA_V15
        ),
        "fixed_contact_propagate_held_ball_state_to_query_time": True,
        "fixed_contact_reward_uses_policy_target": True,
        "fixed_contact_tracking_potential_weight": 0.0,
        "fixed_contact_s0_gate_aligned_position_weight": 4.0,
        "fixed_contact_s0_gate_aligned_motion_weight": 2.0,
        "fixed_contact_outcome_max_surface_z_error_m": 0.010,
        "fixed_contact_outcome_max_pose_error_rad": float(np.deg2rad(3.0)),
        "fixed_contact_outcome_max_racket_vxy_m_s": 0.050,
        "fixed_contact_outcome_max_racket_omega_rad_s": 0.50,
        "fixed_contact_outcome_max_contact_offset_m": 0.020,
        "fixed_contact_outcome_max_horizontal_step_m": 0.050,
        "fixed_contact_outcome_max_outward_progress_m": 0.002,
        "action_delta_penalty_weight": 0.010,
        "terminate_after_confirmed_hits": 0,
        "episode_target_x_range_m": (-0.30, 0.20),
        "episode_target_y_range_m": (-0.12, 0.18),
        "fixed_contact_xy_bin_sampling_enabled": True,
        "fixed_contact_xy_equal_bin_evaluation": True,
        "fixed_contact_eval_grid_x_m": (
            -0.30, -0.20, -0.10, 0.0, 0.10, 0.20
        ),
        "fixed_contact_eval_grid_y_m": (
            -0.12, -0.06, 0.0, 0.06, 0.12, 0.18
        ),
        "fixed_contact_xy_center_probability": 0.20,
        "fixed_contact_xy_bin_jitter_m": 0.050,
        "falling_reset_racket_follow_episode_target_xy": True,
        "falling_reset_racket_follow_episode_target_xy_blend": 1.0,
        "falling_reset_racket_follow_fixed_contact_surface_z": True,
        "falling_reset_contact_clip_to_fixed_workspace": True,
    }

    s0_specs = (
        (
            "v22_s0_full_workspace_hold",
            0.000,
            (0.70, 0.70, 0.65, 0.70, 0.70),
            0.40,
        ),
        (
            "v22_s0_local_acquire_15mm",
            0.015,
            (0.62, 0.66, 0.60, 0.60, 0.60),
            0.25,
        ),
        (
            "v22_s0_local_acquire_30mm",
            0.030,
            (0.55, 0.62, 0.55, 0.52, 0.52),
            0.15,
        ),
    )
    result: list[CurriculumStage] = []
    for name, contact_jitter_m, component_gates, ready_fraction in s0_specs:
        cfg = replace(
            direct[0].cfg,
            **common_cfg_updates,
            fixed_contact_training_phase=name,
            fixed_contact_disable_ball_racket_collision=True,
            fixed_contact_quality_reward_weight=0.0,
            fixed_contact_return_reward_weight=0.0,
            fixed_contact_survival_reward_weight=0.0,
            fixed_contact_outcome_constraint_penalty_weight=0.0,
            fixed_contact_outcome_constraint_bonus_weight=0.0,
            falling_reset_contact_xy_jitter=contact_jitter_m,
            falling_reset_vxy_max=0.0,
            falling_reset_time_to_contact_range_s=(0.40, 0.49),
            horizon_sec=0.60,
            termination_miss_penalty_requires_hit=True,
            early_termination_remaining_horizon_penalty=0.0,
            full_episode_completion_reward=0.0,
        )
        result.append(
            CurriculumStage(
                name=name,
                total_steps=direct[0].total_steps,
                cfg=cfg,
                notes=(
                    "V22 collision-off prerequisite: sample the complete "
                    "absolute workspace with pose-preserving IK, then learn "
                    f"only a {contact_jitter_m:.3f} m/axis local intercept "
                    "and settle before contact. The deterministic self-probe "
                    "requires simultaneous position, height, pose, horizontal "
                    "speed and full angular-speed readiness."
                ),
                target_mean_hits=0.0,
                target_mean_len_frac=0.0,
                gate_mode="strict",
                advance_gate_mode="strict",
                advance_validation_probe_mode="self",
                min_updates=40,
                min_recent_fixed_contact_s0_components=component_gates,
                min_recent_fixed_contact_s0_ready_fraction=ready_fraction,
                fixed_contact_s0_gate_use_advance_eval=True,
                convergence_hold_updates=8,
                max_updates=None,
            )
        )

    juggling_specs = (
        # name, source, horizon, jitter, vxy, hits, len, hit1, hit3, hit12,
        # full, q_min, return_min, all_ready
        (
            "v22_s1_single_outcome",
            0,
            1.00,
            0.010,
            0.03,
            0.70,
            0.45,
            0.70,
            None,
            None,
            0.20,
            0.35,
            0.30,
            0.08,
        ),
        (
            "v22_s2_two_contact_bridge",
            3,
            1.35,
            0.012,
            0.05,
            1.45,
            0.62,
            0.82,
            None,
            None,
            0.38,
            0.40,
            0.35,
            0.10,
        ),
        (
            "v22_s3_three_contact_commit",
            3,
            1.85,
            0.015,
            0.06,
            2.30,
            0.68,
            0.88,
            0.45,
            None,
            0.45,
            0.45,
            0.40,
            0.12,
        ),
        (
            "v22_s4_multi_short",
            3,
            3.00,
            0.018,
            0.08,
            4.50,
            0.72,
            0.91,
            0.70,
            None,
            0.55,
            0.48,
            0.45,
            0.15,
        ),
        (
            "v22_s5_multi_full_horizon",
            5,
            6.00,
            0.025,
            0.12,
            8.00,
            0.72,
            0.93,
            0.82,
            0.35,
            0.60,
            0.52,
            0.50,
            0.18,
        ),
        (
            "v22_s6_vision_bridge",
            6,
            6.00,
            0.020,
            0.14,
            7.50,
            0.68,
            0.91,
            0.78,
            0.30,
            0.55,
            0.48,
            0.45,
            0.15,
        ),
        (
            "v22_s7_vision_commit",
            7,
            6.00,
            0.025,
            0.17,
            9.00,
            0.82,
            0.94,
            0.86,
            0.58,
            0.78,
            0.55,
            0.55,
            0.22,
        ),
        (
            "v22_s8_final_full_acceptance",
            8,
            6.00,
            0.030,
            0.20,
            10.50,
            0.93,
            0.96,
            0.92,
            0.80,
            0.90,
            0.60,
            0.60,
            0.30,
        ),
    )
    for (
        name,
        source_index,
        horizon_s,
        contact_jitter_m,
        incoming_vxy_m_s,
        mean_hits,
        mean_len,
        hit1_rate,
        hit3_rate,
        hit12_rate,
        truncation_rate,
        quality_min,
        return_min,
        all_ready_fraction,
    ) in juggling_specs:
        source_stage = direct[source_index]
        cfg = replace(
            source_stage.cfg,
            **common_cfg_updates,
            fixed_contact_training_phase=name,
            fixed_contact_disable_ball_racket_collision=False,
            fixed_contact_quality_reward_weight=3.0,
            fixed_contact_quality_joint_floor_mix=0.50,
            fixed_contact_return_reward_weight=3.0,
            fixed_contact_survival_reward_weight=0.30,
            fixed_contact_outcome_constraint_penalty_weight=2.0,
            fixed_contact_outcome_constraint_bonus_weight=2.0,
            falling_reset_contact_xy_jitter=contact_jitter_m,
            falling_reset_vxy_max=incoming_vxy_m_s,
            falling_reset_time_to_contact_range_s=(0.32, 0.46),
            horizon_sec=horizon_s,
            termination_miss_penalty_requires_hit=False,
            early_termination_remaining_horizon_penalty=(
                8.0 if horizon_s <= 1.0 else (12.0 if horizon_s < 3.0 else 20.0)
            ),
            full_episode_completion_reward=(2.0 if horizon_s >= 1.35 else 1.0),
            full_episode_completion_min_hits=(
                1 if horizon_s <= 1.0 else (2 if horizon_s < 1.85 else 3)
            ),
        )
        result.append(
            CurriculumStage(
                name=name,
                total_steps=source_stage.total_steps,
                cfg=cfg,
                notes=(
                    "V22 recurrent fixed-plane lesson. Collision stays active "
                    "after the first hit; dense target approach/braking, "
                    "per-contact hard-component quality, bounded return-to-"
                    "center flight and post-hit survival are optimized "
                    "together. Graduation validates this same lesson."
                ),
                target_mean_hits=mean_hits,
                target_mean_len_frac=mean_len,
                gate_mode="strict",
                advance_gate_mode="strict",
                advance_validation_probe_mode="self",
                target_hit1_rate=hit1_rate,
                target_hit3_rate=hit3_rate,
                target_hit12_rate=hit12_rate,
                target_episode_truncation_rate=truncation_rate,
                target_min_hit_interval_s=(0.44 if horizon_s >= 1.85 else None),
                target_max_hit_interval_s=(0.56 if horizon_s >= 1.85 else None),
                hit_interval_gate_source="counted_hit_event",
                max_recent_mean_hit_vxy=(
                    0.13 if name.endswith("final_full_acceptance") else 0.18
                ),
                max_recent_rms_hit_vxy=(
                    0.18 if name.endswith("final_full_acceptance") else 0.24
                ),
                max_recent_mean_hit_racket_vxy=0.050,
                max_recent_hit_racket_angular_speed_rad_s=0.50,
                target_racket_up_cos=float(np.cos(np.deg2rad(5.0))),
                min_recent_mean_hit_apex_abs_z_m=(
                    1.38 if horizon_s >= 1.85 else None
                ),
                max_recent_mean_hit_apex_abs_z_m=(
                    1.42 if horizon_s >= 1.85 else None
                ),
                min_recent_fixed_contact_quality_components=(
                    (quality_min,) * 5
                ),
                min_recent_fixed_contact_return_trajectory_score=return_min,
                min_recent_fixed_contact_return_apex_score=return_min,
                max_recent_fixed_contact_return_horizontal_step_m=0.052,
                min_recent_fixed_contact_return_center_progress_m=-0.002,
                min_recent_fixed_contact_outcome_all_ready_fraction=(
                    all_ready_fraction
                ),
                fixed_contact_xy_bin_success_hit_count=(
                    12 if hit12_rate is not None else (3 if hit3_rate is not None else 1)
                ),
                min_advance_fixed_contact_xy_bin_success_rate=(
                    0.70
                    if name.endswith("final_full_acceptance")
                    else (0.45 if hit12_rate is not None else 0.55)
                ),
                min_updates=(80 if horizon_s >= 6.0 else 50),
                convergence_hold_updates=(16 if horizon_s >= 6.0 else 8),
                max_updates=None,
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v23_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Continue the clean V9 actor on the root-cause-repaired V22 task.

    The physical task, reward, reset geometry and same-stage gates are a
    one-to-one copy of V22.  V23 alone is continuation-only: it uses the V16
    target-conditioning schema so the seven small-magnitude target channels
    can be multiplied by ten after an exactly compensating input-layer and
    Adam-moment migration of the pinned V9 checkpoint.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v22_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=stage.name.replace("v22_", "v23_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_actor_observation_schema=(
                    FIXED_CONTACT_ACTOR_OBSERVATION_SCHEMA_V16
                ),
            ),
            notes=(
                f"{stage.notes} V23 preserves the complete V22 physical and "
                "behavior contract while continuing the pinned clean V9 "
                "first-hit policy. Its seven target-conditioning channels "
                "use the function-preserving x10 input/Adam migration."
            ),
        )
        for stage in source
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v24_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Warm-start only V9's proven acquisition actor on recurrent lessons.

    The bounded V23 S0 experiment showed that carrying a one-hit critic and
    Adam state into a collision-off hold MDP is counterproductive.  V24 keeps
    V23's migrated actor but resets the incompatible value/optimizer state and
    starts at the first collision-on, non-terminating recurrent lesson.  V9's
    passed 0.999 first-hit result and 0.037 m/s hit-racket XY speed provide the
    prerequisite acquisition evidence; V24 still optimizes and gates approach,
    braking and all five contact-quality components in every lesson.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v23_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )[3:]
    return [
        replace(
            stage,
            name=stage.name.replace("v23_", "v24_", 1),
            notes=(
                f"{stage.notes} V24 actor-only continuation: the old one-hit "
                "critic and Adam state are explicitly reset before this "
                "collision-on recurrent lesson."
            ),
        )
        for stage in source
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v25_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair V24's event-reward scale and provide an apex bridge.

    V24 proved that the migrated V9 actor retains first-hit acquisition, but
    its seven independent pseudo-Huber costs were summed and multiplied by
    two.  One ordinary source hit therefore received about -39 constraint
    credit against only a few positive reward units.  V25 averages those
    costs, ramps their event weight, and raises the absolute apex target from
    the source policy's measured 1.325 m to the unchanged final 1.40 m goal.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v24_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    apex_targets_m = (1.33, 1.35, 1.38, 1.40, 1.40, 1.40, 1.40, 1.40)
    apex_sigmas_m = (0.060, 0.050, 0.040, 0.030, 0.025, 0.030, 0.025, 0.020)
    constraint_weights = (0.50, 0.75, 1.00, 1.50, 2.00, 1.50, 2.00, 3.00)
    result: list[CurriculumStage] = []
    for stage, apex_target_m, apex_sigma_m, constraint_weight in zip(
        source,
        apex_targets_m,
        apex_sigmas_m,
        constraint_weights,
        strict=True,
    ):
        result.append(
            replace(
                stage,
                name=stage.name.replace("v24_", "v25_", 1),
                cfg=replace(
                    stage.cfg,
                    fixed_contact_target=replace(
                        stage.cfg.fixed_contact_target,
                        target_apex_z_m=apex_target_m,
                    ),
                    fixed_contact_return_apex_sigma_m=apex_sigma_m,
                    fixed_contact_outcome_constraint_aggregation="mean",
                    fixed_contact_outcome_constraint_penalty_weight=(
                        constraint_weight
                    ),
                    fixed_contact_outcome_constraint_bonus_weight=(
                        constraint_weight
                    ),
                    fixed_contact_s0_gate_aligned_position_weight=2.0,
                    fixed_contact_s0_gate_aligned_motion_weight=1.0,
                ),
                notes=(
                    f"{stage.notes} V25 uses a per-constraint mean, event "
                    f"weight {constraint_weight:.2f}, and an apex bridge at "
                    f"{apex_target_m:.2f} +/- {apex_sigma_m:.3f} m. The "
                    "final stage restores the exact 1.40 m task target and "
                    "all original hard acceptance gates."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v26_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach the soft fixed-plane objective before its hard XYZ guard.

    In the bounded V25 run, 11.4% of episodes ended through the fixed racket
    workspace mask.  Its inherited generic terminal barriers contributed
    about -0.097 reward per step, versus about +0.012 from the complete V25
    task objective.  The first three lessons now retain the exact absolute
    workspace bounds as metrics but do not terminate on them; the hard guard
    returns unchanged once the policy reaches the multi-contact curriculum.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v25_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=stage.name.replace("v25_", "v26_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_workspace_termination_penalty_enabled=(
                    index >= 3
                ),
            ),
            notes=(
                f"{stage.notes} V26 "
                + (
                    "logs fixed XYZ excursions without terminating, so the "
                    "dense fixed-plane and settling objective supplies the "
                    "learning signal during this bridge."
                    if index < 3
                    else "restores the unchanged hard fixed-workspace guard "
                    "for multi-contact safety and acceptance."
                )
            ),
        )
        for index, stage in enumerate(source)
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v27_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Run the omitted actor-only precision prerequisite before juggling."""

    precision_source = _fixed_contact_plane_vision_robust_qvel_rmp_v23_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )[:3]
    recurrent_source = _fixed_contact_plane_vision_robust_qvel_rmp_v26_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    precision = [
        replace(
            stage,
            name=stage.name.replace("v23_", "v27_", 1),
            notes=(
                f"{stage.notes} V27 resets the incompatible V9 one-hit "
                "critic and Adam state before this collision-off precision "
                "lesson; this actor-only variant was not tested by V23."
            ),
        )
        for stage in precision_source
    ]
    recurrent = [
        replace(
            stage,
            name=stage.name.replace("v26_", "v27_", 1),
            notes=(
                f"{stage.notes} V27 reaches this recurrent lesson only after "
                "passing its collision-off position, pose, horizontal-speed "
                "and full-angular-speed prerequisite."
            ),
        )
        for stage in recurrent_source
    ]
    return precision + recurrent


def _fixed_contact_plane_vision_robust_qvel_rmp_v28_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Keep collision-off S0 alive through its declared contact deadline.

    V27 exposed a task-definition contradiction: its S0 ball was sampled to
    cross the contact plane after 0.40--0.49 s, while the inherited camera
    lower-bound termination ended episodes after about 0.275 s.  The first
    three collision-off precision lessons therefore disable only this view
    termination.  Collision-on recurrent lessons keep V27's view contract.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v27_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=stage.name.replace("v27_", "v28_", 1),
            cfg=(
                replace(stage.cfg, terminate_on_ball_view_bounds=False)
                if index < 3
                else stage.cfg
            ),
            notes=(
                f"{stage.notes} V28 "
                + (
                    "disables the inherited camera-bound termination only "
                    "for this collision-off lesson, allowing the complete "
                    "0.40--0.49 s approach-and-settle interval to be scored."
                    if index < 3
                    else "preserves the collision-on recurrent view and "
                    "termination contract unchanged."
                )
            ),
        )
        for index, stage in enumerate(source)
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v29_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Remove the second premature S0 ball-height termination.

    V28 disabled the camera-bound term, but its bounded probe still ended at
    56.5/120 steps because fixed-contact ``ball_too_low`` reused the 0.98 m
    juggling floor after the deliberately non-colliding ball crossed the
    racket plane.  S0 now permits that diagnostic ball to fall to 0 m for the
    remainder of its 0.60 s horizon.  Recurrent stages remain byte-for-byte
    equivalent in configuration to V28.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v28_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        cfg = stage.cfg
        if index < 3:
            cfg = replace(
                cfg,
                fixed_contact_ball_z_bounds_m=(
                    0.0,
                    float(cfg.fixed_contact_ball_z_bounds_m[1]),
                ),
            )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v28_", "v29_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V29 "
                    + (
                        "lowers only the collision-off diagnostic ball floor "
                        "to 0 m so ball_too_low cannot pre-empt the 0.60 s "
                        "precision horizon."
                        if index < 3
                        else "preserves the recurrent ball-height and view "
                        "termination contract unchanged."
                    )
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v30_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Make S0 racket workspace violations diagnostic until graduation.

    The V29 probe removed both ball-height exits, then showed that inherited
    fixed-contact racket XYZ terms ended episodes near 0.40 s, before the
    actor could learn the 0.40--0.49 s approach-and-settle objective.  V30
    keeps every continuous penalty and strict S0 graduation gate but makes
    those three terms non-terminal only in the collision-off lessons.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v29_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [
        replace(
            stage,
            name=stage.name.replace("v29_", "v30_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_workspace_termination_enabled=(index >= 3),
            ),
            notes=(
                f"{stage.notes} V30 "
                + (
                    "logs racket XYZ excursions without terminating; all "
                    "dense tracking terms and strict graduation thresholds "
                    "remain active."
                    if index < 3
                    else "restores the historical hard racket XYZ "
                    "termination for collision-on recurrent juggling."
                )
            ),
        )
        for index, stage in enumerate(source)
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v31_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Resume the interrupted GPU0 V22 run without changing its course."""

    return _fixed_contact_plane_vision_robust_qvel_rmp_v22_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v32_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Train the reviewed GPU1 direct-juggling placed-ball route.

    V23--V30 accidentally remained falling-ball interception courses.  V32
    instead starts every episode with the racket pose sampled across the full
    registered fixed plane and the ball placed one millimetre above that
    racket.  Collision is active and no contact terminates the episode, so the
    first lesson already optimizes autonomous launch plus recurrent juggling.
    It keeps V25's bounded per-constraint reward and apex bridge, and resumes
    the complete clean V9 actor/critic/Adam state because the retained-state
    V23 diagnostic improved while every actor-only reset did not.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v25_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        cfg = replace(
            stage.cfg,
            ball_reset_mode="racket_launch",
            falling_reset_racket_follow_episode_target_xy=False,
            falling_reset_racket_follow_fixed_contact_surface_z=False,
            racket_launch_racket_follow_episode_target_xy=True,
            racket_launch_racket_follow_fixed_contact_surface_z=True,
            racket_launch_surface_gap_range_m=(0.001, 0.001),
            racket_launch_xy_jitter=0.004,
            racket_launch_vxy_max=0.0,
            racket_launch_vnormal_max=0.0,
            terminate_after_confirmed_hits=0,
            fixed_contact_disable_ball_racket_collision=False,
        )
        result.append(
            replace(
                stage,
                name=stage.name.replace("v25_", "v32_", 1),
                cfg=cfg,
                notes=(
                    f"{stage.notes} V32 directly initializes a horizontal "
                    "racket at the sampled full-workspace target, places the "
                    "ball 1 mm above its physical surface, and trains launch "
                    "and recurrent contacts in the same MDP."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v33_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Resume the interrupted GPU0 V31 run without changing its course."""

    return _fixed_contact_plane_vision_robust_qvel_rmp_v31_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v34_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Remove the zero-action shortcut from local acquisition lessons.

    V22's 15 mm square reset is already inside its 20 mm physical readiness
    radius and has an analytic no-motion XY score of about 0.732, above its
    0.62 gate.  It therefore taught holding, not acquisition, before the 30 mm
    lesson.  V34 retains every control, reward, observation, physics, DR and
    PPO contract, but makes the two local lessons area-uniform annuli whose
    easiest untouched reset is below the unchanged graduation score.  At a
    workspace edge, an outward component is reflected inward rather than
    clipped away, preserving the declared acquisition distance.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v22_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    s0_names_and_radii = (
        ("v34_s0_full_workspace_hold", "square_uniform", 0.000, 0.000),
        ("v34_s0_forced_acquire_15_20mm", "annulus_uniform", 0.015, 0.020),
        ("v34_s0_forced_acquire_25_30mm", "annulus_uniform", 0.025, 0.030),
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        if index < len(s0_names_and_radii):
            name, mode, minimum_m, maximum_m = s0_names_and_radii[index]
            cfg = replace(
                stage.cfg,
                fixed_contact_training_phase=name,
                falling_reset_contact_xy_sampling_mode=mode,
                falling_reset_contact_xy_min_radius_m=minimum_m,
                falling_reset_contact_xy_jitter=maximum_m,
            )
            note = (
                "V34 keeps the zero-displacement full-workspace holding "
                "prerequisite unchanged."
                if index == 0
                else (
                    "V34 samples a true local acquisition annulus of "
                    f"{minimum_m * 1000:.0f}--{maximum_m * 1000:.0f} mm. "
                    "The easiest zero-action reset is below the unchanged "
                    "precision gate, and boundary reflection prevents "
                    "workspace clipping from erasing the displacement."
                )
            )
        else:
            name = stage.name.replace("v22_", "v34_", 1)
            cfg = replace(stage.cfg, fixed_contact_training_phase=name)
            note = (
                "V34 preserves this collision-on stage's reset, reward, "
                "gate, observation, control, physics and DR values."
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=cfg,
                notes=f"{stage.notes} {note}",
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v35_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Make the collision-off acquisition time an explicit reset contract.

    V22/V34 declared 0.40--0.49 s to contact, but the reset implementation
    allowed rising-half initialization only for two old reward-mode strings.
    The V22 reward rename therefore clipped the duration to one descending
    half-flight (about 0.23 s), and the episode ended before the declared
    target time.  V35 preserves V34 and explicitly enables the rising-half
    reset only for its three collision-off positioning prerequisites.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v34_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v34_", "v35_", 1)
        cfg = replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            falling_reset_allow_ascending_phase=index < 3,
        )
        note = (
            "V35 explicitly permits rising-half initialization, so the "
            "declared 0.40--0.49 s pre-contact acquisition window is not "
            "silently clipped to a descending half-flight."
            if index < 3
            else (
                "V35 leaves this collision-on stage's falling-reset timing "
                "and all other contracts unchanged."
            )
        )
        result.append(
            replace(
                stage,
                name=name,
                cfg=cfg,
                notes=f"{stage.notes} {note}",
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v36_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach early acquisition over nested workspace supports before hits.

    V35 samples the full absolute workspace from its first lesson and uses IK
    to initialize the racket at that sampled target.  Its nonzero lessons
    therefore prove only a 15--30 mm local correction.  V36 starts the racket
    from one fixed canonical warm pose, expands the predicted contact target
    over five nested lessons, and requires readiness both in the 80--100 ms
    arrival band and throughout at least 80% of the final 100 ms.  The V35
    collision-on juggling tail is otherwise preserved exactly.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v35_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    template = source[0]
    acquisition_specs = (
        (
            "v36_s0_canonical_hold",
            (-0.10, -0.10),
            (0.03, 0.03),
            False,
            (0.70, 0.70, 0.65, 0.70, 0.70),
            0.90,
            0.90,
        ),
        (
            "v36_s0_center_acquire",
            (0.0, 0.0),
            (0.0, 0.0),
            False,
            (0.68, 0.70, 0.65, 0.68, 0.68),
            0.85,
            0.80,
        ),
        (
            "v36_s0_inner_workspace_acquire",
            (-0.10, 0.10),
            (-0.06, 0.06),
            True,
            (0.65, 0.68, 0.62, 0.65, 0.65),
            0.85,
            0.80,
        ),
        (
            "v36_s0_mid_workspace_acquire",
            (-0.20, 0.10),
            (-0.12, 0.12),
            True,
            (0.60, 0.65, 0.58, 0.60, 0.60),
            0.80,
            0.75,
        ),
        (
            "v36_s0_full_workspace_acquire",
            (-0.30, 0.20),
            (-0.12, 0.18),
            True,
            (0.55, 0.62, 0.55, 0.55, 0.55),
            0.80,
            0.75,
        ),
    )
    result: list[CurriculumStage] = []
    for (
        name,
        target_x_range_m,
        target_y_range_m,
        bin_sampling,
        component_gates,
        ready_fraction,
        arrival_ready_fraction,
    ) in acquisition_specs:
        cfg = replace(
            template.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_disable_ball_racket_collision=True,
            episode_target_x_range_m=target_x_range_m,
            episode_target_y_range_m=target_y_range_m,
            fixed_contact_xy_bin_sampling_enabled=bin_sampling,
            fixed_contact_xy_equal_bin_evaluation=bin_sampling,
            fixed_contact_xy_center_probability=(0.20 if bin_sampling else 1.0),
            fixed_contact_xy_bin_jitter_m=(0.025 if bin_sampling else 0.0),
            # The absolute target must be acquired from the canonical warm
            # reset pose; initializing at the target would collapse this back
            # to V35's local-correction task.
            falling_reset_racket_follow_episode_target_xy=False,
            falling_reset_racket_follow_fixed_contact_surface_z=False,
            falling_reset_contact_xy_sampling_mode="square_uniform",
            falling_reset_contact_xy_min_radius_m=0.0,
            falling_reset_contact_xy_jitter=0.0,
            falling_reset_vxy_max=0.0,
            falling_reset_time_to_contact_range_s=(0.40, 0.50),
            falling_reset_allow_ascending_phase=True,
            fixed_contact_final_window_s=0.100,
            fixed_contact_s0_arrival_window_s=(0.080, 0.100),
            fixed_contact_quality_reward_weight=0.0,
            fixed_contact_return_reward_weight=0.0,
            fixed_contact_survival_reward_weight=0.0,
            fixed_contact_outcome_constraint_penalty_weight=0.0,
            fixed_contact_outcome_constraint_bonus_weight=0.0,
            horizon_sec=0.60,
            termination_miss_penalty_requires_hit=True,
            early_termination_remaining_horizon_penalty=0.0,
            full_episode_completion_reward=0.0,
        )
        result.append(
            CurriculumStage(
                name=name,
                total_steps=template.total_steps,
                cfg=cfg,
                notes=(
                    "V36 GPU0 collision-off prerequisite: the racket starts "
                    "at the fixed canonical warm pose and must acquire the "
                    "prediction-conditioned target over a nested absolute "
                    f"support x={target_x_range_m}, y={target_y_range_m}. "
                    "Deterministic self-validation separately proves "
                    "readiness in the 80--100 ms arrival band and sustained "
                    "readiness over the final 100 ms."
                ),
                target_mean_hits=0.0,
                target_mean_len_frac=0.0,
                gate_mode="strict",
                advance_gate_mode="strict",
                advance_validation_probe_mode="self",
                min_updates=(40 if not bin_sampling else 60),
                min_recent_fixed_contact_s0_components=component_gates,
                min_recent_fixed_contact_s0_ready_fraction=ready_fraction,
                min_recent_fixed_contact_s0_arrival_ready_fraction=(
                    arrival_ready_fraction
                ),
                fixed_contact_s0_gate_use_advance_eval=True,
                convergence_hold_updates=(8 if not bin_sampling else 12),
                max_updates=None,
            )
        )

    for stage in source[3:]:
        name = stage.name.replace("v35_", "v36_", 1)
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, fixed_contact_training_phase=name),
                notes=(
                    f"{stage.notes} V36 reaches this unchanged collision-on "
                    "juggling lesson only after passing the nested absolute-"
                    "workspace acquire-and-settle prerequisite."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v37_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair placed-ball apex credit without adding an acquisition course.

    V32 correctly implements the GPU1 reset intent, but a gross launch can put
    the next plane crossing beyond the predictor's one-second validity limit.
    Its Gaussian return reward is then both gated off and numerically flat.
    V37 adds only an event-level pseudo-Huber apex cost with a controlled
    per-stage weight.  It retains the placed-ball full-workspace task and is
    paired with an actor-only V9 warm start so the falling-ball critic and Adam
    state cannot define the new MDP's initial value targets.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v32_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    apex_penalty_weights = (0.20, 0.25, 0.30, 0.40, 0.50, 0.50, 0.60, 0.75)
    result: list[CurriculumStage] = []
    for stage, penalty_weight in zip(
        source, apex_penalty_weights, strict=True
    ):
        name = stage.name.replace("v32_", "v37_", 1)
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    fixed_contact_apex_error_penalty_weight=penalty_weight,
                    fixed_contact_apex_error_penalty_scale_m=0.100,
                ),
                notes=(
                    f"{stage.notes} V37 adds a crossing-validity-independent "
                    "pseudo-Huber apex error cost with event weight "
                    f"{penalty_weight:.2f} and 0.10 m scale. The placed-ball "
                    "reset, target, collision, observation, control and hard "
                    "acceptance contracts are unchanged."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v38_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Bridge the canonical-to-center move and brake before the deadline."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v36_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    expanded = [source[0]]
    for fraction in (1 / 3, 2 / 3):
        x = -.10 * (1 - fraction)
        y = .03 * (1 - fraction)
        expanded.append(replace(
            source[1],
            name=f"v36_s0_center_bridge_{round(fraction * 3)}",
            cfg=replace(source[1].cfg, episode_target_x_range_m=(x, x),
                        episode_target_y_range_m=(y, y)),
        ))
    expanded.extend(source[1:])
    result = []
    for stage in expanded:
        name = stage.name.replace("v36_", "v38_", 1)
        collision_off = stage.cfg.fixed_contact_disable_ball_racket_collision
        result.append(replace(
            stage, name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name,
                        fixed_contact_surface_frame_mode="mesh_axes_v1",
                        fixed_contact_s0_settle_lead_s=(.020 if collision_off else 0.)),
            fixed_contact_s0_gate_per_episode_and_bin=collision_off,
            notes=(
                "V38 starts braking at TTC=120 ms so readiness is due by "
                "100 ms; both deadline bands include every evaluation lane "
                "and must pass in the worst sampled workspace bin. "
                "The collision-on V36 task is preserved with the common "
                "mesh surface/bounds correction."
            ),
        ))
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v39_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Isolate the finite-mesh placed-ball frame repair from reward tuning."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v37_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    return [replace(
        stage, name=stage.name.replace("v37_", "v39_", 1),
        cfg=replace(stage.cfg,
                    fixed_contact_training_phase=stage.name.replace("v37_", "v39_", 1),
                    fixed_contact_surface_frame_mode="mesh_axes_v1"),
        notes=("V39 places and holds the ball along the compiled mesh thickness "
               "axis, with jitter in its tangent plane. Reward, control, PPO, "
               "full-workspace reset support and gates stay V37-exact."),
    ) for stage in source]


def _fixed_contact_plane_vision_robust_qvel_rmp_v40_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach target-state stability before retrying the stalled center move."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v38_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed = [
        replace(
            stage,
            name=stage.name.replace("v38_", "v40_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=stage.name.replace(
                    "v38_", "v40_", 1
                ),
            ),
        )
        for stage in source
    ]
    center = source[3]
    repair_specs = (
        ("v40_s0_center_hold_at_target", 1.00, True),
        ("v40_s0_center_acquire_distance_25", 0.75, True),
        ("v40_s0_center_acquire_distance_50", 0.50, True),
        ("v40_s0_center_acquire_distance_75", 0.25, True),
    )
    repair = [
        replace(
            center,
            name=name,
            cfg=replace(
                center.cfg,
                fixed_contact_training_phase=name,
                falling_reset_racket_follow_episode_target_xy=True,
                falling_reset_racket_follow_episode_target_xy_blend=blend,
                falling_reset_racket_follow_fixed_contact_surface_z=follow_z,
            ),
            notes=(
                "V40 target-state stability repair. The pose-preserving IK "
                f"reset supplies {blend:.0%} of the canonical-to-center "
                "displacement and aligns the surface height. The policy must "
                "remain ready, then progressively move and brake under the "
                "unchanged per-episode and deterministic arrival gates."
            ),
        )
        for name, blend, follow_z in repair_specs
    ]
    retry_name = "v40_s0_center_acquire_retry"
    repair.append(
        replace(
            center,
            name=retry_name,
            cfg=replace(center.cfg, fixed_contact_training_phase=retry_name),
            notes=center.notes,
        )
    )
    return [*renamed[:4], *repair, *renamed[4:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v41_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Remove the sticky zero-hit optimum and stage first-launch quality."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v39_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    repaired: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("v39_", "v41_", 1)
        repaired.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    fixed_contact_include_stick_penalty=True,
                    fixed_contact_pre_hit_s0_reward_max_s=0.12,
                ),
                notes=(
                    f"{stage.notes} V41 includes the already logged sticky-"
                    "contact cost in total reward and limits preparation "
                    "credit to the first 120 ms until one hit is counted."
                ),
            )
        )

    commit = replace(
        repaired[0],
        name="v41_s1_single_outcome_commit",
        cfg=replace(
            repaired[0].cfg,
            fixed_contact_training_phase="v41_s1_single_outcome_commit",
        ),
        notes=source[0].notes,
    )
    launch_only = replace(
        repaired[0],
        name="v41_s1_launch_only_bridge",
        cfg=replace(
            repaired[0].cfg,
            fixed_contact_training_phase="v41_s1_launch_only_bridge",
            fixed_contact_outcome_constraint_penalty_weight=0.0,
            fixed_contact_outcome_constraint_bonus_weight=0.0,
            fixed_contact_apex_error_penalty_weight=0.0,
        ),
        notes=(
            "V41 first-launch bridge: every counted upward hit has positive "
            "event credit before outcome constraints are introduced. Sticky "
            "contact is charged and zero-hit S0 credit ends after 120 ms."
        ),
        target_mean_hits=0.20,
        target_mean_len_frac=0.25,
        target_hit1_rate=0.20,
        min_recent_fixed_contact_quality_components=None,
        min_recent_fixed_contact_return_trajectory_score=None,
        min_recent_fixed_contact_return_apex_score=None,
        min_recent_fixed_contact_outcome_all_ready_fraction=None,
        min_advance_fixed_contact_xy_bin_success_rate=0.10,
    )
    launch_quality = replace(
        repaired[0],
        name="v41_s1_launch_quality_bridge",
        cfg=replace(
            repaired[0].cfg,
            fixed_contact_training_phase="v41_s1_launch_quality_bridge",
            fixed_contact_outcome_constraint_penalty_weight=0.25,
            fixed_contact_outcome_constraint_bonus_weight=0.25,
            fixed_contact_apex_error_penalty_weight=0.05,
        ),
        notes=(
            "V41 launch-quality bridge restores bounded contact and apex "
            "costs before the unchanged V39 single-outcome acceptance gate."
        ),
        target_mean_hits=0.45,
        target_mean_len_frac=0.35,
        target_hit1_rate=0.45,
        min_recent_fixed_contact_quality_components=(
            0.15, 0.15, 0.15, 0.15, 0.15
        ),
        min_recent_fixed_contact_return_trajectory_score=0.10,
        min_recent_fixed_contact_return_apex_score=0.10,
        min_recent_fixed_contact_outcome_all_ready_fraction=0.02,
        min_advance_fixed_contact_xy_bin_success_rate=0.30,
    )
    return [launch_only, launch_quality, commit, *repaired[1:]]


def _fixed_contact_plane_vision_robust_qvel_rmp_v42_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Bootstrap placed-ball launch, then remove the release assistance."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v41_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    launch_source = source[0]
    hold_specs = (
        ("v42_s1_launch_hold_300ms", 0.30, 0.10, 0.15, 0.05),
        ("v42_s1_launch_hold_200ms", 0.20, 0.15, 0.18, 0.075),
        ("v42_s1_launch_hold_100ms", 0.10, 0.18, 0.20, 0.08),
        ("v42_s1_launch_hold_050ms", 0.05, 0.20, 0.22, 0.09),
        ("v42_s1_launch_unassisted", 0.00, 0.20, 0.25, 0.10),
    )
    launch_stages = [
        replace(
            launch_source,
            name=name,
            cfg=replace(
                launch_source.cfg,
                fixed_contact_training_phase=name,
                fixed_contact_pre_hit_s0_reward_max_s=0.0,
                racket_launch_hold_time_s=hold_s,
                racket_launch_hold_time_range_s=None,
                racket_launch_hold_mode="racket_relative",
            ),
            target_mean_hits=target_hit1,
            target_hit1_rate=target_hit1,
            target_mean_len_frac=target_len,
            min_advance_fixed_contact_xy_bin_success_rate=min_xy_bin,
            notes=(
                "V42 direct placed-ball launch homotopy: hold the initialized "
                f"ball on the moving racket for {hold_s:.2f} s, preserving "
                "its realized racket velocity at release. Pre-hit S0 "
                "positioning reward is disabled because it produced the V41 "
                "action-independent penalty plateau. The hold is reduced to "
                "zero before contact-quality and recurrent lessons."
            ),
        )
        for name, hold_s, target_hit1, target_len, min_xy_bin in hold_specs
    ]
    tail = [
        replace(
            stage,
            name=stage.name.replace("v41_", "v42_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=stage.name.replace(
                    "v41_", "v42_", 1
                ),
                fixed_contact_pre_hit_s0_reward_max_s=0.0,
                racket_launch_hold_time_s=0.0,
                racket_launch_hold_time_range_s=None,
            ),
            notes=f"{stage.notes} V42 runs this lesson without launch hold.",
        )
        for stage in source[1:]
    ]
    return [*launch_stages, *tail]


