def _fixed_contact_plane_vision_robust_qvel_rmp_v45_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Learn a causal placed-ball launch with a fresh stable actor."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v41_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    launch_source = source[0]
    launch_specs = (
        (
            "v45_s1_guided_launch_030ms_scale050",
            0.030, 0.50, 50.0, 0.060, 0.02, 0.15, 0.02,
        ),
        (
            "v45_s1_guided_launch_020ms_scale065",
            0.020, 0.65, 35.0, 0.050, 0.05, 0.18, 0.04,
        ),
        (
            "v45_s1_guided_launch_010ms_scale080",
            0.010, 0.80, 20.0, 0.040, 0.10, 0.22, 0.07,
        ),
        (
            "v45_s1_unassisted_launch_reward",
            0.000, 1.00, 10.0, 0.030, 0.15, 0.25, 0.09,
        ),
        (
            "v45_s1_unassisted_launch_commit",
            0.000, 1.00, 0.0, 0.000, 0.20, 0.25, 0.10,
        ),
    )
    launch_stages = [
        replace(
            launch_source,
            name=name,
            cfg=replace(
                launch_source.cfg,
                fixed_contact_training_phase=name,
                fixed_contact_pre_hit_s0_reward_max_s=0.0,
                fixed_contact_pre_hit_launch_vz_reward_weight=reward_weight,
                fixed_contact_pre_hit_launch_vz_target_m_s=0.50,
                fixed_contact_pre_hit_launch_vz_window_s=reward_window_s,
                racket_launch_hold_time_s=hold_s,
                racket_launch_hold_time_range_s=None,
                racket_launch_hold_mode="racket_relative",
                action_velocity_scale=action_scale,
            ),
            target_mean_hits=target_hit1,
            target_hit1_rate=target_hit1,
            target_mean_len_frac=target_len,
            min_advance_fixed_contact_xy_bin_success_rate=min_xy_bin,
            notes=(
                "V45 fresh-policy direct launch lesson. A signed, bounded "
                f"reward measures realized racket Vz for only the first "
                f"{reward_window_s * 1000:.0f} ms before the first hit; its "
                f"weight is {reward_weight:.1f}. The moving-racket hold is "
                f"{hold_s * 1000:.0f} ms and QVEL scale is "
                f"{action_scale:.0%}. Both aids are removed before the "
                "unchanged outcome course."
            ),
        )
        for (
            name,
            hold_s,
            action_scale,
            reward_weight,
            reward_window_s,
            target_hit1,
            target_len,
            min_xy_bin,
        ) in launch_specs
    ]
    tail = [
        replace(
            stage,
            name=stage.name.replace("v41_", "v45_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=stage.name.replace(
                    "v41_", "v45_", 1
                ),
                fixed_contact_pre_hit_s0_reward_max_s=0.0,
                fixed_contact_pre_hit_launch_vz_reward_weight=0.0,
                fixed_contact_pre_hit_launch_vz_window_s=0.0,
                racket_launch_hold_time_s=0.0,
                racket_launch_hold_time_range_s=None,
                action_velocity_scale=launch_source.cfg.action_velocity_scale,
            ),
            notes=f"{stage.notes} V45 runs without launch shaping.",
        )
        for stage in source[1:]
    ]
    return [*launch_stages, *tail]


def _fixed_contact_plane_vision_robust_qvel_rmp_v46_stages(
    stages: list[CurriculumStage], *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Add immediate action-to-Vz credit to the V45 launch bridge."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v45_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    command_weights = (100.0, 70.0, 40.0, 20.0, 0.0)
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v45_", "v46_", 1)
        command_weight = command_weights[index] if index < 5 else 0.0
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    fixed_contact_pre_hit_launch_command_vz_reward_weight=(
                        command_weight
                    ),
                ),
                notes=(
                    f"{stage.notes} V46 additionally rewards the immediate "
                    "desired joint velocity projected through the registered "
                    f"warm-pose racket Vz Jacobian with weight {command_weight:.1f}; "
                    "realized Vz and physical hit gates remain authoritative."
                ),
            )
        )
    return result


