def _fixed_contact_plane_vision_robust_qvel_rmp_v82_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Separate GPU1 contact acquisition from shaped quality tightening."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v80_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    renamed: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("v80_", "v82_", 1)
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        renamed.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, **cfg_updates),
                notes=f"{stage.notes} V82 preserves this V80 lesson.",
            )
        )

    acquisition_source = source[4]
    acquisition_name = "v82_s1_contact_acquisition_only"
    acquisition_cfg = replace(
        acquisition_source.cfg,
        fixed_contact_training_phase=acquisition_name,
        hit_racket_vxy_penalty_weight=0.0,
        hit_vxy_penalty_weight=0.0,
        low_hit_penalty_weight=0.0,
        hit_apex_lift_penalty_weight=0.0,
        hit_apex_view_center_penalty_weight=0.0,
        post_hit_overdue_penalty_weight=0.0,
        fixed_contact_outcome_constraint_penalty_weight=0.0,
        hit_racket_angular_speed_penalty_weight=0.0,
        hit_contact_center_excess_penalty_weight=0.0,
        hit_cycle_racket_xy_path_penalty_weight=0.0,
        hit_cycle_racket_xy_area_penalty_weight=0.0,
        racket_cycle_vxy_penalty_weight=0.0,
        hit_height_penalty_weight=0.0,
        hit_contact_z_penalty_weight=0.0,
        hit_next_contact_anchor_penalty_weight=0.0,
        fast_hit_penalty_weight=0.0,
        hit_count_floor_reward_weight=3.0,
    )
    acquisition = replace(
        acquisition_source,
        name=acquisition_name,
        cfg=acquisition_cfg,
        min_updates=10,
        convergence_hold_updates=4,
        notes=(
            "V82 acquisition advances only on confirmed-hit and survival "
            "metrics. Event-quality costs and every quality gate are disabled."
        ),
        **_FIXED_CONTACT_ACQUISITION_QUALITY_GATE_DEFAULTS,
    )

    bridge_source = source[5]
    bridge_name = "v82_s1_quality_hinge_bridge"
    bridge = replace(
        bridge_source,
        name=bridge_name,
        cfg=replace(
            bridge_source.cfg,
            fixed_contact_training_phase=bridge_name,
            hit_racket_vxy_penalty_weight=0.20,
            hit_racket_vxy_soft_limit_m_s=0.18,
            hit_racket_vxy_penalty_scale_m_s=0.15,
            hit_vxy_penalty_weight=0.50,
            hit_vxy_soft_limit_m_s=0.23,
            hit_racket_angular_speed_penalty_weight=0.25,
            hit_racket_angular_speed_soft_limit_rad_s=0.60,
            low_hit_penalty_weight=100.0,
            hit_apex_lift_penalty_weight=25.0,
            fixed_contact_outcome_constraint_penalty_weight=0.10,
            hit_count_floor_reward_weight=2.5,
        ),
        max_recent_mean_hit_vxy=0.32,
        max_recent_rms_hit_vxy=0.34,
        max_recent_mean_hit_racket_vxy=0.34,
        max_recent_hit_racket_angular_speed_rad_s=0.90,
        target_racket_up_cos=float(np.cos(np.deg2rad(10.0))),
        max_recent_fixed_contact_return_horizontal_step_m=0.13,
        min_recent_fixed_contact_return_center_progress_m=-0.13,
        min_updates=40,
        convergence_hold_updates=8,
        notes=(
            "V82 first restores squared-hinge motion/outcome penalties with "
            "soft limits strictly inside relaxed quality gates, so failing "
            "samples retain a non-saturating gradient."
        ),
    )

    commit_source = source[6]
    commit_name = "v82_s1_quality_hinge_commit"
    commit = replace(
        commit_source,
        name=commit_name,
        cfg=replace(
            commit_source.cfg,
            fixed_contact_training_phase=commit_name,
            hit_racket_vxy_penalty_weight=0.35,
            hit_racket_vxy_soft_limit_m_s=0.12,
            hit_racket_vxy_penalty_scale_m_s=0.15,
            hit_vxy_penalty_weight=0.75,
            hit_vxy_soft_limit_m_s=0.18,
            hit_racket_angular_speed_penalty_weight=0.50,
            hit_racket_angular_speed_soft_limit_rad_s=0.45,
            low_hit_penalty_weight=250.0,
            hit_apex_lift_penalty_weight=50.0,
            fixed_contact_outcome_constraint_penalty_weight=0.20,
            hit_count_floor_reward_weight=2.0,
        ),
        max_recent_mean_hit_vxy=0.26,
        max_recent_rms_hit_vxy=0.30,
        max_recent_mean_hit_racket_vxy=0.20,
        max_recent_hit_racket_angular_speed_rad_s=0.70,
        target_racket_up_cos=float(np.cos(np.deg2rad(7.0))),
        max_recent_fixed_contact_return_horizontal_step_m=0.09,
        min_recent_fixed_contact_return_center_progress_m=-0.07,
        min_updates=60,
        convergence_hold_updates=10,
        notes=(
            "V82 tightens the same active squared-hinge quality objectives "
            "only after the acquisition lesson has passed."
        ),
    )

    strict_name = "v82_s1_quality_strict_commit"
    strict = replace(
        commit_source,
        name=strict_name,
        cfg=replace(
            commit_source.cfg,
            fixed_contact_training_phase=strict_name,
            hit_racket_vxy_penalty_weight=0.50,
            hit_racket_vxy_soft_limit_m_s=0.04,
            hit_racket_vxy_penalty_scale_m_s=0.15,
            hit_vxy_penalty_weight=1.0,
            hit_vxy_soft_limit_m_s=0.14,
            hit_racket_angular_speed_penalty_weight=0.75,
            hit_racket_angular_speed_soft_limit_rad_s=0.40,
            low_hit_penalty_weight=250.0,
            hit_apex_lift_penalty_weight=50.0,
            fixed_contact_outcome_constraint_penalty_weight=0.25,
            hit_count_floor_reward_weight=1.5,
        ),
        max_recent_mean_hit_vxy=0.18,
        max_recent_rms_hit_vxy=0.24,
        max_recent_mean_hit_racket_vxy=0.05,
        max_recent_hit_racket_angular_speed_rad_s=0.50,
        target_racket_up_cos=float(np.cos(np.deg2rad(5.0))),
        max_recent_fixed_contact_return_horizontal_step_m=0.052,
        min_recent_fixed_contact_return_center_progress_m=-0.002,
        min_updates=80,
        convergence_hold_updates=12,
        notes=(
            "V82 restores the unchanged strict V80 quality gates after two "
            "active-gradient bridges."
        ),
    )

    return [
        *renamed[:4],
        acquisition,
        bridge,
        commit,
        strict,
        *renamed[7:],
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v83_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Move GPU0's braking objective ahead of the physical response lag."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v81_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v81_", "v83_", 1)
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        if index in (8, 9):
            # The recovered-RMP/PD response begins too late when braking is
            # rewarded only in the final 80 ms.  Add 80 ms of lead without
            # changing the exact readiness thresholds or factorized support.
            cfg_updates["fixed_contact_s0_settle_lead_s"] = 0.08
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, **cfg_updates),
                notes=(
                    f"{stage.notes} V83 starts the unchanged S0 braking "
                    "objective 80 ms earlier to cover measured RMP/PD lag; "
                    "all graduation gates and XY-by-blend cells are unchanged."
                    if index in (8, 9)
                    else f"{stage.notes} V83 preserves this V81 lesson."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v84_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach direct juggling from causal falling contacts, then widen space."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v82_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    workspace_support = {
        8: ((0.0, 0.0), (0.0, 0.0), "center"),
        9: ((-0.05, 0.05), (-0.04, 0.04), "local"),
        10: ((-0.10, 0.10), (-0.06, 0.06), "inner"),
        11: ((-0.15, 0.15), (-0.10, 0.10), "mid"),
        12: ((-0.20, 0.18), (-0.12, 0.15), "wide"),
        13: ((-0.30, 0.20), (-0.12, 0.18), "full"),
    }
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v82_", "v84_", 1)
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        notes = f"{stage.notes} V84 preserves this pre-acquisition lesson."
        if index >= 4:
            # A placed ball makes contact before the delayed RMP has built a
            # useful stroke and then punishes the policy for that unavoidable
            # pending contact.  Falling resets expose the complete causal
            # approach -> stroke -> brake sequence instead.
            cfg_updates.update(
                ball_reset_mode="falling_contact",
                falling_reset_mixture_probability=0.0,
                falling_reset_episode_target_x_range_m=None,
                falling_reset_episode_target_y_range_m=None,
                falling_reset_episode_racket_anchor_z_range_m=None,
                falling_reset_racket_follow_episode_target_xy=True,
                falling_reset_racket_follow_fixed_contact_surface_z=True,
                falling_reset_racket_follow_episode_target_xy_blend=1.0,
                falling_reset_racket_follow_episode_target_xy_blend_range=None,
                falling_reset_racket_follow_episode_target_xy_blend_choices=None,
                falling_reset_apply_target_follow_blend_choices=False,
                racket_launch_racket_follow_episode_target_xy=False,
                racket_launch_racket_follow_fixed_contact_surface_z=False,
                racket_launch_hold_time_s=0.0,
                racket_launch_hold_time_range_s=None,
                # Keep a physically reasonable 0.285--0.325 m incoming orbit
                # throughout the course.  The inherited late 0.20--0.24 m
                # reset required roughly twice the active racket impulse and
                # was experimentally incompatible with the strict vxy gate.
                falling_reset_apex_height_range_m=(0.285, 0.325),
                # The vertical target builds smoothly and is held through
                # contact. XY/pose/vxy/omega constraints remain active; only
                # the surface-Z position term is suppressed during the stroke.
                fixed_contact_recurrent_launch_vz_reward_weight=0.0,
                fixed_contact_smooth_stroke_vz_penalty_weight=(
                    0.0 if index == 4 else 1.0
                ),
                fixed_contact_smooth_stroke_peak_m_s=0.8,
                fixed_contact_smooth_stroke_lead_s=0.24,
                fixed_contact_smooth_stroke_brake_lead_s=0.12,
                fixed_contact_smooth_stroke_error_scale_m_s=0.20,
                fixed_contact_smooth_stroke_min_hit_count=0,
                fixed_contact_s0_suppress_z_during_launch=True,
                fixed_contact_pre_hit_launch_reward_stops_on_pending_hit=True,
                fixed_contact_pending_hit_retract_vz_reward_weight=(
                    0.0 if index == 4 else 0.75
                ),
                fixed_contact_pending_hit_retract_command_vz_reward_weight=(
                    0.0 if index == 4 else 0.50
                ),
                fixed_contact_pending_hit_retract_vz_target_m_s=0.5,
                fixed_contact_pending_hit_retract_vz_window_s=0.10,
                fixed_contact_pending_hit_retract_all_hits=True,
            )
            # Keep acquisition and its quality bridges at the center. Widen
            # only after the strict center-quality contract has been learned.
            if index <= 8:
                cfg_updates.update(
                    episode_target_x_range_m=(0.0, 0.0),
                    episode_target_y_range_m=(0.0, 0.0),
                )
            if index in workspace_support:
                x_range, y_range, label = workspace_support[index]
                cfg_updates.update(
                    episode_target_x_range_m=x_range,
                    episode_target_y_range_m=y_range,
                )
                name = f"v84_s1_workspace_{label}_bridge"
                cfg_updates["fixed_contact_training_phase"] = name
            elif index >= 14:
                cfg_updates.update(
                    episode_target_x_range_m=(-0.30, 0.20),
                    episode_target_y_range_m=(-0.12, 0.18),
                )
            notes = (
                f"{stage.notes} V84 uses a causal falling-contact reset and "
                "a finite smooth Z stroke held through contact, followed by "
                "bounded recurrent retraction. Workspace support "
                "widens monotonically only after center acquisition/quality."
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, **cfg_updates),
                notes=notes,
            )
        )
    # Preserve the explicitly registered acquisition identity used by the
    # actor-only resume validator and launcher.
    result[4] = replace(
        result[4],
        name="v84_s1_contact_acquisition_only",
        cfg=replace(
            result[4].cfg,
            fixed_contact_training_phase="v84_s1_contact_acquisition_only",
        ),
    )
    return result


def _with_fixed_cartesian_pose_constraint(
    stage: CurriculumStage,
    *,
    name: str,
    roll_pitch_limit_deg: float,
    projection_penalty_weight: float,
    min_updates: int | None = None,
    convergence_hold_updates: int | None = None,
    notes: str,
) -> CurriculumStage:
    """Promote one fixed-contact cfg into the opt-in constrained subclass."""

    values = {
        field.name: getattr(stage.cfg, field.name)
        for field in fields(MjxFixedContactCartesianPoseConstraintConfig)
        if hasattr(stage.cfg, field.name)
    }
    values.update(
        fixed_contact_training_phase=name,
        cartesian_pose_projection_enabled=True,
        cartesian_pose_position_lower_m=(-0.348, -0.700, 1.002),
        cartesian_pose_position_upper_m=(0.348, -0.280, 1.120),
        cartesian_pose_rpy_axis_enabled=(True, True, False),
        cartesian_pose_roll_limit_deg=float(roll_pitch_limit_deg),
        cartesian_pose_pitch_limit_deg=float(roll_pitch_limit_deg),
        cartesian_pose_position_margin_m=0.0005,
        cartesian_pose_orientation_margin_deg=0.10,
        cartesian_pose_position_cbf_gain_s=20.0,
        cartesian_pose_orientation_cbf_gain_s=20.0,
        cartesian_pose_projection_sweeps=24,
        cartesian_pose_projection_tolerance=2.0e-5,
        cartesian_pose_projection_penalty_weight=float(
            projection_penalty_weight
        ),
    )
    cfg = MjxFixedContactCartesianPoseConstraintConfig(**values)
    updates: dict[str, object] = {
        "name": name,
        "cfg": cfg,
        "notes": f"{stage.notes} {notes}".strip(),
    }
    if min_updates is not None:
        updates["min_updates"] = max(int(stage.min_updates), int(min_updates))
    if convergence_hold_updates is not None:
        updates["convergence_hold_updates"] = int(
            convergence_hold_updates
        )
    return replace(stage, **updates)


def _fixed_contact_plane_vision_robust_qvel_rmp_v85_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU0 from-scratch V83 course with a staged hard Cartesian set."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v83_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    limits_deg = (15.0, 8.0, 5.0, 2.0)
    penalties = (0.010, 0.020, 0.035, 0.050)
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        limit_index = min(index, len(limits_deg) - 1)
        name = stage.name.replace("v83_", "v85_", 1)
        constraint_source = stage
        xy_bin_note = ""
        if index == 7:
            # V81/V83 accidentally paired equal-bin/factorized validation
            # with disabled XY-bin sampling for the center-only stratified
            # lesson. MjxJuggleEnv correctly rejects that inconsistent
            # contract. V85 fixes only its opt-in copy: the episode target
            # ranges remain exactly (0, 0), so this stratifies the five blend
            # choices without widening the XY task distribution.
            constraint_source = replace(
                stage,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_xy_bin_sampling_enabled=True,
                ),
            )
            xy_bin_note = (
                " The center-only stratified lesson explicitly enables "
                "XY-bin sampling required by its equal-bin evaluator; its "
                "zero-width center target support is unchanged."
            )
        result.append(
            _with_fixed_cartesian_pose_constraint(
                constraint_source,
                name=name,
                roll_pitch_limit_deg=limits_deg[limit_index],
                projection_penalty_weight=penalties[limit_index],
                min_updates=40 if index < 4 else None,
                notes=(
                    "V85 keeps the absolute XYZ hard set active and stages "
                    f"the relative roll/pitch limit at +/-{limits_deg[limit_index]:g} "
                    "degrees; yaw stays free. The small projection cost teaches "
                    "the actor to remain inside the shield instead of relying "
                    f"on repeated intervention.{xy_bin_note}"
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v86_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU1 from-scratch falling-contact course with constraint homotopy."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v84_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    acquisition_source = source[4]
    bridge_specs = (
        ("v86_s1_cartesian_rp15_acquisition", 15.0, 0.010, 40, 8),
        ("v86_s1_cartesian_rp8_acquisition", 8.0, 0.020, 50, 10),
        ("v86_s1_cartesian_rp5_acquisition", 5.0, 0.035, 60, 12),
        ("v86_s1_cartesian_rp2_acquisition", 2.0, 0.050, 80, 16),
    )
    result = [
        _with_fixed_cartesian_pose_constraint(
            acquisition_source,
            name=name,
            roll_pitch_limit_deg=limit_deg,
            projection_penalty_weight=penalty_weight,
            min_updates=min_updates,
            convergence_hold_updates=hold_updates,
            notes=(
                "V86 constraint acquisition uses only the centered causal "
                "falling-contact reset with every motion/outcome quality gate "
                f"still disabled while roll/pitch tighten to +/-{limit_deg:g} "
                "degrees; the absolute XYZ set is already hard and yaw is free."
            ),
        )
        for name, limit_deg, penalty_weight, min_updates, hold_updates in (
            bridge_specs
        )
    ]
    for stage in source[5:]:
        name = stage.name.replace("v84_", "v86_", 1)
        result.append(
            _with_fixed_cartesian_pose_constraint(
                stage,
                name=name,
                roll_pitch_limit_deg=2.0,
                projection_penalty_weight=0.050,
                notes=(
                    "V86 holds the final +/-2 degree roll/pitch and absolute "
                    "XYZ hard set while the existing quality and workspace "
                    "lessons advance; yaw remains unconstrained."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v87_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair V85's sparse inner-workspace diagonal/blend discontinuity."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v85_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def renamed(stage: CurriculumStage) -> CurriculumStage:
        name = stage.name.replace("v85_", "v87_", 1)
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name),
            notes=f"{stage.notes} V87 preserves this V85 lesson exactly.",
        )

    strict_inner = source[10]

    def corner_bridge(
        *,
        name: str,
        blends: tuple[float, ...],
        apex_range_m: tuple[float, float],
        time_to_contact_range_s: tuple[float, float],
        ready_target: float,
        arrival_target: float,
        min_updates: int,
        hold_updates: int,
        notes: str,
    ) -> CurriculumStage:
        cfg = replace(
            strict_inner.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_eval_grid_x_m=(-0.10, 0.10),
            fixed_contact_eval_grid_y_m=(-0.06, 0.06),
            fixed_contact_factorized_reset_evaluation=True,
            fixed_contact_factorized_reset_validation_enabled=True,
            fixed_contact_factorized_reset_validation_blend_choices=blends,
            falling_reset_racket_follow_episode_target_xy_blend_range=None,
            falling_reset_racket_follow_episode_target_xy_blend_choices=blends,
            falling_reset_apply_target_follow_blend_choices=True,
            falling_reset_apex_height_range_m=apex_range_m,
            falling_reset_time_to_contact_range_s=time_to_contact_range_s,
            fixed_contact_s0_settle_lead_s=0.08,
        )
        return replace(
            strict_inner,
            name=name,
            cfg=cfg,
            min_updates=min_updates,
            convergence_hold_updates=hold_updates,
            min_recent_fixed_contact_s0_ready_fraction=ready_target,
            min_recent_fixed_contact_s0_arrival_ready_fraction=arrival_target,
            notes=notes,
        )

    hard_blend_repair = corner_bridge(
        name="v87_s0_inner_corner_hard_blend_repair",
        blends=(0.0, 0.25),
        apex_range_m=(0.35, 0.38),
        time_to_contact_range_s=(0.50, 0.53),
        ready_target=0.60,
        arrival_target=0.52,
        min_updates=80,
        hold_updates=10,
        notes=(
            "V87 concentrates the first repair on the four inner-workspace "
            "corners and the two low-follow reset blends. Frozen V85-u5350 "
            "diagnostics found both opposing blend-zero diagonals at zero "
            "readiness while 43/45 cells were mostly healthy. The longer "
            "arrival range and 80 ms settle lead match the previously passed "
            "V85 factorial bridge; Cartesian XYZ and +/-2 degree roll/pitch "
            "hard constraints remain unchanged and yaw remains free."
        ),
    )
    full_blend_commit = corner_bridge(
        name="v87_s0_inner_corner_full_blend_commit",
        blends=(0.0, 0.25, 0.5, 0.75, 1.0),
        apex_range_m=(0.30, 0.34),
        time_to_contact_range_s=(0.45, 0.49),
        ready_target=0.75,
        arrival_target=0.68,
        min_updates=100,
        hold_updates=12,
        notes=(
            "V87 restores every registered blend at the four corners and "
            "tightens the arrival timing only after the hard low-follow "
            "population has passed. The final full 45-cell reproof and its "
            "0.85/0.80 gate remain unchanged after this bridge."
        ),
    )
    return [
        *(renamed(stage) for stage in source[:10]),
        hard_blend_repair,
        full_blend_commit,
        *(renamed(stage) for stage in source[10:]),
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v88_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Bound S0 reset displacement while retaining absolute XY coverage."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v85_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    blend_support = {
        # The Cartesian reset is target_xy * blend, so the remaining
        # acquisition distance is norm(target_xy) * (1 - blend).  These
        # supports cap it at 58.3, 58.3 and 70.0 mm respectively.  The final
        # value remains wider than the registered 50 mm per-bounce target
        # displacement while avoiding V85's artificial 350 mm reset jump.
        10: (0.50, 0.75, 1.00),
        11: (0.75, 1.00),
        12: (0.80, 1.00),
    }
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v85_", "v88_", 1)
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        notes = f"{stage.notes} V88 preserves this V85 lesson exactly."
        if index in blend_support:
            choices = blend_support[index]
            cfg_updates.update(
                falling_reset_racket_follow_episode_target_xy_blend_range=None,
                falling_reset_racket_follow_episode_target_xy_blend_choices=(
                    choices
                ),
                falling_reset_apply_target_follow_blend_choices=True,
                fixed_contact_factorized_reset_validation_blend_choices=(
                    choices
                ),
            )
            maximum_reset_distance_m = (0.0584, 0.0584, 0.0700)[index - 10]
            notes = (
                f"V88 retains this stage's complete absolute target XY "
                f"support and every readiness gate, but bounds its "
                f"Cartesian reset-to-target acquisition distance to at most "
                f"{1000.0 * maximum_reset_distance_m:.1f} mm. The old "
                "factorized low-blend cells demanded an artificial long "
                "move that exceeded the in-view falling-ball preparation "
                "window; later collision-on domains already reset at the "
                "episode target and remain unchanged."
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, **cfg_updates),
                notes=notes,
            )
        )
    return result


def _renamed_fixed_contact_1024_batch_stages(
    source: list[CurriculumStage],
    *,
    source_prefix: str,
    target_prefix: str,
    version: str,
) -> list[CurriculumStage]:
    """Clone a course for the opt-in 1024-environment PPO batch shape."""

    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace(source_prefix, target_prefix, 1)
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, fixed_contact_training_phase=name),
                notes=(
                    f"{stage.notes} {version} changes only the launcher-owned "
                    "1024-environment batch-shape contract; environment, "
                    "reward, control, observation and curriculum gates are "
                    "unchanged."
                ).strip(),
            )
        )
    return result


