def _fixed_contact_plane_vision_robust_qvel_rmp_v92_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Keep V91 training/stage semantics while reducing validation lanes."""

    result = [
        replace(
            stage,
            notes=(
                f"{stage.notes} V92 preserves the V91 stage identity and all "
                "training semantics; only the launcher-owned advance-validation "
                "parallelism and completed-episode floor change from 64 to "
                "32 so full-horizon stages remain capacity-feasible."
            ).strip(),
        )
        for stage in _fixed_contact_plane_vision_robust_qvel_rmp_v91_stages(
            stages,
            measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        )
    ]
    for validation_stage in result:
        validate_advance_eval_episode_capacity(
            min_episodes=32,
            min_len_frac=float(validation_stage.target_mean_len_frac),
            horizon_steps=max(
                1,
                int(validation_stage.cfg.horizon_sec / 0.005),
            ),
            eval_envs=32,
            eval_steps=1200,
        )
    return result


