def _fixed_contact_plane_vision_robust_qvel_rmp_v95_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair GPU0's unsafe edge reset and incomplete factorial validator."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v93_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def renamed(stage: CurriculumStage) -> CurriculumStage:
        name = stage.name.replace("v89_", "v95_", 1)
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name),
            notes=f"{stage.notes} V95 preserves this lesson otherwise.",
        )

    full_workspace = source[12]
    safe_cfg = replace(
        full_workspace.cfg,
        falling_reset_racket_follow_ik_orientation_weight=0.25,
        cartesian_pose_require_reset_reference_safe=True,
    )
    bridge_name = "v95_s0_full_workspace_safe_reset_bridge"
    bridge = replace(
        full_workspace,
        name=bridge_name,
        cfg=replace(safe_cfg, fixed_contact_training_phase=bridge_name),
        min_recent_fixed_contact_s0_ready_fraction=0.70,
        min_recent_fixed_contact_s0_arrival_ready_fraction=0.65,
        fixed_contact_s0_gate_per_episode_and_bin=False,
        min_updates=40,
        convergence_hold_updates=8,
        notes=(
            "V95 reconstructs the full-workspace reset IK with stronger pose "
            "weighting and refuses any lookup reference outside the unchanged "
            "absolute XYZ and +/-2 degree roll/pitch hard set. The bridge "
            "keeps the complete 6x6x2 population while introducing the "
            "corrected reset geometry with attainable aggregate readiness "
            "gates. Per-cell gating returns in the following commit stage."
        ),
    )
    commit_name = "v95_s0_full_workspace_safe_reset_commit"
    commit = replace(
        full_workspace,
        name=commit_name,
        cfg=replace(safe_cfg, fixed_contact_training_phase=commit_name),
        notes=(
            "V95 re-proves the corrected complete 6x6 XY by two-blend "
            "population at the original 0.80/0.75 readiness gates. Advance "
            "validation must allocate all 72 deterministic lanes."
        ),
    )
    tail: list[CurriculumStage] = []
    for stage in source[13:]:
        name = stage.name.replace("v89_", "v95_", 1)
        tail.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    falling_reset_racket_follow_ik_orientation_weight=0.25,
                    cartesian_pose_require_reset_reference_safe=True,
                ),
                notes=(
                    f"{stage.notes} V95 retains the corrected, fail-closed "
                    "reset-reference safety audit in every downstream domain."
                ),
            )
        )
    return [*(renamed(stage) for stage in source[:12]), bridge, commit, *tail]


def _fixed_contact_plane_vision_robust_qvel_rmp_v96_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair GPU1's seven-way constraint dilution with a staged bridge."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v94_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def with_reward_contract(
        stage: CurriculumStage,
        *,
        name: str,
        outcome_weight: float,
        outcome_bonus: float,
        racket_vxy_weight: float,
        racket_omega_weight: float,
    ) -> CurriculumStage:
        return replace(
            stage,
            name=name,
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=name,
                fixed_contact_outcome_constraint_aggregation="mean",
                fixed_contact_outcome_constraint_penalty_weight=outcome_weight,
                fixed_contact_outcome_constraint_bonus_weight=outcome_bonus,
                hit_racket_vxy_penalty_weight=racket_vxy_weight,
                hit_racket_angular_speed_penalty_weight=racket_omega_weight,
            ),
        )

    prefix = [
        replace(
            stage,
            name=stage.name.replace("v91_", "v96_", 1),
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=stage.name.replace(
                    "v91_", "v96_", 1
                ),
            ),
            notes=f"{stage.notes} V96 preserves this prerequisite.",
        )
        for stage in source[:9]
    ]
    active = source[9]
    bridge = with_reward_contract(
        active,
        name="v96_s1_workspace_inner_outcome_repair_bridge",
        outcome_weight=0.875,
        outcome_bonus=0.50,
        racket_vxy_weight=3.0,
        racket_omega_weight=1.5,
    )
    bridge = replace(
        bridge,
        max_recent_mean_hit_racket_vxy=0.060,
        max_recent_fixed_contact_return_horizontal_step_m=0.060,
        min_recent_fixed_contact_return_center_progress_m=-0.006,
        min_updates=40,
        convergence_hold_updates=8,
        notes=(
            "V96 resumes the closest full-state V92 checkpoint before the "
            "long survival/quality tradeoff. It restores half of the "
            "per-component strength lost when seven constraint costs were "
            "changed from sum to mean, and tightens sparse racket losses "
            "gradually under near-parent motion gates."
        ),
    )
    commit = with_reward_contract(
        active,
        name="v96_s1_workspace_inner_outcome_repair_commit",
        outcome_weight=1.75,
        outcome_bonus=1.0,
        racket_vxy_weight=4.0,
        racket_omega_weight=2.0,
    )
    commit = replace(
        commit,
        notes=(
            "V96 restores the full per-component scale of the historical "
            "0.25 sum-aggregated loss (0.25 x seven = 1.75 under mean) and "
            "reinstates the original inner-workspace motion/return gates."
        ),
    )
    tail: list[CurriculumStage] = []
    for stage in source[10:]:
        name = stage.name.replace("v91_", "v96_", 1)
        tail.append(
            replace(
                with_reward_contract(
                    stage,
                    name=name,
                    outcome_weight=1.75,
                    outcome_bonus=1.0,
                    racket_vxy_weight=4.0,
                    racket_omega_weight=2.0,
                ),
                notes=(
                    f"{stage.notes} V96 retains the gate-aligned normalized "
                    "outcome and racket-motion losses after the bridge."
                ),
            )
        )
    return [*prefix, bridge, commit, *tail]


def _fixed_contact_plane_vision_robust_qvel_rmp_v97_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair GPU0's underweighted center-return objective in two steps."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v95_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def renamed(stage: CurriculumStage) -> CurriculumStage:
        name = stage.name.replace("v95_", "v97_", 1)
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name),
        )

    active = source[14]
    bridge_name = "v97_s1_center_outcome_repair_bridge"
    bridge = replace(
        active,
        name=bridge_name,
        cfg=replace(
            active.cfg,
            fixed_contact_training_phase=bridge_name,
            fixed_contact_outcome_constraint_aggregation="mean",
            fixed_contact_outcome_constraint_penalty_weight=1.0,
            fixed_contact_outcome_constraint_bonus_weight=0.75,
        ),
        min_recent_fixed_contact_return_center_progress_m=-0.005,
        min_updates=40,
        convergence_hold_updates=8,
        notes=(
            "V97 keeps the exact V95 center-domain control, direct motion "
            "penalties and safety gates while doubling the seven-way "
            "mean-aggregated outcome signal. The temporary -5 mm center "
            "gate bridges the saved V95 policy toward, but does not replace, "
            "the original -2 mm requirement."
        ),
    )
    commit_name = "v97_s1_center_outcome_repair_commit"
    commit = replace(
        active,
        name=commit_name,
        cfg=replace(
            active.cfg,
            fixed_contact_training_phase=commit_name,
            fixed_contact_outcome_constraint_aggregation="mean",
            fixed_contact_outcome_constraint_penalty_weight=1.75,
            fixed_contact_outcome_constraint_bonus_weight=1.0,
        ),
        notes=(
            "V97 restores the full per-component strength of the historical "
            "0.25 sum loss (0.25 x seven = 1.75 under mean aggregation) and "
            "reinstates the unchanged V95 -2 mm center-return gate."
        ),
    )
    tail = []
    for stage in source[15:]:
        repaired = renamed(stage)
        tail.append(
            replace(
                repaired,
                cfg=replace(
                    repaired.cfg,
                    fixed_contact_outcome_constraint_aggregation="mean",
                    fixed_contact_outcome_constraint_penalty_weight=1.75,
                    fixed_contact_outcome_constraint_bonus_weight=1.0,
                ),
                notes=(
                    f"{repaired.notes} V97 retains the gate-aligned outcome "
                    "scale after the center-return repair."
                ),
            )
        )
    return [*(renamed(stage) for stage in source[:14]), bridge, commit, *tail]


