def _fixed_contact_plane_vision_robust_qvel_rmp_v100_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair GPU1's measured low-X/high-Y generalization failure first."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v98_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def renamed(stage: CurriculumStage) -> CurriculumStage:
        name = stage.name.replace("v96_", "v100_", 1)
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name),
        )

    active = source[16]
    corner_cfg = {
        "episode_target_x_range_m": (-0.30, -0.20),
        "episode_target_y_range_m": (0.12, 0.18),
        "fixed_contact_eval_grid_x_m": (-0.30, -0.20),
        "fixed_contact_eval_grid_y_m": (0.12, 0.18),
        "fixed_contact_xy_bin_sampling_enabled": True,
    }
    bridge_name = "v100_s2_hard_xy_corner_bridge"
    bridge = replace(
        active,
        name=bridge_name,
        cfg=replace(
            active.cfg,
            fixed_contact_training_phase=bridge_name,
            fixed_contact_xy_bin_jitter_m=0.025,
            **corner_cfg,
        ),
        target_mean_hits=1.45,
        target_mean_len_frac=0.55,
        target_hit1_rate=0.72,
        target_hit3_rate=0.05,
        target_episode_truncation_rate=0.30,
        min_recent_fixed_contact_outcome_all_ready_fraction=0.08,
        min_advance_fixed_contact_xy_bin_success_rate=0.35,
        min_updates=40,
        convergence_hold_updates=8,
        notes=(
            "V100 isolates the low-X/high-Y corner family identified by both "
            "failed V98 36-bin validators. It begins with half jitter and "
            "intermediate recurrent gates so the selected V98 best actor can "
            "adapt without losing its global two-contact behavior."
        ),
    )
    commit_name = "v100_s2_hard_xy_corner_commit"
    commit = replace(
        active,
        name=commit_name,
        cfg=replace(
            active.cfg,
            fixed_contact_training_phase=commit_name,
            fixed_contact_xy_bin_jitter_m=0.050,
            **corner_cfg,
        ),
        min_updates=max(60, int(active.min_updates)),
        convergence_hold_updates=max(
            12, int(active.convergence_hold_updates)
        ),
        notes=(
            "V100 restores full 50 mm XY-bin jitter on the four measured hard "
            "corner bins and requires the original two-contact online, reset "
            "and fixed-bin gates before returning to the full workspace."
        ),
    )
    full_name = "v100_s2_full_workspace_reproof"
    full = replace(
        active,
        name=full_name,
        cfg=replace(active.cfg, fixed_contact_training_phase=full_name),
        notes=(
            "V100 returns to the byte-for-byte V98 two-contact environment, "
            "reward and gates and must re-prove all 36 XY bins after the "
            "targeted corner lessons."
        ),
    )
    return [
        *(renamed(stage) for stage in source[:16]),
        bridge,
        commit,
        full,
        *(renamed(stage) for stage in source[17:]),
    ]


