def _fixed_contact_plane_vision_robust_qvel_rmp_v129_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Bridge V128's passed repair into commit without its abrupt credit jump."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v128_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def renamed(stage: CurriculumStage) -> CurriculumStage:
        name = stage.name.replace("v128_", "v129_", 1)
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name),
        )

    repair = source[18]
    transition_name = "v129_s1_motion_apex_conjunction_transition"
    transition = replace(
        repair,
        name=transition_name,
        cfg=replace(
            repair.cfg,
            fixed_contact_training_phase=transition_name,
            hit_racket_vxy_quality_gate_sigma_m_s=0.0625,
            hit_racket_vxy_quality_gate_floor=0.225,
            fixed_contact_apex_error_penalty_weight=0.1875,
        ),
        max_recent_mean_hit_racket_vxy=0.065,
        min_recent_fixed_contact_return_apex_score=0.285,
        min_recent_fixed_contact_outcome_all_ready_fraction=0.05,
        min_advance_fixed_contact_xy_bin_success_rate=0.35,
        min_updates=40,
        convergence_hold_updates=8,
        notes=(
            "V129 resumes the V128 update-128 stage that passed its automatic "
            "block, retains the repaired 0.50 joint-credit mix and low-X "
            "actor focus, and inserts exact midpoint speed/apex shaping. The "
            "intermediate gates require conjunction retention before commit."
        ),
    )
    old_commit = source[19]
    commit_name = "v129_s1_motion_apex_conjunction_commit"
    commit = replace(
        old_commit,
        name=commit_name,
        cfg=replace(
            old_commit.cfg,
            fixed_contact_training_phase=commit_name,
            fixed_contact_event_joint_quality_gate_mix=0.50,
        ),
        notes=(
            f"{old_commit.notes} V129 retains the empirically viable 0.50 "
            "joint-credit mix instead of V128's rejected 0.75 step; all "
            "strict physical, reset-CVaR and 36-bin commit gates are unchanged."
        ),
    )
    return [
        *(renamed(stage) for stage in source[:19]),
        transition,
        commit,
        *(renamed(stage) for stage in source[20:]),
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v130_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Retarget V127's actor mass to its repeatedly failed outermost corner."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v127_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("v127_", "v130_", 1)
        notes = stage.notes
        if stage.name == "v127_s2_joint_lane_angular_reproof":
            name = "v130_s2_exact_corner_angular_reproof"
            notes = (
                f"{notes} V130 preserves every V127 environment, reward, "
                "gate and PPO value. Its launcher replaces four-bin 4.0x "
                "focus with bounded 8.0x actor focus only on the repeatedly "
                "failed (-0.30,+0.18) outer-corner bin."
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, fixed_contact_training_phase=name),
                notes=notes,
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v131_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Retain predicted arrival while teaching a late vertical hit cycle."""

    s0_source = _fixed_contact_plane_vision_robust_qvel_rmp_v95_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    outcome_source = _fixed_contact_plane_vision_robust_qvel_rmp_v129_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def renamed_s0(stage: CurriculumStage) -> CurriculumStage:
        name = stage.name.replace("v95_", "v131_", 1)
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, fixed_contact_training_phase=name),
            notes=(
                f"{stage.notes} V131 preserves the passed V95 prediction-"
                "arrival lesson exactly before enabling collision."
            ),
        )

    def cycle_stage(
        stage: CurriculumStage,
        *,
        name: str,
        x_range_m: tuple[float, float] | None = None,
        y_range_m: tuple[float, float] | None = None,
        peak_m_s: float = 0.80,
        stroke_weight: float = 1.0,
        arrival_fraction: float = 0.35,
        **stage_updates: object,
    ) -> CurriculumStage:
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
            "fixed_contact_s0_arrival_window_s": (0.080, 0.100),
            "fixed_contact_s0_settle_lead_s": 0.080,
            "fixed_contact_pre_hit_s0_reward_max_s": 0.0,
            "fixed_contact_falling_pre_hit_s0_reward_max_s": 0.46,
            "fixed_contact_first_hit_deadline_s": 0.50,
            "fixed_contact_smooth_stroke_vz_penalty_weight": stroke_weight,
            "fixed_contact_smooth_stroke_peak_m_s": peak_m_s,
            "fixed_contact_smooth_stroke_lead_s": 0.080,
            "fixed_contact_smooth_stroke_brake_lead_s": 0.020,
            "fixed_contact_smooth_stroke_error_scale_m_s": 0.20,
            "fixed_contact_smooth_stroke_min_hit_count": 0,
            "fixed_contact_post_hit_s0_window_s": 0.300,
            "fixed_contact_s0_suppress_z_during_launch": True,
            "fixed_contact_pending_hit_retract_vz_reward_weight": 0.75,
            "fixed_contact_pending_hit_retract_vz_target_m_s": 0.50,
            "fixed_contact_pending_hit_retract_vz_window_s": 0.100,
            "fixed_contact_pending_hit_retract_command_vz_reward_weight": 0.50,
            "fixed_contact_pending_hit_retract_all_hits": True,
        }
        if x_range_m is not None:
            cfg_updates["episode_target_x_range_m"] = x_range_m
        if y_range_m is not None:
            cfg_updates["episode_target_y_range_m"] = y_range_m
        return replace(
            stage,
            name=name,
            cfg=replace(stage.cfg, **cfg_updates),
            min_recent_fixed_contact_s0_arrival_ready_fraction=(
                arrival_fraction
            ),
            fixed_contact_s0_gate_use_advance_eval=True,
            notes=(
                f"{stage.notes} V131 requires the actor to be inside the "
                "complete predicted contact pose/motion gate 80--100 ms "
                "before impact. Only then does a cosine late upstroke begin; "
                "Z stationarity is masked during that stroke, XY/pose remain "
                "active, and every physical contact is followed by a bounded "
                "100 ms retraction and a 300 ms next-contact recovery window."
            ),
            **stage_updates,
        )

    center_bridge = cycle_stage(
        outcome_source[14],
        name="v131_s1_center_late_stroke_bridge",
        peak_m_s=0.45,
        stroke_weight=0.50,
        arrival_fraction=0.50,
        target_mean_hits=0.30,
        target_hit1_rate=0.30,
        target_hit3_rate=None,
        target_mean_len_frac=0.30,
        min_updates=40,
        convergence_hold_updates=8,
    )
    center_commit = cycle_stage(
        outcome_source[15],
        name="v131_s1_center_late_stroke_commit",
        peak_m_s=0.60,
        stroke_weight=0.75,
        arrival_fraction=0.50,
    )
    center_recurrent = cycle_stage(
        outcome_source[16],
        name="v131_s1_center_recurrent_cycle",
        arrival_fraction=0.45,
    )
    workspace_specs = (
        (
            "v131_s1_workspace_local_cycle",
            (-0.05, 0.05),
            (-0.04, 0.04),
            0.60,
            0.60,
            0.45,
        ),
        (
            "v131_s1_workspace_inner_cycle",
            (-0.10, 0.10),
            (-0.06, 0.06),
            0.65,
            0.62,
            0.42,
        ),
        (
            "v131_s1_workspace_mid_cycle",
            (-0.20, 0.10),
            (-0.12, 0.12),
            0.68,
            0.64,
            0.38,
        ),
        (
            "v131_s1_workspace_full_cycle",
            (-0.30, 0.20),
            (-0.12, 0.18),
            0.70,
            0.65,
            0.35,
        ),
    )
    workspace = [
        cycle_stage(
            outcome_source[17],
            name=name,
            x_range_m=x_range_m,
            y_range_m=y_range_m,
            arrival_fraction=arrival_fraction,
            target_mean_hits=target_hits,
            target_hit1_rate=target_hit1,
            target_hit3_rate=None,
            min_updates=40,
            convergence_hold_updates=8,
        )
        for (
            name,
            x_range_m,
            y_range_m,
            target_hits,
            target_hit1,
            arrival_fraction,
        ) in workspace_specs
    ]
    repaired_tail = [
        cycle_stage(
            stage,
            name=stage.name.replace("v129_", "v131_", 1),
            arrival_fraction=0.35,
        )
        for stage in outcome_source[18:]
    ]
    return [
        *(renamed_s0(stage) for stage in s0_source[:14]),
        center_bridge,
        center_commit,
        center_recurrent,
        *workspace,
        *repaired_tail,
    ]


def _fixed_contact_plane_vision_robust_qvel_rmp_v132_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Learn placed-ball juggling directly across randomized racket poses."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v86_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )

    def support_grid(
        bounds_m: tuple[float, float],
        canonical_grid_m: tuple[float, ...],
    ) -> tuple[float, ...]:
        """Retain canonical lanes while always covering a lesson's edges."""

        lower, upper = sorted(float(value) for value in bounds_m)
        lanes = {lower, upper}
        lanes.update(
            float(value)
            for value in canonical_grid_m
            if lower <= float(value) <= upper
        )
        if lower <= 0.0 <= upper:
            lanes.add(0.0)
        return tuple(sorted(lanes))

    def placed_cycle_cfg(
        stage: CurriculumStage,
        *,
        name: str,
        x_range_m: tuple[float, float],
        y_range_m: tuple[float, float],
        hold_s: float,
        launch_actual_weight: float,
        launch_command_weight: float,
        launch_window_s: float,
        recurrent_stroke: bool,
    ) -> object:
        return replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            ball_reset_mode="racket_launch",
            episode_target_x_range_m=x_range_m,
            episode_target_y_range_m=y_range_m,
            fixed_contact_eval_grid_x_m=support_grid(
                x_range_m,
                tuple(stage.cfg.fixed_contact_eval_grid_x_m),
            ),
            fixed_contact_eval_grid_y_m=support_grid(
                y_range_m,
                tuple(stage.cfg.fixed_contact_eval_grid_y_m),
            ),
            racket_launch_racket_follow_episode_target_xy=True,
            racket_launch_racket_follow_fixed_contact_surface_z=True,
            falling_reset_racket_follow_contact_y=False,
            falling_reset_racket_follow_episode_target_xy=False,
            falling_reset_racket_follow_fixed_contact_surface_z=False,
            falling_reset_racket_follow_episode_target_xy_blend=1.0,
            falling_reset_racket_follow_episode_target_xy_blend_range=None,
            falling_reset_racket_follow_episode_target_xy_blend_choices=None,
            falling_reset_apply_target_follow_blend_choices=False,
            racket_launch_hold_time_s=hold_s,
            racket_launch_hold_time_range_s=None,
            racket_launch_pre_release_control_mode="hold_command",
            racket_launch_vxy_max=0.0,
            racket_launch_vnormal_max=0.0,
            fixed_contact_s0_arrival_window_s=(0.080, 0.100),
            fixed_contact_s0_settle_lead_s=0.080,
            fixed_contact_pre_hit_s0_reward_max_s=0.0,
            fixed_contact_falling_pre_hit_s0_reward_max_s=0.0,
            fixed_contact_first_hit_deadline_s=0.50,
            fixed_contact_pre_hit_launch_vz_reward_weight=(
                launch_actual_weight
            ),
            fixed_contact_pre_hit_launch_vz_target_m_s=0.50,
            fixed_contact_pre_hit_launch_vz_window_s=launch_window_s,
            fixed_contact_pre_hit_launch_command_vz_reward_weight=(
                launch_command_weight
            ),
            fixed_contact_pre_hit_launch_reward_stops_on_pending_hit=True,
            fixed_contact_smooth_stroke_vz_penalty_weight=(
                1.0 if recurrent_stroke else 0.0
            ),
            fixed_contact_smooth_stroke_peak_m_s=0.80,
            fixed_contact_smooth_stroke_lead_s=0.080,
            fixed_contact_smooth_stroke_brake_lead_s=0.020,
            fixed_contact_smooth_stroke_error_scale_m_s=0.20,
            fixed_contact_smooth_stroke_min_hit_count=1,
            fixed_contact_post_hit_s0_window_s=0.300,
            fixed_contact_s0_suppress_z_during_launch=True,
            fixed_contact_pending_hit_retract_vz_reward_weight=0.75,
            fixed_contact_pending_hit_retract_vz_target_m_s=0.50,
            fixed_contact_pending_hit_retract_vz_window_s=0.100,
            fixed_contact_pending_hit_retract_command_vz_reward_weight=0.50,
            fixed_contact_pending_hit_retract_all_hits=True,
        )

    launch_specs = (
        (
            0,
            "v132_s1_placed_local_rp15_launch",
            (-0.05, 0.05),
            (-0.04, 0.04),
            0.12,
            20.0,
            40.0,
            0.20,
            0.10,
        ),
        (
            1,
            "v132_s1_placed_local_rp8_launch",
            (-0.08, 0.08),
            (-0.05, 0.05),
            0.09,
            15.0,
            30.0,
            0.17,
            0.20,
        ),
        (
            2,
            "v132_s1_placed_inner_rp5_launch",
            (-0.10, 0.10),
            (-0.06, 0.06),
            0.06,
            10.0,
            20.0,
            0.14,
            0.30,
        ),
        (
            3,
            "v132_s1_placed_mid_rp2_launch",
            (-0.15, 0.15),
            (-0.10, 0.10),
            0.03,
            5.0,
            10.0,
            0.11,
            0.40,
        ),
        (
            3,
            "v132_s1_placed_wide_recurrent_bridge",
            (-0.20, 0.18),
            (-0.12, 0.15),
            0.0,
            2.5,
            5.0,
            0.08,
            0.55,
        ),
        (
            3,
            "v132_s1_placed_full_unassisted_commit",
            (-0.30, 0.20),
            (-0.12, 0.18),
            0.0,
            0.0,
            0.0,
            0.0,
            0.70,
        ),
    )
    launch_stages: list[CurriculumStage] = []
    for (
        source_index,
        name,
        x_range_m,
        y_range_m,
        hold_s,
        actual_weight,
        command_weight,
        reward_window_s,
        hit_target,
    ) in launch_specs:
        source_stage = source[source_index]
        recurrent = len(launch_stages) >= 4
        launch_stages.append(
            replace(
                source_stage,
                name=name,
                cfg=placed_cycle_cfg(
                    source_stage,
                    name=name,
                    x_range_m=x_range_m,
                    y_range_m=y_range_m,
                    hold_s=hold_s,
                    launch_actual_weight=actual_weight,
                    launch_command_weight=command_weight,
                    launch_window_s=reward_window_s,
                    recurrent_stroke=recurrent,
                ),
                target_mean_hits=hit_target,
                target_hit1_rate=hit_target,
                target_hit3_rate=(0.01 if recurrent else None),
                target_mean_len_frac=min(0.45, 0.28 + 0.03 * source_index),
                min_recent_fixed_contact_s0_arrival_ready_fraction=(
                    0.15 if len(launch_stages) == 4 else 0.20
                    if len(launch_stages) == 5 else None
                ),
                fixed_contact_s0_gate_use_advance_eval=recurrent,
                min_updates=max(40, int(source_stage.min_updates)),
                notes=(
                    "V132 starts a new random actor directly on placed-ball "
                    "juggling. The racket and ball share the sampled workspace "
                    "target; launch hold/credit taper to zero while support "
                    "widens. After the first confirmed hit, the actor must "
                    "repeat the 80 ms late upstroke, 100 ms retraction and "
                    "prediction-arrival recovery cycle under the hard "
                    "Cartesian set."
                ),
            )
        )

    # The first six lessons already cover the center-to-full support homotopy;
    # omit V86's redundant falling-reset workspace bridge sequence. Keep its
    # quality and long-horizon ordering, now on randomized placed resets.
    tail_source = [*source[4:7], *source[13:]]
    tail: list[CurriculumStage] = []
    for index, stage in enumerate(tail_source):
        name = stage.name.replace("v86_", "v132_", 1)
        arrival_fraction = 0.20 if index < 3 else 0.25 if index < 6 else 0.30
        tail.append(
            replace(
                stage,
                name=name,
                cfg=placed_cycle_cfg(
                    stage,
                    name=name,
                    x_range_m=(-0.30, 0.20),
                    y_range_m=(-0.12, 0.18),
                    hold_s=0.0,
                    launch_actual_weight=0.0,
                    launch_command_weight=0.0,
                    launch_window_s=0.0,
                    recurrent_stroke=True,
                ),
                min_recent_fixed_contact_s0_arrival_ready_fraction=(
                    arrival_fraction
                ),
                fixed_contact_s0_gate_use_advance_eval=True,
                notes=(
                    f"{stage.notes} V132 keeps the full randomized placed-"
                    "racket support and grades the recurrent late-stroke/"
                    "retraction/predicted-arrival loop together with the "
                    "existing hit, apex, motion and hard-safety gates."
                ),
            )
        )
    return [*launch_stages, *tail]


def _fixed_contact_plane_vision_robust_qvel_rmp_v133_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Close V131's one-hit/full-horizon recurrent-cycle loophole."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v131_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v131_", "v133_", 1)
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        stage_updates: dict[str, object] = {}
        notes = (
            f"{stage.notes} V133 preserves this passed V131 lesson exactly."
        )
        if index >= 16:
            cfg_updates.update(
                fixed_contact_recurrent_hit_deadline_s=0.60,
                post_hit_overdue_penalty_weight=10.0,
                post_hit_overdue_penalty_dt_scaled=True,
                post_hit_overdue_soft_limit_s=0.50,
                post_hit_overdue_penalty_scale_s=0.08,
                full_episode_completion_min_hits=3,
            )
            stage_updates.update(
                hit_interval_gate_source="counted_hit_event",
                target_min_hit_interval_s=0.40,
                target_max_hit_interval_s=0.52,
                target_hit3_rate=max(0.02, float(stage.target_hit3_rate or 0.0)),
            )
            notes = (
                f"{stage.notes} V133 keeps the same prediction-arrival, "
                "late stroke, retraction, RMP, physics and hard Cartesian "
                "contract, but makes a missing next counted contact after "
                "0.60 s an explicit miss. Overdue credit starts at 0.50 s, "
                "and horizon completion requires at least three contacts; "
                "the stage therefore cannot graduate by hitting once and "
                "waiting through the 1.35 s horizon."
            )
        if index == 16:
            name = "v133_s1_center_recurrent_deadline_bridge"
            cfg_updates["fixed_contact_training_phase"] = name
            stage_updates.update(
                target_mean_hits=1.20,
                target_hit1_rate=max(0.65, float(stage.target_hit1_rate or 0.0)),
                target_hit3_rate=0.02,
                target_mean_len_frac=0.65,
                target_episode_truncation_rate=0.10,
                min_updates=80,
                convergence_hold_updates=10,
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, **cfg_updates),
                notes=notes,
                **stage_updates,
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v134_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Teach physical launch outcome, then recurrence, before XY widening."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v132_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source_quality = source[0]
    quality_name = "v134_s1_placed_local_launch_quality"
    quality_cfg = replace(
        source_quality.cfg,
        fixed_contact_training_phase=quality_name,
        fixed_contact_pre_hit_launch_vz_reward_weight=40.0,
        fixed_contact_pre_hit_launch_command_vz_reward_weight=5.0,
        hit_vxy_soft_limit_m_s=0.45,
        hit_vxy_penalty_weight=2.0,
        hit_vxy_penalty_scale_m_s=0.35,
        hit_vxy_apply_from_first_hit=True,
        hit_vxy_zero_reward_weight=1.0,
        hit_vxy_zero_reward_sigma_m_s=0.25,
        early_hit_vxy_penalty_hit_count=1,
        early_hit_vxy_penalty_multiplier=2.0,
        early_hit_vxy_zero_reward_multiplier=2.0,
        hit_next_contact_anchor_penalty_weight=0.10,
        fixed_contact_outcome_constraint_penalty_weight=1.0,
        fixed_contact_outcome_constraint_bonus_weight=0.5,
        fixed_contact_smooth_stroke_vz_penalty_weight=0.0,
        fixed_contact_recurrent_hit_deadline_s=0.0,
        full_episode_completion_min_hits=3,
    )
    quality = replace(
        source_quality,
        name=quality_name,
        cfg=quality_cfg,
        target_mean_hits=0.30,
        target_hit1_rate=0.30,
        target_hit3_rate=None,
        target_episode_truncation_rate=None,
        max_recent_mean_first_hit_ball_vxy=0.75,
        min_recent_fixed_contact_outcome_all_ready_fraction=0.02,
        min_recent_fixed_contact_s0_arrival_ready_fraction=None,
        fixed_contact_s0_gate_use_advance_eval=False,
        min_updates=160,
        convergence_hold_updates=10,
        notes=(
            "V134 starts directly from randomized placed-ball juggling, but "
            "grades the physical racket launch and outgoing first-hit outcome "
            "before widening support. Actual racket vertical velocity carries "
            "8x the command-space proxy; outgoing ball VXY, the next predicted "
            "contact anchor and the fixed-contact hard outcome set are active "
            "from the first counted hit. Full-horizon survival is deliberately "
            "not a first-lesson graduation target."
        ),
    )

    recurrent_name = "v134_s1_placed_local_recurrent_bridge"
    recurrent = replace(
        quality,
        name=recurrent_name,
        cfg=replace(
            quality_cfg,
            fixed_contact_training_phase=recurrent_name,
            racket_launch_hold_time_s=0.09,
            fixed_contact_pre_hit_launch_vz_reward_weight=30.0,
            fixed_contact_pre_hit_launch_command_vz_reward_weight=3.75,
            fixed_contact_smooth_stroke_vz_penalty_weight=1.0,
            fixed_contact_recurrent_hit_deadline_s=0.60,
            post_hit_overdue_penalty_weight=10.0,
            post_hit_overdue_penalty_dt_scaled=True,
            post_hit_overdue_soft_limit_s=0.50,
            post_hit_overdue_penalty_scale_s=0.08,
        ),
        target_mean_hits=1.05,
        target_hit1_rate=0.65,
        target_hit3_rate=0.01,
        target_mean_len_frac=0.60,
        hit_interval_gate_source="counted_hit_event",
        target_min_hit_interval_s=0.40,
        target_max_hit_interval_s=0.52,
        target_episode_truncation_rate=0.05,
        max_recent_mean_first_hit_ball_vxy=0.70,
        min_recent_fixed_contact_s0_arrival_ready_fraction=0.15,
        fixed_contact_s0_gate_use_advance_eval=True,
        min_updates=160,
        convergence_hold_updates=10,
        notes=(
            "V134 keeps the same local placed-ball reset and adds the complete "
            "late-stroke/retraction/prediction-arrival loop before any XY or "
            "roll/pitch widening. A 0.60 s recurrent deadline and three-hit "
            "completion gate align PPO with the requested 0.40--0.50 s cycle."
        ),
    )

    tail: list[CurriculumStage] = []
    for stage in source[1:]:
        name = stage.name.replace("v132_", "v134_", 1)
        actual_weight = float(
            stage.cfg.fixed_contact_pre_hit_launch_vz_reward_weight
        )
        command_weight = float(
            stage.cfg.fixed_contact_pre_hit_launch_command_vz_reward_weight
        )
        tail.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    fixed_contact_pre_hit_launch_vz_reward_weight=max(
                        actual_weight, command_weight
                    ),
                    fixed_contact_pre_hit_launch_command_vz_reward_weight=(
                        0.25 * actual_weight
                    ),
                    fixed_contact_smooth_stroke_vz_penalty_weight=max(
                        1.0,
                        float(
                            stage.cfg.fixed_contact_smooth_stroke_vz_penalty_weight
                        ),
                    ),
                    fixed_contact_recurrent_hit_deadline_s=0.60,
                    post_hit_overdue_penalty_weight=10.0,
                    post_hit_overdue_penalty_dt_scaled=True,
                    post_hit_overdue_soft_limit_s=0.50,
                    post_hit_overdue_penalty_scale_s=0.08,
                    full_episode_completion_min_hits=3,
                    hit_vxy_soft_limit_m_s=min(
                        0.45, float(stage.cfg.hit_vxy_soft_limit_m_s)
                    ),
                    hit_vxy_penalty_weight=max(
                        2.0, float(stage.cfg.hit_vxy_penalty_weight)
                    ),
                    hit_vxy_penalty_scale_m_s=min(
                        0.35, float(stage.cfg.hit_vxy_penalty_scale_m_s)
                    ),
                    hit_vxy_apply_from_first_hit=True,
                    hit_vxy_zero_reward_weight=max(
                        1.0, float(stage.cfg.hit_vxy_zero_reward_weight)
                    ),
                    hit_vxy_zero_reward_sigma_m_s=max(
                        0.25, float(stage.cfg.hit_vxy_zero_reward_sigma_m_s)
                    ),
                    early_hit_vxy_penalty_hit_count=max(
                        1, int(stage.cfg.early_hit_vxy_penalty_hit_count)
                    ),
                    early_hit_vxy_penalty_multiplier=max(
                        2.0, float(stage.cfg.early_hit_vxy_penalty_multiplier)
                    ),
                    hit_next_contact_anchor_penalty_weight=max(
                        0.10,
                        float(stage.cfg.hit_next_contact_anchor_penalty_weight),
                    ),
                    fixed_contact_outcome_constraint_penalty_weight=max(
                        1.0,
                        float(
                            stage.cfg.fixed_contact_outcome_constraint_penalty_weight
                        ),
                    ),
                    fixed_contact_outcome_constraint_bonus_weight=max(
                        0.5,
                        float(
                            stage.cfg.fixed_contact_outcome_constraint_bonus_weight
                        ),
                    ),
                ),
                target_hit3_rate=max(0.01, float(stage.target_hit3_rate or 0.0)),
                hit_interval_gate_source="counted_hit_event",
                target_min_hit_interval_s=0.40,
                target_max_hit_interval_s=0.52,
                max_recent_mean_first_hit_ball_vxy=min(
                    0.70,
                    float(stage.max_recent_mean_first_hit_ball_vxy or 0.70),
                ),
                min_recent_fixed_contact_s0_arrival_ready_fraction=max(
                    0.15,
                    float(
                        stage.min_recent_fixed_contact_s0_arrival_ready_fraction
                        or 0.0
                    ),
                ),
                fixed_contact_s0_gate_use_advance_eval=True,
                notes=(
                    f"{stage.notes} V134 reaches this support only after a "
                    "local physical-outcome lesson and a local recurrent-cycle "
                    "lesson; the recurrent deadline and three-hit completion "
                    "contract remain active throughout widening."
                ),
            )
        )
    return [quality, recurrent, *tail]


def _fixed_contact_plane_vision_robust_qvel_rmp_v135_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair V133's infeasible short-horizon gate and overlaunch credit."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v133_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source[:17]:
        name = stage.name.replace("v133_", "v135_", 1)
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, fixed_contact_training_phase=name),
                notes=(
                    f"{stage.notes} V135 preserves this passed V133 lesson "
                    "and its actor/critic/control contract exactly."
                ),
            )
        )

    source_local = source[17]

    def outcome_cfg(
        stage: CurriculumStage,
        *,
        name: str,
        apex_weight: float,
        reflected_weight: float,
        reflected_xy_sigma_m_s: float,
        reflected_z_sigma_m_s: float,
    ) -> MjxJuggleConfig:
        return replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            # V133's 5.0 dense survival credit and a fixed 0.8 m/s stroke
            # supported a two-hit but progressively over-high attractor.  The
            # smaller survival term retains a dense continuation signal while
            # the two event-level pseudo-Huber terms directly optimize the
            # requested apex and recoverable outgoing velocity.
            post_first_hit_alive_reward_weight=1.4,
            fixed_contact_smooth_stroke_vz_penalty_weight=0.5,
            fixed_contact_smooth_stroke_peak_m_s=0.60,
            fixed_contact_apex_error_penalty_weight=apex_weight,
            fixed_contact_apex_error_penalty_scale_m=0.10,
            hit_adaptive_reflected_velocity_penalty_weight=reflected_weight,
            hit_adaptive_reflected_velocity_xy_sigma_m_s=(
                reflected_xy_sigma_m_s
            ),
            hit_adaptive_reflected_velocity_z_sigma_m_s=(
                reflected_z_sigma_m_s
            ),
            # A one-second falling-contact episode admits the initial contact
            # and one recurrence, not the three contacts V133 requested.
            full_episode_completion_min_hits=2,
        )

    bridge_name = "v135_s1_workspace_local_outcome_bridge"
    bridge = replace(
        source_local,
        name=bridge_name,
        cfg=outcome_cfg(
            source_local,
            name=bridge_name,
            apex_weight=0.20,
            reflected_weight=0.10,
            reflected_xy_sigma_m_s=0.25,
            reflected_z_sigma_m_s=0.35,
        ),
        target_mean_hits=1.40,
        target_hit1_rate=0.90,
        target_hit3_rate=None,
        min_recent_fixed_contact_quality_components=(
            0.15,
            0.30,
            0.30,
            0.30,
            0.30,
        ),
        min_recent_fixed_contact_return_apex_score=0.15,
        min_recent_fixed_contact_outcome_all_ready_fraction=0.02,
        min_recent_mean_hit_apex_abs_z_m=1.20,
        max_recent_mean_hit_apex_abs_z_m=1.49,
        min_updates=80,
        convergence_hold_updates=10,
        notes=(
            "V135 resumes the passed V133 recurrent bridge, not the degraded "
            "workspace-local actor. This bridge requires the feasible first "
            "recurrence in the one-second horizon and gives bounded direct "
            "credit to apex and reflected velocity before restoring every "
            "strict local outcome gate."
        ),
    )
    commit_name = "v135_s1_workspace_local_outcome_commit"
    commit = replace(
        source_local,
        name=commit_name,
        cfg=outcome_cfg(
            source_local,
            name=commit_name,
            apex_weight=0.40,
            reflected_weight=0.20,
            reflected_xy_sigma_m_s=0.20,
            reflected_z_sigma_m_s=0.30,
        ),
        target_mean_hits=max(1.60, float(source_local.target_mean_hits)),
        target_hit1_rate=max(0.90, float(source_local.target_hit1_rate or 0.0)),
        target_hit3_rate=None,
        min_recent_mean_hit_apex_abs_z_m=1.32,
        max_recent_mean_hit_apex_abs_z_m=1.46,
        min_updates=120,
        convergence_hold_updates=10,
        notes=(
            "V135 local commit restores V133's complete physical quality, "
            "return, outcome, arrival and hard-safety gates. It still grades "
            "one counted recurrence rather than an impossible third contact "
            "inside the one-second falling-contact horizon."
        ),
    )
    result.extend((bridge, commit))

    for source_stage in source[18:]:
        name = source_stage.name.replace("v133_", "v135_", 1)
        short_horizon = float(source_stage.cfg.horizon_sec) < 1.12
        two_contact_bridge = name == "v135_s2_two_contact_bridge"
        needs_two_hits = short_horizon or two_contact_bridge
        cfg = replace(
            source_stage.cfg,
            fixed_contact_training_phase=name,
            post_first_hit_alive_reward_weight=1.4,
            fixed_contact_smooth_stroke_vz_penalty_weight=min(
                0.75,
                float(
                    source_stage.cfg.fixed_contact_smooth_stroke_vz_penalty_weight
                ),
            ),
            fixed_contact_smooth_stroke_peak_m_s=min(
                0.60,
                float(source_stage.cfg.fixed_contact_smooth_stroke_peak_m_s),
            ),
            fixed_contact_apex_error_penalty_weight=max(
                0.40,
                float(source_stage.cfg.fixed_contact_apex_error_penalty_weight),
            ),
            fixed_contact_apex_error_penalty_scale_m=0.10,
            hit_adaptive_reflected_velocity_penalty_weight=max(
                0.20,
                float(
                    source_stage.cfg.hit_adaptive_reflected_velocity_penalty_weight
                ),
            ),
            hit_adaptive_reflected_velocity_xy_sigma_m_s=0.20,
            hit_adaptive_reflected_velocity_z_sigma_m_s=0.30,
            full_episode_completion_min_hits=(
                2
                if needs_two_hits
                else int(source_stage.cfg.full_episode_completion_min_hits)
            ),
        )
        result.append(
            replace(
                source_stage,
                name=name,
                cfg=cfg,
                target_hit3_rate=(
                    None if needs_two_hits else source_stage.target_hit3_rate
                ),
                notes=(
                    f"{source_stage.notes} V135 retains the original domain "
                    "and strict gates, carries the bounded apex/reflected-"
                    "velocity credit forward, and requests hit3 only where "
                    "the episode horizon can physically contain it."
                ),
            )
        )
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v136_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Acquire contact before annealing to V134's physical outcome target."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v132_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    source_local = source[0]

    def physical_cfg(
        stage: CurriculumStage,
        *,
        name: str,
        actual_weight: float,
        command_weight: float,
        vxy_weight: float,
        reflected_weight: float,
        anchor_weight: float,
        outcome_weight: float,
        outcome_bonus: float,
    ) -> MjxJuggleConfig:
        return replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_pre_hit_launch_vz_reward_weight=actual_weight,
            fixed_contact_pre_hit_launch_command_vz_reward_weight=(
                command_weight
            ),
            hit_vxy_soft_limit_m_s=0.45,
            hit_vxy_penalty_weight=vxy_weight,
            hit_vxy_penalty_scale_m_s=0.50,
            hit_vxy_penalty_loss="pseudo_huber",
            hit_vxy_apply_from_first_hit=(vxy_weight > 0.0),
            hit_vxy_zero_reward_weight=0.5 * vxy_weight,
            hit_vxy_zero_reward_sigma_m_s=0.35,
            early_hit_vxy_penalty_hit_count=(1 if vxy_weight > 0.0 else 0),
            early_hit_vxy_penalty_multiplier=1.0,
            early_hit_vxy_zero_reward_multiplier=1.0,
            hit_adaptive_reflected_velocity_penalty_weight=reflected_weight,
            hit_adaptive_reflected_velocity_xy_sigma_m_s=0.25,
            hit_adaptive_reflected_velocity_z_sigma_m_s=0.40,
            hit_next_contact_anchor_penalty_weight=anchor_weight,
            fixed_contact_outcome_constraint_penalty_weight=outcome_weight,
            fixed_contact_outcome_constraint_bonus_weight=outcome_bonus,
            fixed_contact_smooth_stroke_vz_penalty_weight=0.0,
            fixed_contact_recurrent_hit_deadline_s=0.0,
            full_episode_completion_min_hits=1,
        )

    acquire_name = "v136_s1_placed_local_contact_acquisition"
    acquire = replace(
        source_local,
        name=acquire_name,
        cfg=physical_cfg(
            source_local,
            name=acquire_name,
            actual_weight=20.0,
            command_weight=40.0,
            vxy_weight=0.0,
            reflected_weight=0.0,
            anchor_weight=0.0,
            outcome_weight=0.0,
            outcome_bonus=0.0,
        ),
        target_mean_hits=0.30,
        target_hit1_rate=0.30,
        target_hit3_rate=None,
        target_episode_truncation_rate=None,
        max_recent_mean_first_hit_ball_vxy=None,
        min_recent_fixed_contact_outcome_all_ready_fraction=None,
        min_recent_fixed_contact_s0_arrival_ready_fraction=None,
        fixed_contact_s0_gate_use_advance_eval=False,
        min_updates=160,
        convergence_hold_updates=10,
        notes=(
            "V136 first learns contact with V132's effective 2:1 command-to-"
            "actual launch guide. No post-contact quality loss or outcome gate "
            "can make the no-contact policy preferable in this lesson."
        ),
    )
    bridge_name = "v136_s1_placed_local_physical_bridge"
    bridge = replace(
        acquire,
        name=bridge_name,
        cfg=physical_cfg(
            source_local,
            name=bridge_name,
            actual_weight=30.0,
            command_weight=30.0,
            vxy_weight=0.15,
            reflected_weight=0.10,
            anchor_weight=0.02,
            outcome_weight=0.10,
            outcome_bonus=0.10,
        ),
        target_mean_hits=0.50,
        target_hit1_rate=0.50,
        min_updates=120,
        notes=(
            "V136 physical bridge keeps the learned command guide while "
            "introducing bounded pseudo-Huber outgoing-velocity and gentle "
            "anchor/outcome credit. Hard physical outcome gates remain off."
        ),
    )
    commit_name = "v136_s1_placed_local_physical_commit"
    commit = replace(
        bridge,
        name=commit_name,
        cfg=physical_cfg(
            source_local,
            name=commit_name,
            actual_weight=40.0,
            command_weight=20.0,
            vxy_weight=0.30,
            reflected_weight=0.20,
            anchor_weight=0.05,
            outcome_weight=0.25,
            outcome_bonus=0.20,
        ),
        target_mean_hits=0.65,
        target_hit1_rate=0.65,
        max_recent_mean_first_hit_ball_vxy=0.75,
        min_recent_fixed_contact_outcome_all_ready_fraction=0.02,
        min_updates=160,
        notes=(
            "V136 physical commit makes measured launch credit dominant only "
            "after contact acquisition, then grades the preregistered first-"
            "hit VXY and complete fixed-contact outcome together."
        ),
    )
    recurrent_name = "v136_s1_placed_local_recurrent_bridge"
    recurrent = replace(
        commit,
        name=recurrent_name,
        cfg=replace(
            commit.cfg,
            fixed_contact_training_phase=recurrent_name,
            racket_launch_hold_time_s=0.09,
            fixed_contact_smooth_stroke_vz_penalty_weight=0.5,
            fixed_contact_smooth_stroke_peak_m_s=0.60,
            fixed_contact_recurrent_hit_deadline_s=0.60,
            post_hit_overdue_penalty_weight=5.0,
            post_hit_overdue_penalty_dt_scaled=True,
            post_hit_overdue_soft_limit_s=0.50,
            post_hit_overdue_penalty_scale_s=0.08,
            full_episode_completion_min_hits=2,
        ),
        target_mean_hits=1.05,
        target_hit1_rate=0.65,
        target_hit3_rate=None,
        target_mean_len_frac=0.60,
        hit_interval_gate_source="counted_hit_event",
        target_min_hit_interval_s=0.40,
        target_max_hit_interval_s=0.52,
        target_episode_truncation_rate=0.05,
        min_recent_fixed_contact_s0_arrival_ready_fraction=0.15,
        fixed_contact_s0_gate_use_advance_eval=True,
        min_updates=160,
        notes=(
            "V136 adds the local recurrent deadline only after first-hit "
            "physical quality is learned. This 1.35-second bridge requires "
            "one adjacent counted interval and a two-hit completion reward."
        ),
    )

    tail: list[CurriculumStage] = []
    for source_stage in source[1:]:
        name = source_stage.name.replace("v132_", "v136_", 1)
        command_weight = float(
            source_stage.cfg.fixed_contact_pre_hit_launch_command_vz_reward_weight
        )
        vxy_weight = max(0.30, float(source_stage.cfg.hit_vxy_penalty_weight))
        cfg = replace(
            source_stage.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_pre_hit_launch_vz_reward_weight=command_weight,
            fixed_contact_pre_hit_launch_command_vz_reward_weight=command_weight,
            hit_vxy_penalty_weight=vxy_weight,
            hit_vxy_penalty_scale_m_s=max(
                0.35, float(source_stage.cfg.hit_vxy_penalty_scale_m_s)
            ),
            hit_vxy_penalty_loss="pseudo_huber",
            hit_vxy_apply_from_first_hit=True,
            hit_adaptive_reflected_velocity_penalty_weight=max(
                0.20,
                float(
                    source_stage.cfg.hit_adaptive_reflected_velocity_penalty_weight
                ),
            ),
            hit_adaptive_reflected_velocity_xy_sigma_m_s=0.25,
            hit_adaptive_reflected_velocity_z_sigma_m_s=0.40,
            hit_next_contact_anchor_penalty_weight=max(
                0.05,
                float(source_stage.cfg.hit_next_contact_anchor_penalty_weight),
            ),
            fixed_contact_outcome_constraint_penalty_weight=max(
                0.25,
                float(
                    source_stage.cfg.fixed_contact_outcome_constraint_penalty_weight
                ),
            ),
            fixed_contact_outcome_constraint_bonus_weight=max(
                0.20,
                float(
                    source_stage.cfg.fixed_contact_outcome_constraint_bonus_weight
                ),
            ),
            fixed_contact_smooth_stroke_peak_m_s=min(
                0.60,
                float(source_stage.cfg.fixed_contact_smooth_stroke_peak_m_s),
            ),
            fixed_contact_recurrent_hit_deadline_s=0.60,
            post_hit_overdue_penalty_weight=max(
                5.0, float(source_stage.cfg.post_hit_overdue_penalty_weight)
            ),
            post_hit_overdue_penalty_dt_scaled=True,
            post_hit_overdue_soft_limit_s=0.50,
            post_hit_overdue_penalty_scale_s=0.08,
        )
        tail.append(
            replace(
                source_stage,
                name=name,
                cfg=cfg,
                hit_interval_gate_source="counted_hit_event",
                target_min_hit_interval_s=0.40,
                target_max_hit_interval_s=0.52,
                notes=(
                    f"{source_stage.notes} V136 reaches this lesson only "
                    "after contact acquisition and physical-outcome commit; "
                    "bounded outcome credit remains active during widening."
                ),
            )
        )
    return [acquire, bridge, commit, recurrent, *tail]


