def _historical_fixed_contact_env_cfg(
    env_cfg: object,
) -> object:
    """Backfill only default-off fields absent from historical checkpoints."""

    if not isinstance(env_cfg, dict):
        return env_cfg
    compatible_cfg = dict(env_cfg)
    for name, default in _HISTORICAL_FIXED_CONTACT_ENV_CFG_DEFAULTS.items():
        compatible_cfg.setdefault(name, default)
    return compatible_cfg


def validate_fixed_contact_plane_v6_resume_payload(
    payload: dict[str, object],
    *,
    requested_start_stage: str | None,
    resume_curriculum_state: bool,
) -> None:
    """Pin V6 to the reproducible V4 update-200 speed frontier."""

    source_args = payload.get("args", {})

    def source_arg(name: str, default=None):
        if isinstance(source_args, dict):
            return source_args.get(name, default)
