def validate_fixed_contact_plane_v40_resume_payload(
    payload: dict[str, object],
    *,
    requested_start_stage: str | None,
    resume_curriculum_state: bool,
) -> None:
    """Pin V40 to the last safely persisted V38 center-acquisition state."""

    source_args = payload.get("args", {})

    def source_arg(name: str, default=None):
        if isinstance(source_args, dict):
            return source_args.get(name, default)
        return getattr(source_args, name, default)

    source_profile = source_arg("curriculum_profile")
    if source_profile == FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V40_PROFILE:
        expected_recovery = {
            "step": 231_473_152,
            "global_update": 100,
            "stage_index": 5,
            "stage_name": "v40_s0_center_hold_at_target",
            "stage_update": 100,
            "obs_dim": 80,
            "critic_obs_dim": 401,
            "act_dim": 7,
        }
        recovery_mismatches = [
            f"{name}={payload.get(name)!r}"
            for name, expected_value in expected_recovery.items()
            if payload.get(name) != expected_value
        ]
        if requested_start_stage != "v40_s0_center_hold_at_target":
            recovery_mismatches.append(
                f"requested_start_stage={requested_start_stage!r}"
            )
        if not resume_curriculum_state:
            recovery_mismatches.append("resume_curriculum_state=False")
        expected_numeric_args = {
            "seed": 20260980,
            "n_envs": 256,
            "n_steps": 128,
            "minibatch_size": 16384,
            "update_epochs": 4,
            "learning_rate": 1.0e-4,
            "gamma": 0.9995,
            "gae_lambda": 0.99,
            "clip_range": 0.10,
            "target_kl": 0.006,
            "ent_coef": 0.0001,
            "min_log_std": -4.8,
            "max_log_std": -2.8,
            "convergence_window": 24,
            "stage_metric_warmup_updates": 10,
            "advance_eval_n_envs": 128,
        }
        for name, expected_value in expected_numeric_args.items():
            actual = source_arg(name)
            if actual is None or not np.isclose(
                float(actual), float(expected_value), rtol=0.0, atol=1.0e-12
            ):
                recovery_mismatches.append(f"source {name}={actual!r}")
        params = payload.get("params")
        if not isinstance(params, dict):
            recovery_mismatches.append("params missing")
        else:
            missing_params = {"pi", "v", "log_std"} - set(params)
            if missing_params:
                recovery_mismatches.append(
                    "parameter trees missing "
                    + ",".join(sorted(missing_params))
                )
        opt = payload.get("opt")
        if opt is None:
            recovery_mismatches.append("Adam moments missing")
        elif int(np.asarray(getattr(opt, "t", -1))) != 55_393:
            recovery_mismatches.append(
                f"Adam t={getattr(opt, 't', None)!r}"
            )
        if payload.get("stage_actor_anchor_reference_params") is None:
            recovery_mismatches.append("stage-local actor anchor missing")
        if recovery_mismatches:
            raise SystemExit(
                "[mjx_curriculum] V40 memory recovery is not the exact "
                "update-100 checkpoint: " + ", ".join(recovery_mismatches)
            )
        return

    expected = {
        "step": 228_196_352,
        "global_update": 1741,
        "stage_index": 4,
        "stage_name": "v38_s0_center_acquire",
        "stage_update": 1600,
        "obs_dim": 80,
        "critic_obs_dim": 401,
        "act_dim": 7,
    }
    mismatches: list[str] = []
    if requested_start_stage != "v40_s0_center_hold_at_target":
        mismatches.append(f"requested_start_stage={requested_start_stage!r}")
    if resume_curriculum_state:
        mismatches.append("resume_curriculum_state=True")
    if source_profile != (
        FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V38_PROFILE
    ):
        mismatches.append(
            f"source profile={source_profile!r}"
        )
    for key, value in expected.items():
        if payload.get(key) != value:
            mismatches.append(f"{key}={payload.get(key)!r}")
    if mismatches:
        raise SystemExit(
            "[mjx_curriculum] V40 requires the pinned protected V38 "
            "global-update-1741 checkpoint and a fresh repair window: "
            + ", ".join(mismatches)
        )


