def validate_fixed_contact_plane_v64_resume_payload(
    payload: dict[str, object],
    *,
    requested_start_stage: str | None,
    resume_curriculum_state: bool,
    stage_names: list[str],
) -> None:
    """Require a complete immediately preceding V63/V64 stage checkpoint."""

    if resume_curriculum_state:
        raise SystemExit("V64 starts a fresh convergence window after each stage")
    if payload.get("opt") is None:
        raise SystemExit("V64 requires restored Adam moments")
    expected_dims = {"obs_dim": 80, "critic_obs_dim": 401, "act_dim": 7}
    for field, expected in expected_dims.items():
        if payload.get(field) != expected:
            raise SystemExit(
                f"V64 source {field} mismatch: expected {expected!r}, "
                f"got {payload.get(field)!r}"
            )
    source_index = int(payload.get("stage_index", 0))
    if source_index < 1 or source_index >= len(stage_names):
        raise SystemExit(
            "V64 source must be a passed nonfinal stage checkpoint"
        )
    expected_start = stage_names[source_index]
    if requested_start_stage != expected_start:
        raise SystemExit(
            f"V64 must resume the stage immediately after its source: "
            f"expected {expected_start!r}, got {requested_start_stage!r}"
        )
    source_profile = (payload.get("args") or {}).get("curriculum_profile")
    source_name = str(payload.get("stage_name", ""))
    expected_v64_source = stage_names[source_index - 1]
    if source_profile == FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V63_PROFILE:
        if source_index != 1:
            raise SystemExit("V64 accepts V63 only at its passed Stage-1 boundary")
        expected_source = expected_v64_source.replace("v64_", "v63_", 1)
    elif source_profile == FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V64_PROFILE:
        expected_source = expected_v64_source
    else:
        raise SystemExit("V64 requires a V63 Stage-1 or preceding V64 checkpoint")
    if source_name != expected_source:
        raise SystemExit(
            f"V64 source stage mismatch: expected {expected_source!r}, "
            f"got {source_name!r}"
        )


def _validate_fixed_contact_complete_state(
    payload: dict[str, object],
    *,
    version: str,
    resume_curriculum_state: bool,
    allow_curriculum_state: bool = False,
) -> None:
    if resume_curriculum_state and not allow_curriculum_state:
        raise SystemExit(f"{version} starts fresh per-stage convergence history")
    if payload.get("opt") is None:
        raise SystemExit(f"{version} requires restored Adam moments")
    for field, expected in {
        "obs_dim": 80,
        "critic_obs_dim": 401,
        "act_dim": 7,
    }.items():
        if payload.get(field) != expected:
            raise SystemExit(
                f"{version} source {field} mismatch: expected {expected!r}, "
                f"got {payload.get(field)!r}"
            )


def validate_fixed_contact_predictive_stage_reexec_payload(
    payload: dict[str, object],
    *,
    profile: str,
    version: str,
    requested_start_stage: str | None,
    resume_curriculum_state: bool,
    stage_names: list[str] | None,
    trainer_stage_reexec: bool,
) -> None:
    """Authenticate an internal same-profile predictive-course reexec."""

    _validate_fixed_contact_complete_state(
        payload,
        version=version,
        resume_curriculum_state=resume_curriculum_state,
        allow_curriculum_state=True,
    )
    if not trainer_stage_reexec:
        raise SystemExit(
            f"{version} same-profile checkpoint requires trainer-stage reexec"
        )
    source_args = payload.get("args") or {}
    source_profile = (
        source_args.get("curriculum_profile")
        if isinstance(source_args, dict)
        else getattr(source_args, "curriculum_profile", None)
    )
    if source_profile != profile:
        raise SystemExit(
            f"{version} trainer-stage reexec source profile mismatch: "
            f"expected {profile!r}, got {source_profile!r}"
        )
    if not stage_names:
        raise SystemExit(
            f"{version} trainer-stage reexec requires the stage registry"
        )
    source_index = int(payload.get("stage_index", 0))
    if source_index < 1 or source_index > len(stage_names):
        raise SystemExit(
            f"{version} trainer-stage reexec source stage_index is invalid"
        )
    source_stage_name = stage_names[source_index - 1]
    if payload.get("stage_name") != source_stage_name:
        raise SystemExit(
            f"{version} trainer-stage reexec source stage identity mismatch"
        )
    if resume_curriculum_state:
        if requested_start_stage != source_stage_name:
            raise SystemExit(
                f"{version} same-stage reexec must preserve stage_name"
            )
        if not isinstance(payload.get("stage_history_tail"), list):
            raise SystemExit(
                f"{version} same-stage reexec requires bounded history"
            )
        return
    if source_index >= len(stage_names):
        raise SystemExit(
            f"{version} next-stage reexec requires a passed nonfinal stage"
        )
    last_row = payload.get("last_row") or {}
    if not isinstance(last_row, dict) or float(
        last_row.get("convergence/stage_converged", 0.0)
    ) < 0.5:
        raise SystemExit(
            f"{version} next-stage reexec requires a passed source"
        )
    if requested_start_stage != stage_names[source_index]:
        raise SystemExit(
            f"{version} must resume immediately after its passed source"
        )


