def validate_fixed_contact_v147_from_scratch(
    *,
    resume_from: str | Path | None,
    resume_start_stage: str | None,
    reset_optimizer_on_resume: bool,
    reset_critic_on_resume: bool,
    trainer_stage_reexec: bool = False,
    profile_label: str = "V147",
) -> None:
    """Fail closed if the clean-airborne GPU1 course receives legacy state."""

    if trainer_stage_reexec:
        if (
            resume_from is None
            or resume_start_stage in (None, "auto")
            or reset_optimizer_on_resume
            or reset_critic_on_resume
        ):
            raise SystemExit(
                f"{profile_label} trainer-stage reexec requires a checkpoint, "
                "an explicit stage, and restored critic/optimizer state"
            )
        return
    # argparse supplies ``auto`` even without a resume request.  Any explicit
    # stage identity is nevertheless stateful resume intent and must fail.
    invalid_start = resume_start_stage not in (None, "auto")
    if (
        resume_from is not None
        or invalid_start
        or reset_optimizer_on_resume
        or reset_critic_on_resume
    ):
        raise SystemExit(
            f"{profile_label} is from-scratch only and rejects every "
            "resume/reset option"
        )


def _validate_predictive_repair_source(
    payload: dict[str, object],
    *,
    version: str,
    source_profile: str,
    expected: dict[str, object],
    requested_start_stage: str | None,
    expected_start_stage: str,
    resume_curriculum_state: bool,
) -> None:
    """Validate a complete immutable parent for a fresh repair course."""

    _validate_fixed_contact_complete_state(
        payload,
        version=version,
        resume_curriculum_state=resume_curriculum_state,
        allow_curriculum_state=False,
    )
    source_args = payload.get("args") or {}
    actual_profile = (
        source_args.get("curriculum_profile")
        if isinstance(source_args, dict)
        else getattr(source_args, "curriculum_profile", None)
    )
    mismatches = [
        f"{field}={payload.get(field)!r}"
        for field, value in expected.items()
        if payload.get(field) != value
    ]
    if actual_profile != source_profile:
        mismatches.append(f"source curriculum_profile={actual_profile!r}")
    if requested_start_stage != expected_start_stage:
        mismatches.append(f"requested_start_stage={requested_start_stage!r}")
    if resume_curriculum_state:
        mismatches.append("resume_curriculum_state=True")
    if mismatches:
        raise SystemExit(f"{version} pinned source mismatch: " + ", ".join(mismatches))


