def validate_fixed_contact_v176_resume_payload(
    payload: dict[str, object],
    *,
    requested_start_stage: str | None,
    resume_curriculum_state: bool,
    stage_names: list[str] | None = None,
    trainer_stage_reexec: bool = False,
) -> None:
    """Pin V176 to V175-u260, then require complete CMDP stage reexecs."""

    source_args = payload.get("args") or {}

    def source_arg(name: str, default=None):
        if isinstance(source_args, dict):
            return source_args.get(name, default)
        return getattr(source_args, name, default)

    source_profile = source_arg("curriculum_profile")
    if source_profile == FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V176_PROFILE:
        validate_fixed_contact_predictive_stage_reexec_payload(
            payload,
            profile=FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V176_PROFILE,
            version="V176",
            requested_start_stage=requested_start_stage,
            resume_curriculum_state=resume_curriculum_state,
            stage_names=stage_names,
            trainer_stage_reexec=trainer_stage_reexec,
        )
        params = payload.get("params")
        mismatches: list[str] = []
        if not isinstance(params, dict):
            mismatches.append("params missing")
        else:
            cost_value = params.get("cmdp_cost_v")
            dual = params.get("cmdp_dual")
            if not isinstance(cost_value, dict):
                mismatches.append("cmdp_cost_v missing")
            else:
                try:
                    output_dim = int(cost_value["out"]["b"].shape[0])
                except (KeyError, TypeError, AttributeError, IndexError):
                    output_dim = -1
                if output_dim != len(CONTACT_QUALITY_CMDP_COST_NAMES):
                    mismatches.append(f"cmdp_cost_v output_dim={output_dim}")
            if dual is None or np.asarray(dual).shape != (
                len(CONTACT_QUALITY_CMDP_COST_NAMES),
            ):
                mismatches.append(
                    f"cmdp_dual shape={None if dual is None else np.asarray(dual).shape!r}"
                )
        expected_source_values = {
            "cmdp_enabled": True,
            "cmdp_cost_mode": "fixed_contact_quality",
            "cmdp_cost_gae_lambda": 0.97,
            "cmdp_cost_vf_coef": 0.5,
            "cmdp_dual_learning_rate": 0.05,
            "cmdp_dual_max": 4.0,
            "cmdp_approach_vxy_terminal_limit_m_s": 0.05,
            "cmdp_approach_vxy_brake_accel_m_s2": 1.0,
            "cmdp_approach_vxy_delay_s": 0.025,
            "cmdp_approach_vxy_window_s": 0.12,
            "cmdp_approach_vxy_excess_scale_m_s": 0.05,
        }
        for name, expected in expected_source_values.items():
            actual = source_arg(name)
            if isinstance(expected, bool):
                if bool(actual) is not expected:
                    mismatches.append(f"source {name}={actual!r}")
            elif isinstance(expected, str):
                if actual != expected:
                    mismatches.append(f"source {name}={actual!r}")
            elif actual is None or not np.isclose(
                float(actual), float(expected), rtol=0.0, atol=1.0e-12
            ):
                mismatches.append(f"source {name}={actual!r}")
        if mismatches:
            raise SystemExit(
                "V176 stage reexec lacks the complete actual-contact CMDP "
                "state: " + ", ".join(mismatches)
            )
        return

    _validate_predictive_repair_source(
        payload,
        version="V176",
        source_profile=FIXED_CONTACT_PLANE_VISION_ROBUST_QVEL_RMP_V175_PROFILE,
        expected={
            "step": 34_078_720,
            "global_update": 260,
            "stage_index": 1,
            "stage_name": "v175_g1_plane_impact_center",
            "stage_update": 260,
        },
        requested_start_stage=requested_start_stage,
        expected_start_stage="v176_g1_actual_contact_cmdp_repair",
        resume_curriculum_state=resume_curriculum_state,
    )
    params = payload.get("params")
    if isinstance(params, dict) and (
        "cmdp_cost_v" in params or "cmdp_dual" in params
    ):
        raise SystemExit("V176 pinned V175 source must not contain CMDP state")
    expected_v175_values = {
        "n_envs": 1024,
        "n_steps": 128,
        "minibatch_size": 16384,
        "update_epochs": 4,
        "learning_rate": 5.0e-5,
        "gamma": 0.9995,
        "gae_lambda": 0.995,
        "clip_range": 0.10,
        "target_kl": 0.004,
        "ent_coef": 1.0e-4,
        "min_log_std": -4.8,
        "max_log_std": -2.8,
    }
    mismatches = [
        f"source {name}={source_arg(name)!r}"
        for name, expected in expected_v175_values.items()
        if source_arg(name) is None
        or not np.isclose(
            float(source_arg(name)), float(expected), rtol=0.0, atol=1.0e-12
        )
    ]
    if bool(source_arg("cmdp_enabled", False)):
        mismatches.append("source cmdp_enabled=True")
    if mismatches:
        raise SystemExit(
            "V176 pinned V175 optimizer contract mismatch: "
            + ", ".join(mismatches)
        )


