def validate_fixed_contact_v177_cli_history_mode(
    *,
    allow_obs_dim_migration: bool,
    resume_curriculum_state: bool,
    trainer_stage_reexec: bool,
) -> None:
    """Separate initial V177 continuation from same-stage memory reexec.

    The initial V163-to-V177 continuation deliberately starts fresh
    convergence history because the event semantics change.  Once V177 is
    running, its periodic same-stage process reexec must restore that bounded
    history together with actor, critic and optimizer state; otherwise the
    memory-release mechanism cannot restart the trainer at update 500.
    """

    if bool(allow_obs_dim_migration):
        raise ValueError(
            "V177 prohibits observation-dimension migration on every resume"
        )
    if bool(resume_curriculum_state) and not bool(trainer_stage_reexec):
        raise ValueError(
            "V177 initial continuation must start fresh atomic-hit stage "
            "history"
        )


