def _validate_fixed_contact_actor_only_plateau_source(
    payload: dict[str, object],
    *,
    version: str,
    source_profile: str,
    expected: dict[str, object],
    requested_start_stage: str | None,
    expected_start_stage: str,
    resume_curriculum_state: bool,
) -> None:
    """Validate a pinned full checkpoint used for actor-only MDP repair."""

    if resume_curriculum_state:
        raise SystemExit(f"{version} starts a fresh convergence window")
    source_args = payload.get("args") or {}
    actual_profile = (
        source_args.get("curriculum_profile")
        if isinstance(source_args, dict)
        else getattr(source_args, "curriculum_profile", None)
    )
    if actual_profile != source_profile:
        raise SystemExit(
            f"{version} source profile mismatch: expected {source_profile!r}, "
            f"got {actual_profile!r}"
        )
    for field, value in {
        "obs_dim": 80,
        "critic_obs_dim": 401,
        "act_dim": 7,
        **expected,
    }.items():
        if payload.get(field) != value:
            raise SystemExit(
                f"{version} source {field} mismatch: expected {value!r}, "
                f"got {payload.get(field)!r}"
            )
    if requested_start_stage != expected_start_stage:
        raise SystemExit(
            f"{version} requires requested_start_stage={expected_start_stage!r}"
        )


