def _fixed_contact_plane_vision_robust_qvel_rmp_v145_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair V143's path-dependent reset IK and undersampled XY gate."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v143_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("v143_", "v145_", 1)
        use_seed_permuted_xy = bool(
            stage.cfg.fixed_contact_xy_bin_sampling_enabled
            and not stage.cfg.fixed_contact_factorized_reset_evaluation
        )
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    falling_reset_racket_follow_xy_canonical_ik=True,
                    fixed_contact_xy_equal_bin_seed_permutation=(
                        use_seed_permuted_xy
                    ),
                ),
                notes=(
                    f"{stage.notes} V145 changes no lesson, domain, reward, "
                    "control or gate threshold. Its reset IK solves every "
                    "Cartesian target from the same canonical warm posture, "
                    "so a target no longer changes joint-space branch when "
                    "the global workspace range changes. Its frozen "
                    "evaluator rotates "
                    "the equal-count XY assignment across environment lanes "
                    "per seed, then pools repeated outcomes for each same "
                    "coordinate before selecting the worst bin. This removes "
                    "the historical coordinate/lane confound and keeps the "
                    "declared 0.35 rate probabilistic."
                ),
            )
        )
    if len(result) != len(source):
        raise ValueError("V145 must preserve the complete V143 course length")
    return result


def _predictive_contact_cfg(
    source: MjxJuggleConfig,
    **updates: object,
) -> MjxPredictiveContactCurriculumConfig:
    """Promote one historical config without mutating its dataclass schema."""

    defaults = MjxPredictiveContactCurriculumConfig()
    values = {
        field.name: getattr(source, field.name, getattr(defaults, field.name))
        for field in fields(MjxPredictiveContactCurriculumConfig)
    }
    unknown = set(updates).difference(values)
    if unknown:
        raise ValueError(f"unknown predictive-contact config fields: {unknown}")
    values.update(updates)
    return MjxPredictiveContactCurriculumConfig(**values)


def _predictive_workspace_ranges(
    label: str,
) -> tuple[tuple[float, float], tuple[float, float]]:
    ranges = {
        "center": ((0.0, 0.0), (0.0, 0.0)),
        "local": ((-0.05, 0.05), (-0.04, 0.04)),
        "inner": ((-0.10, 0.10), (-0.06, 0.06)),
        "mid": ((-0.20, 0.10), (-0.12, 0.12)),
        "full": ((-0.30, 0.20), (-0.12, 0.18)),
    }
    return ranges[label]


def _predictive_workspace_grids(
    label: str,
) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """Return exact frozen lanes for each nested predictive workspace.

    The historical 0.10/0.06 m grid contains only the center inside the new
    local support.  Explicit edge-inclusive grids are therefore part of the
    V146/V147 contract rather than an incidental inheritance from V145/V144.
    """

    grids = {
        "center": ((0.0,), (0.0,)),
        "local": ((-0.05, 0.0, 0.05), (-0.04, 0.0, 0.04)),
        "inner": ((-0.10, 0.0, 0.10), (-0.06, 0.0, 0.06)),
        "mid": (
            (-0.20, -0.10, 0.0, 0.10),
            (-0.12, -0.06, 0.0, 0.06, 0.12),
        ),
        "full": (
            (-0.30, -0.20, -0.10, 0.0, 0.10, 0.20),
            (-0.12, -0.06, 0.0, 0.06, 0.12, 0.18),
        ),
    }
    return grids[label]


def _fixed_contact_plane_vision_robust_qvel_rmp_v146_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU0: prove arrival, condition strike, then build recurrent survival."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v145_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    arrival_template = source[13]
    hit_template = source[15]
    recurrent_template = source[21]
    specs = (
        # name, template, workspace, horizon, mode, P1/P2/P3/P5/P6/P12, full
        ("v146_g0_arrival_center_reproof", arrival_template, "center", 0.60,
         "arrival_only", None, None, None, None, None, None, None, 0.85),
        ("v146_g0_arrival_local", arrival_template, "local", 0.60,
         "arrival_only", None, None, None, None, None, None, None, 0.80),
        ("v146_g0_arrival_inner", arrival_template, "inner", 0.60,
         "arrival_only", None, None, None, None, None, None, None, 0.78),
        ("v146_g0_arrival_mid", arrival_template, "mid", 0.60,
         "arrival_only", None, None, None, None, None, None, None, 0.75),
        ("v146_g0_arrival_full", arrival_template, "full", 0.60,
         "arrival_only", None, None, None, None, None, None, None, 0.72),
        ("v146_g0_arrived_hit_bridge", hit_template, "local", 1.00,
         "arrival_conditioned_single_hit", 0.80, None, None, None, None,
         None, None, None),
        ("v146_g0_arrived_hit_commit", hit_template, "local", 1.00,
         "arrival_conditioned_single_hit", 0.90, None, None, None, None,
         None, None, None),
        ("v146_g0_joint_local_bridge", recurrent_template, "local", 1.50,
         "mixture", 0.90, 0.40, None, None, None, None, None, None),
        ("v146_g0_joint_local_commit", recurrent_template, "local", 1.50,
         "mixture", None, 0.70, 0.20, None, None, None, None, None),
        ("v146_g0_joint_inner", recurrent_template, "inner", 1.50,
         "mixture", None, 0.65, 0.20, None, None, None, None, None),
        ("v146_g0_joint_mid", recurrent_template, "mid", 1.50,
         "mixture", None, 0.60, 0.20, None, None, None, None, None),
        ("v146_g0_joint_full", recurrent_template, "full", 1.50,
         "mixture", None, 0.55, 0.15, None, None, None, None, None),
        ("v146_g0_horizon_3s", recurrent_template, "full", 3.00,
         "mixture", None, None, 0.75, 0.45, None, None, 0.65, None),
        ("v146_g0_horizon_6s_bridge", recurrent_template, "full", 6.00,
         "mixture", None, None, None, None, 0.70, 0.50, 0.70, None),
        ("v146_g0_horizon_6s_proof", recurrent_template, "full", 6.00,
         "mixture", None, None, None, None, None, 0.80, 0.80, None),
    )
    result: list[CurriculumStage] = []
    for index, spec in enumerate(specs):
        (
            name,
            template,
            workspace,
            horizon,
            mode,
            hit1,
            hit2,
            hit3,
            hit5,
            hit6,
            hit12,
            full,
            arrival_ready,
        ) = spec
        x_range, y_range = _predictive_workspace_ranges(str(workspace))
        x_grid, y_grid = _predictive_workspace_grids(str(workspace))
        if mode == "arrival_only":
            mixture = (1.0, 0.0, 0.0)
        elif mode == "arrival_conditioned_single_hit":
            mixture = (0.0, 1.0, 0.0)
        elif index < 12:
            mixture = (0.20, 0.20, 0.60)
        elif index < 14:
            mixture = (0.10, 0.10, 0.80)
        else:
            mixture = (0.05, 0.05, 0.90)
        cfg = _predictive_contact_cfg(
            template.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_skill_mode=str(mode),
            fixed_contact_ttc_phase_schedule_enabled=True,
            fixed_contact_disable_ball_racket_collision=(
                mode == "arrival_only"
            ),
            fixed_contact_reset_mixture_arrival_only=mixture[0],
            fixed_contact_reset_mixture_arrived_hit=mixture[1],
            fixed_contact_reset_mixture_recurrent=mixture[2],
            fixed_contact_actual_event_alignment_enabled=True,
            fixed_contact_contact_duration_metrics_enabled=True,
            ball_reset_mode="falling_contact",
            falling_reset_time_to_contact_range_s=(
                (0.080, 0.100)
                if mode == "arrival_conditioned_single_hit"
                else (0.16, 0.32)
            ),
            falling_reset_racket_follow_episode_target_xy=True,
            falling_reset_racket_follow_xy_canonical_ik=True,
            fixed_contact_reset_observation_uses_ball_init_velocity=True,
            episode_target_x_range_m=x_range,
            episode_target_y_range_m=y_range,
            fixed_contact_eval_grid_x_m=x_grid,
            fixed_contact_eval_grid_y_m=y_grid,
            horizon_sec=float(horizon),
        )
        result.append(
            replace(
                template,
                name=str(name),
                cfg=cfg,
                target_mean_hits=(0.0 if mode == "arrival_only" else 0.75),
                target_mean_len_frac=(0.0 if mode == "arrival_only" else 0.10),
                target_hit1_rate=hit1,
                target_hit2_rate=hit2,
                target_hit3_rate=hit3,
                target_hit5_rate=hit5,
                target_hit6_rate=hit6,
                target_hit12_rate=hit12,
                target_episode_truncation_rate=full,
                max_recent_mean_hit_vxy=(
                    min(float(template.max_recent_mean_hit_vxy), 0.16)
                    if index >= 6
                    and template.max_recent_mean_hit_vxy is not None
                    else template.max_recent_mean_hit_vxy
                ),
                max_recent_rms_hit_vxy=(
                    min(float(template.max_recent_rms_hit_vxy), 0.23)
                    if index >= 6
                    and template.max_recent_rms_hit_vxy is not None
                    else template.max_recent_rms_hit_vxy
                ),
                max_recent_mean_hit_racket_vxy=(
                    min(
                        float(template.max_recent_mean_hit_racket_vxy),
                        0.065,
                    )
                    if index >= 6
                    and template.max_recent_mean_hit_racket_vxy is not None
                    else template.max_recent_mean_hit_racket_vxy
                ),
                max_recent_rms_hit_racket_vxy=(
                    0.12 if index == 5 else 0.105 if index >= 6 else None
                ),
                max_recent_hit_next_contact_anchor_err=(
                    0.050 if index >= 6 else None
                ),
                max_recent_fixed_contact_return_horizontal_step_m=(
                    min(
                        float(
                            template.max_recent_fixed_contact_return_horizontal_step_m
                        ),
                        0.050,
                    )
                    if index >= 6
                    and template.max_recent_fixed_contact_return_horizontal_step_m
                    is not None
                    else template.max_recent_fixed_contact_return_horizontal_step_m
                ),
                min_recent_fixed_contact_s0_ready_fraction=(
                    arrival_ready if index < 5 else None
                ),
                min_recent_fixed_contact_s0_arrival_ready_fraction=(
                    arrival_ready
                ),
                min_recent_fixed_contact_ready_100ms_fraction=arrival_ready,
                min_recent_fixed_contact_ready_hold_fraction=(
                    (0.75, 0.70, 0.65, 0.60, 0.55)[index]
                    if index < 5
                    else None
                ),
                min_advance_fixed_contact_s0_worst_bin_ready_fraction=(
                    (0.85, 0.70, 0.65, 0.60, 0.55)[index]
                    if index < 5
                    else None
                ),
                min_advance_fixed_contact_s0_worst_bin_arrival_ready_fraction=(
                    (0.85, 0.70, 0.65, 0.60, 0.55)[index]
                    if index < 5
                    else None
                ),
                fixed_contact_xy_bin_success_hit_count=(
                    1
                    if index in {9, 11}
                    else template.fixed_contact_xy_bin_success_hit_count
                ),
                min_advance_fixed_contact_xy_bin_success_rate=(
                    0.70
                    if index == 9
                    else 0.55
                    if index == 11
                    else (
                        template.min_advance_fixed_contact_xy_bin_success_rate
                    )
                ),
                max_recent_contact_occupancy=(
                    0.03 if index >= 5 else None
                ),
                max_recent_p95_contact_duration_s=(
                    0.020 if index >= 5 else None
                ),
                min_recent_contact_edge_to_hit_conversion=(
                    0.90 if index >= 5 else None
                ),
                fixed_contact_condition_recurrent_episode_gates=(
                    mode == "mixture"
                ),
                fixed_contact_s0_gate_use_advance_eval=bool(arrival_ready),
                advance_validation_probe_mode="self",
                min_updates=max(80, int(template.min_updates)),
                max_updates=None,
                convergence_hold_updates=max(
                    12, int(template.convergence_hold_updates)
                ),
                notes=(
                    "V146 predictive-contact decomposition: retain V145's "
                    "80-D measured-QVEL/RMP/PD/physics contract, train this "
                    f"single {mode} lesson, and graduate on an independent "
                    "same-domain block. No atomic PPO transaction guard."
                ),
            )
        )
    if len(result) != 15:
        raise ValueError("V146 must contain exactly 15 registered lessons")
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v147_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU1: learn clean airborne contact directly, without placed-ball PPO."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v144_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    template = source[2]
    specs = (
        ("v147_g1_airborne_center_acquire", "center", 1.00, 5.0, 0.60,
         None, None, None, None, None, None),
        ("v147_g1_airborne_local_clean_hit", "local", 1.00, 5.0, 0.80,
         None, None, None, None, None, None),
        ("v147_g1_pose_box_3deg_commit", "local", 1.00, 3.0, 0.85,
         None, None, None, None, None, None),
        ("v147_g1_local_recurrent_bridge", "local", 1.50, 3.0, None,
         0.35, None, None, None, None, None),
        ("v147_g1_local_recurrent_commit", "local", 1.50, 3.0, None,
         0.65, 0.15, None, None, None, None),
        ("v147_g1_inner_recurrent", "inner", 1.50, 3.0, None,
         0.60, None, None, None, None, None),
        ("v147_g1_mid_recurrent", "mid", 1.50, 3.0, None,
         0.55, None, None, None, None, None),
        ("v147_g1_full_recurrent", "full", 1.50, 3.0, None,
         0.50, None, None, None, None, None),
        ("v147_g1_prediction_arrival_bridge", "full", 1.50, 3.0, None,
         0.50, None, None, None, None, None),
        ("v147_g1_prediction_arrival_commit", "full", 1.50, 3.0, None,
         0.50, None, None, None, None, None),
        ("v147_g1_horizon_3s", "full", 3.00, 3.0, None,
         None, 0.70, 0.40, None, None, 0.60),
        ("v147_g1_horizon_6s_bridge", "full", 6.00, 3.0, None,
         None, None, None, 0.65, 0.45, 0.65),
        ("v147_g1_horizon_6s_proof", "full", 6.00, 3.0, None,
         None, None, None, None, 0.75, 0.75),
    )
    result: list[CurriculumStage] = []
    for index, (
        name,
        workspace,
        horizon,
        pose_limit_deg,
        hit1,
        hit2,
        hit3,
        hit5,
        hit6,
        hit12,
        full,
    ) in enumerate(specs):
        x_range, y_range = _predictive_workspace_ranges(workspace)
        x_grid, y_grid = _predictive_workspace_grids(workspace)
        arrival_shaping = index >= 8
        cfg = _predictive_contact_cfg(
            template.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_skill_mode="scripted_airborne_handoff",
            fixed_contact_ttc_phase_schedule_enabled=arrival_shaping,
            fixed_contact_s0_arrival_worst_constraint_penalty_weight=(
                0.0 if index < 8 else 5.0 if index == 8 else 10.0
            ),
            fixed_contact_actual_event_alignment_enabled=True,
            fixed_contact_contact_duration_metrics_enabled=True,
            ball_reset_mode="scripted_airborne_handoff",
            scripted_airborne_handoff_enabled=True,
            scripted_airborne_handoff_ttc_range_s=(0.16, 0.21),
            scripted_airborne_handoff_surface_gap_m=0.001,
            scripted_airborne_handoff_target_apex_abs_m=1.33,
            falling_reset_time_to_contact_range_s=(0.16, 0.21),
            falling_reset_vxy_max=0.0,
            falling_reset_racket_follow_episode_target_xy=True,
            falling_reset_racket_follow_xy_canonical_ik=True,
            racket_launch_racket_follow_episode_target_xy=False,
            racket_launch_racket_follow_fixed_contact_surface_z=False,
            fixed_contact_reset_observation_uses_ball_init_velocity=True,
            episode_target_x_range_m=x_range,
            episode_target_y_range_m=y_range,
            fixed_contact_eval_grid_x_m=x_grid,
            fixed_contact_eval_grid_y_m=y_grid,
            cartesian_pose_roll_limit_deg=float(pose_limit_deg),
            cartesian_pose_pitch_limit_deg=float(pose_limit_deg),
            horizon_sec=float(horizon),
        )
        result.append(
            replace(
                template,
                name=name,
                cfg=cfg,
                target_mean_hits=0.75,
                target_mean_len_frac=0.10,
                target_hit1_rate=hit1,
                target_hit2_rate=hit2,
                target_hit3_rate=hit3,
                target_hit5_rate=hit5,
                target_hit6_rate=hit6,
                target_hit12_rate=hit12,
                target_episode_truncation_rate=full,
                target_min_hit_interval_s=(0.40 if index >= 3 else None),
                target_max_hit_interval_s=(0.52 if index >= 3 else None),
                hit_interval_gate_source="counted_hit_event",
                max_recent_mean_hit_vxy=(
                    None if index == 0 else 0.25 if index == 1 else 0.20
                ),
                max_recent_rms_hit_vxy=(
                    None if index == 0 else 0.30 if index == 1 else 0.25
                ),
                max_recent_mean_first_hit_ball_vxy=(
                    None if index == 0 else 0.25 if index == 1 else 0.20
                ),
                max_recent_rms_first_hit_ball_vxy=(
                    None if index == 0 else 0.30 if index == 1 else 0.25
                ),
                require_aggregate_hit_vxy_with_first_hit=(index >= 1),
                max_recent_mean_hit_racket_vxy=(
                    None if index == 0 else 0.08 if index == 1 else 0.065
                ),
                max_recent_rms_hit_racket_vxy=(
                    None if index == 0 else 0.12 if index == 1 else 0.105
                ),
                max_recent_hit_racket_angular_speed_rad_s=(
                    None if index == 0 else 0.80
                ),
                min_recent_fixed_contact_quality_components=(
                    None if index == 0 else (0.35,) * 5
                ),
                min_recent_fixed_contact_return_trajectory_score=(
                    None if index == 0 else 0.30
                ),
                min_recent_fixed_contact_return_apex_score=(
                    None if index == 0 else 0.24
                ),
                max_recent_fixed_contact_return_horizontal_step_m=(
                    0.050 if index >= 3 else None
                ),
                min_recent_fixed_contact_return_center_progress_m=(
                    -0.002 if index >= 3 else None
                ),
                min_recent_fixed_contact_outcome_all_ready_fraction=(
                    None if index == 0 else 0.08
                ),
                max_recent_hit_next_contact_anchor_err=(
                    None
                    if index < 2
                    else 0.070
                    if index < 4
                    else 0.050
                ),
                min_recent_fixed_contact_s0_arrival_ready_fraction=(
                    0.45 if index == 8 else None
                ),
                fixed_contact_s0_gate_use_advance_eval=index in {8, 9},
                min_recent_fixed_contact_ready_100ms_fraction=(
                    0.45 if index == 8 else None
                ),
                min_recent_fixed_contact_ready_hold_fraction=(
                    0.60 if index == 9 else None
                ),
                min_advance_fixed_contact_ready_hold_worst_bin_fraction=(
                    0.40 if index == 9 else None
                ),
                fixed_contact_xy_bin_success_hit_count=(
                    1
                    if index in {5, 6, 7}
                    else template.fixed_contact_xy_bin_success_hit_count
                ),
                min_advance_fixed_contact_xy_bin_success_rate=(
                    0.65
                    if index == 5
                    else 0.60
                    if index == 6
                    else 0.55
                    if index == 7
                    else (
                        template.min_advance_fixed_contact_xy_bin_success_rate
                    )
                ),
                max_recent_contact_occupancy=0.03,
                max_recent_p95_contact_duration_s=0.020,
                min_recent_contact_edge_to_hit_conversion=(
                    0.85 if index == 0 else 0.90
                ),
                advance_validation_probe_mode="self",
                min_updates=max(80, int(template.min_updates)),
                max_updates=None,
                convergence_hold_updates=max(
                    12, int(template.convergence_hold_updates)
                ),
                notes=(
                    "V147 from-scratch clean-airborne curriculum: actor time "
                    "starts after an analytic separated handoff; the script "
                    "does not add reward, hits or survival time. Control, "
                    "80-D observation, RMP/PD and collision parameters are "
                    "unchanged from the fixed-contact family."
                ),
            )
        )
    if len(result) != 13:
        raise ValueError("V147 must contain exactly 13 registered lessons")
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v148_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU1: isolate the first three clean-contact lessons to one hit."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v147_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        name = stage.name.replace("v147_", "v148_", 1)
        terminate_hits = 1 if index < 3 else 0
        result.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    terminate_after_confirmed_hits=terminate_hits,
                ),
                notes=(
                    "V148 preserves V147 except that the first three clean "
                    "airborne acquisition/pose lessons terminate after the "
                    "first confirmed hit; recurrent lessons remain uncapped."
                ),
            )
        )
    if len(result) != 13:
        raise ValueError("V148 must contain exactly 13 registered lessons")
    if any(
        int(stage.cfg.terminate_after_confirmed_hits) != (1 if index < 3 else 0)
        for index, stage in enumerate(result)
    ):
        raise ValueError("V148 single-hit/recurrent termination contract drift")
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v149_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU0: align one-shot TTC-100 credit before widening the workspace."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v146_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    mid = source[3]
    bridge_cfg = replace(
        mid.cfg,
        fixed_contact_training_phase="v149_g0_arrival_mid_deadline_bridge",
        fixed_contact_ready_deadline_success_weight=0.75,
        fixed_contact_ready_deadline_miss_weight=1.50,
        fixed_contact_s0_arrival_worst_constraint_penalty_weight=5.0,
    )
    commit_cfg = replace(
        bridge_cfg,
        fixed_contact_training_phase="v149_g0_arrival_mid_deadline_commit",
        fixed_contact_ready_deadline_success_weight=1.0,
        fixed_contact_ready_deadline_miss_weight=2.0,
        fixed_contact_s0_arrival_worst_constraint_penalty_weight=10.0,
    )
    bridge = replace(
        mid,
        name="v149_g0_arrival_mid_deadline_bridge",
        cfg=bridge_cfg,
        min_recent_fixed_contact_s0_ready_fraction=0.70,
        min_recent_fixed_contact_s0_arrival_ready_fraction=0.70,
        min_recent_fixed_contact_ready_100ms_fraction=0.70,
        min_advance_fixed_contact_s0_worst_bin_ready_fraction=0.55,
        min_advance_fixed_contact_s0_worst_bin_arrival_ready_fraction=0.55,
        min_updates=max(96, int(mid.min_updates)),
        convergence_hold_updates=max(12, int(mid.convergence_hold_updates)),
        notes=(
            "V149 TTC-100 bridge: restore the stopped V146 mid-workspace "
            "actor and add one-shot deadline credit plus weakest-component "
            "arrival cost. Later 80/60 ms readiness cannot repay a miss."
        ),
    )
    commit = replace(
        mid,
        name="v149_g0_arrival_mid_deadline_commit",
        cfg=commit_cfg,
        min_updates=max(160, int(mid.min_updates)),
        convergence_hold_updates=max(16, int(mid.convergence_hold_updates)),
        notes=(
            "V149 unchanged-domain timing commit at the original V146 "
            "ready@100=0.75 and worst-cell=0.60 gates."
        ),
    )
    tail: list[CurriculumStage] = []
    for stage in source[4:]:
        name = stage.name.replace("v146_", "v149_", 1)
        tail.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    stage.cfg,
                    fixed_contact_training_phase=name,
                    fixed_contact_ready_deadline_success_weight=1.0,
                    fixed_contact_ready_deadline_miss_weight=2.0,
                    fixed_contact_s0_arrival_worst_constraint_penalty_weight=(
                        max(
                            10.0,
                            float(
                                stage.cfg.fixed_contact_s0_arrival_worst_constraint_penalty_weight
                            ),
                        )
                    ),
                ),
                notes=(
                    "V149 retains the V146 domain/gates after committing "
                    "the non-compensable TTC-100 timing contract."
                ),
            )
        )
    result = list(source[:3]) + [bridge, commit] + tail
    if len(result) != 16:
        raise ValueError("V149 must contain exactly 16 registered lessons")
    return result


def _v150_recurrent_cfg(cfg: MjxPredictiveContactCurriculumConfig, *, name: str):
    """Activate only the trace-supported recurrent interface signals."""

    return replace(
        cfg,
        fixed_contact_training_phase=name,
        fixed_contact_post_first_hit_alive_requires_free_flight=True,
        fixed_contact_include_stick_penalty=True,
        fixed_contact_include_failed_hit_penalty=True,
        fixed_contact_include_task_aligned_auxiliary_reward=True,
        fixed_contact_include_recurrent_event_reward=True,
        fixed_contact_include_adaptive_event_penalties=True,
        fixed_contact_recurrent_hit_deadline_s=0.58,
        hit_cadence_use_counted_interval=True,
        hit_cadence_target_interval=0.46,
        hit_cadence_sigma=0.06,
        hit_cadence_reward_weight=0.75,
        hit_min_interval=0.40,
        hit_max_interval=0.52,
        hit_min_interval_penalty_weight=0.50,
        hit_max_interval_penalty_weight=0.75,
        post_hit_overdue_soft_limit_s=0.52,
        post_hit_overdue_penalty_scale_s=0.08,
        post_hit_overdue_penalty_weight=1.0,
        post_hit_overdue_penalty_dt_scaled=True,
        stick_min_contact_steps=4,
        stick_contact_penalty_weight=3.0,
        failed_hit_penalty_weight=3.0,
        fixed_contact_outcome_constraint_aggregation="max",
        fixed_contact_outcome_constraint_penalty_weight=2.0,
        contact_edge_pose_penalty_multiplier=1.0,
        contact_edge_racket_vxy_penalty_multiplier=1.0,
    )


def _fixed_contact_plane_vision_robust_qvel_rmp_v150_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU1: teach detach, return-basin recovery, then capped recurrence."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v148_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    recurrent = source[3]
    detach_name = "v150_g1_post_hit_detach"
    detach_cfg = replace(
        _v150_recurrent_cfg(recurrent.cfg, name=detach_name),
        fixed_contact_post_hit_recovery_lesson_enabled=True,
        fixed_contact_post_hit_recovery_success_weight=3.0,
        fixed_contact_return_basin_lesson_enabled=False,
        terminate_after_confirmed_hits=0,
        horizon_sec=0.75,
    )
    detach = replace(
        recurrent,
        name=detach_name,
        cfg=detach_cfg,
        target_mean_hits=0.80,
        target_hit1_rate=0.85,
        target_hit2_rate=None,
        target_min_hit_interval_s=None,
        target_max_hit_interval_s=None,
        min_updates=max(120, int(recurrent.min_updates)),
        convergence_hold_updates=max(12, int(recurrent.convergence_hold_updates)),
        notes=(
            "V150 post-hit detach lesson: success requires a counted first "
            "hit, clean free flight and actual racket pose/Z recovery."
        ),
    )
    basin_name = "v150_g1_return_basin_ttc100"
    basin_cfg = replace(
        _v150_recurrent_cfg(recurrent.cfg, name=basin_name),
        fixed_contact_post_hit_recovery_lesson_enabled=False,
        fixed_contact_return_basin_lesson_enabled=True,
        fixed_contact_return_basin_success_weight=4.0,
        fixed_contact_ttc_phase_schedule_enabled=True,
        fixed_contact_s0_arrival_worst_constraint_penalty_weight=5.0,
        terminate_after_confirmed_hits=0,
        horizon_sec=1.20,
    )
    basin = replace(
        recurrent,
        name=basin_name,
        cfg=basin_cfg,
        target_mean_hits=0.80,
        target_hit1_rate=0.85,
        target_hit2_rate=None,
        target_min_hit_interval_s=None,
        target_max_hit_interval_s=None,
        min_recent_fixed_contact_s0_arrival_ready_fraction=0.45,
        min_recent_fixed_contact_ready_100ms_fraction=0.45,
        fixed_contact_s0_gate_use_advance_eval=True,
        min_updates=max(160, int(recurrent.min_updates)),
        convergence_hold_updates=max(16, int(recurrent.convergence_hold_updates)),
        notes=(
            "V150 one-hit return-basin lesson: terminate before the second "
            "impact at the next descending TTC=100 ms checkpoint."
        ),
    )

    def two_hit_stage(name: str, target: float, min_updates: int) -> CurriculumStage:
        cfg = replace(
            _v150_recurrent_cfg(recurrent.cfg, name=name),
            fixed_contact_post_hit_recovery_lesson_enabled=False,
            fixed_contact_return_basin_lesson_enabled=False,
            terminate_after_confirmed_hits=2,
            horizon_sec=1.50,
        )
        return replace(
            recurrent,
            name=name,
            cfg=cfg,
            target_mean_hits=1.10,
            target_hit1_rate=0.85,
            target_hit2_rate=target,
            target_hit3_rate=None,
            target_min_hit_interval_s=0.40,
            target_max_hit_interval_s=0.52,
            min_updates=max(min_updates, int(recurrent.min_updates)),
            convergence_hold_updates=max(16, int(recurrent.convergence_hold_updates)),
            notes=(
                "V150 capped two-hit bridge: the second counted hit is the "
                "terminal success event, keeping P2 credit causal."
            ),
        )

    two_hit_bridge = two_hit_stage("v150_g1_two_hit_bridge", 0.15, 160)
    two_hit_commit = two_hit_stage("v150_g1_two_hit_commit", 0.35, 200)
    tail: list[CurriculumStage] = []
    for stage in source[4:]:
        name = stage.name.replace("v148_", "v150_", 1)
        tail.append(
            replace(
                stage,
                name=name,
                cfg=replace(
                    _v150_recurrent_cfg(stage.cfg, name=name),
                    fixed_contact_post_hit_recovery_lesson_enabled=False,
                    fixed_contact_return_basin_lesson_enabled=False,
                    terminate_after_confirmed_hits=0,
                ),
                notes=(
                    "V150 retains the V148 recurrent/domain contract after "
                    "the explicit detach, return-basin and capped-P2 bridge."
                ),
            )
        )
    result = list(source[:3]) + [
        detach,
        basin,
        two_hit_bridge,
        two_hit_commit,
    ] + tail
    if len(result) != 16:
        raise ValueError("V150 must contain exactly 16 registered lessons")
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v151_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU0: learn the undertrained 0.8 reset blend before mixed retention.

    Frozen V149 replay separated the factorized reset population: lanes whose
    racket reset followed the target completely were already ready at the
    TTC-100 deadline, while the 0.8-follow lanes still had a 3--5 cm motion
    and braking task.  These lessons remove the solved 1.0 lanes from the
    actor-gradient population, lengthen preparation first, and then restore
    the original TTC, jitter, and mixed reset distribution.  Advancement
    always evaluates the complete registered XY x {0.8, 1.0} product.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v149_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    bridge = source[3]

    def focus_stage(
        *,
        name: str,
        ttc_range_s: tuple[float, float],
        jitter_m: float,
        recent_ready: float,
        recent_hold: float,
        worst_ready: float,
        min_updates: int,
    ) -> CurriculumStage:
        cfg = replace(
            bridge.cfg,
            fixed_contact_training_phase=name,
            falling_reset_time_to_contact_range_s=ttc_range_s,
            falling_reset_racket_follow_episode_target_xy_blend_range=None,
            falling_reset_racket_follow_episode_target_xy_blend_choices=(0.8,),
            falling_reset_apply_target_follow_blend_choices=True,
            fixed_contact_factorized_reset_validation_blend_choices=(0.8, 1.0),
            fixed_contact_xy_center_probability=0.0,
            fixed_contact_xy_bin_jitter_m=jitter_m,
        )
        return replace(
            bridge,
            name=name,
            cfg=cfg,
            min_recent_fixed_contact_s0_ready_fraction=recent_ready,
            min_recent_fixed_contact_s0_arrival_ready_fraction=recent_ready,
            min_recent_fixed_contact_ready_100ms_fraction=recent_ready,
            min_recent_fixed_contact_ready_hold_fraction=recent_hold,
            min_advance_fixed_contact_s0_worst_bin_ready_fraction=worst_ready,
            min_advance_fixed_contact_s0_worst_bin_arrival_ready_fraction=(
                worst_ready
            ),
            min_advance_fixed_contact_ready_hold_worst_bin_fraction=worst_ready,
            min_updates=max(min_updates, int(bridge.min_updates)),
            convergence_hold_updates=max(
                16, int(bridge.convergence_hold_updates)
            ),
            notes=(
                "V151 reset-blend repair: train only the unsolved 0.8 "
                "racket-follow population while independent advancement "
                "retains every mid-workspace XY x {0.8, 1.0} lane."
            ),
        )

    focus = [
        focus_stage(
            name="v151_g0_blend080_long_exact_bridge",
            ttc_range_s=(0.28, 0.32),
            jitter_m=0.0,
            recent_ready=0.55,
            recent_hold=0.50,
            worst_ready=0.30,
            min_updates=120,
        ),
        focus_stage(
            name="v151_g0_blend080_timing_exact_bridge",
            ttc_range_s=(0.22, 0.32),
            jitter_m=0.0,
            recent_ready=0.60,
            recent_hold=0.55,
            worst_ready=0.40,
            min_updates=140,
        ),
        focus_stage(
            name="v151_g0_blend080_jitter_commit",
            ttc_range_s=(0.16, 0.32),
            jitter_m=0.025,
            recent_ready=0.65,
            recent_hold=0.60,
            worst_ready=0.50,
            min_updates=180,
        ),
    ]
    retention_name = "v151_g0_mid_mixed_retention"
    retention = replace(
        bridge,
        name=retention_name,
        cfg=replace(
            bridge.cfg,
            fixed_contact_training_phase=retention_name,
            falling_reset_time_to_contact_range_s=(0.16, 0.32),
            falling_reset_racket_follow_episode_target_xy_blend_range=None,
            falling_reset_racket_follow_episode_target_xy_blend_choices=(
                0.8,
                1.0,
            ),
            falling_reset_apply_target_follow_blend_choices=True,
            fixed_contact_factorized_reset_validation_blend_choices=(0.8, 1.0),
            fixed_contact_xy_center_probability=0.20,
            fixed_contact_xy_bin_jitter_m=0.025,
        ),
        min_recent_fixed_contact_s0_ready_fraction=0.70,
        min_recent_fixed_contact_s0_arrival_ready_fraction=0.70,
        min_recent_fixed_contact_ready_100ms_fraction=0.70,
        min_recent_fixed_contact_ready_hold_fraction=0.60,
        min_advance_fixed_contact_s0_worst_bin_ready_fraction=0.55,
        min_advance_fixed_contact_s0_worst_bin_arrival_ready_fraction=0.55,
        min_advance_fixed_contact_ready_hold_worst_bin_fraction=0.50,
        min_updates=max(160, int(bridge.min_updates)),
        convergence_hold_updates=max(16, int(bridge.convergence_hold_updates)),
        notes=(
            "V151 restores the original mid-workspace TTC, jitter, center "
            "prior and 0.8/1.0 reset mixture before the unchanged V149 "
            "deadline commit."
        ),
    )
    tail: list[CurriculumStage] = []
    for stage in source[4:]:
        name = stage.name.replace("v149_", "v151_", 1)
        tail.append(
            replace(
                stage,
                name=name,
                cfg=replace(stage.cfg, fixed_contact_training_phase=name),
                notes=(
                    "V151 preserves the V149 objective, domain and gates "
                    "after the isolated 0.8-reset motion curriculum."
                ),
            )
        )
    result = focus + [retention] + tail
    if len(result) != 16:
        raise ValueError("V151 must contain exactly 16 registered lessons")
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v152_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU0: retain solved reset support during the blend-0.8 repair.

    V151 trained its first three lessons exclusively on blend 0.8 while its
    frozen advancement grid also required blend 1.0.  Long plateau training
    consequently forgot some already-solved lanes.  V152 keeps a 3:1 hard to
    retention mixture in every focused lesson and fails closed at a finite
    per-stage cap rather than training indefinitely on a failed gate.
    """

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v151_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    focus_names = (
        "v152_g0_blend080_retention_long_bridge",
        "v152_g0_blend080_retention_timing_bridge",
        "v152_g0_blend080_retention_jitter_commit",
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        if index < 3:
            name = focus_names[index]
            cfg = replace(
                stage.cfg,
                fixed_contact_training_phase=name,
                # Training samples the declared 3:1 repair/retention mix.
                # Frozen advancement independently enables factorized lane
                # assignment through advance_validation_env_cfg().
                fixed_contact_factorized_reset_evaluation=False,
                falling_reset_racket_follow_episode_target_xy_blend_choices=(
                    0.8,
                    1.0,
                ),
                falling_reset_racket_follow_episode_target_xy_blend_choice_probabilities=(
                    0.75,
                    0.25,
                ),
            )
            cap = 800
            notes = (
                "V152 trains the unsolved blend=0.8 lanes with 75% mass and "
                "replays solved blend=1.0 lanes with 25% mass; the complete "
                "factorized frozen grid remains the blocking validator."
            )
        else:
            name = stage.name.replace("v151_", "v152_", 1)
            cfg = replace(stage.cfg, fixed_contact_training_phase=name)
            cap = 1000
            notes = (
                "V152 preserves the V151 objective/domain contract after "
                "closing reset-blend forgetting and adds a fail-closed "
                "finite plateau cap."
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=cfg,
                max_updates=cap,
                notes=notes,
            )
        )
    if len(result) != 16:
        raise ValueError("V152 must contain exactly 16 registered lessons")
    return result


def _fixed_contact_plane_vision_robust_qvel_rmp_v153_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """GPU1: make the first post-hit lesson a true one-hit recovery task."""

    source = _fixed_contact_plane_vision_robust_qvel_rmp_v150_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source):
        if index < 3:
            # These immutable V148 acquisition lessons are checkpoint history;
            # V153 resumes directly at index 3 and never replays them.
            result.append(stage)
            continue
        name = stage.name.replace("v150_", "v153_", 1)
        cfg = replace(stage.cfg, fixed_contact_training_phase=name)
        notes = (
            "V153 preserves the V150 recurrent/domain contract with finite "
            "fail-closed stage caps."
        )
        cap = 1000
        if index == 3:
            name = "v153_g1_post_hit_full_recovery"
            cfg = replace(
                cfg,
                fixed_contact_training_phase=name,
                fixed_contact_post_hit_recovery_require_full_readiness=True,
                # This lesson has exactly one credited contact.  Recurrence,
                # cadence and overdue shaping otherwise pull the actor away
                # from the requested detach-and-stabilize state.
                fixed_contact_include_recurrent_event_reward=False,
                hit_cadence_reward_weight=0.0,
                hit_min_interval_penalty_weight=0.0,
                hit_max_interval_penalty_weight=0.0,
                post_hit_overdue_penalty_weight=0.0,
                hit_reward_cap_mode="fixed",
                hit_reward_count_cap=1,
                horizon_sec=0.38,
            )
            notes = (
                "V153 one-hit recovery lesson: only the first contact earns "
                "event credit; success requires clean free flight plus the "
                "complete actual-racket XY/Z/pose/VXY/omega ready state."
            )
            cap = 800
            stage = replace(
                stage,
                min_recent_fixed_contact_post_hit_recovery_complete_fraction=(
                    0.50
                ),
            )
        result.append(
            replace(
                stage,
                name=name,
                cfg=cfg,
                max_updates=cap,
                notes=notes,
            )
        )
    if len(result) != 16:
        raise ValueError("V153 must contain exactly 16 registered lessons")
    return result


