def _fixed_plane_limit_cycle_qvel_rmp_v4_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Align precision credit and bridge two-hit transfer into steady juggling."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V4 gpu_role must be gpu0 or gpu1")
    v3 = _fixed_plane_limit_cycle_qvel_rmp_v3_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )

    def renamed_cfg(source: MjxFixedContactPlaneVisionConfig, name: str):
        return replace(source, fixed_contact_training_phase=name)

    def precision_cfg(source: MjxFixedContactPlaneVisionConfig, name: str):
        return replace(
            source,
            fixed_contact_training_phase=name,
            # V3 left half of the confirmed-hit credit independent of the
            # weakest contact/return component, then restored most lateral
            # penalties through the event budget.  V4 makes positive event
            # credit proportional to the weakest quality while retaining a
            # two-percent positive floor against the no-contact optimum.
            fixed_contact_event_joint_quality_gate_mix=1.0,
            fixed_contact_hit_event_penalty_budget_fraction=0.98,
            approach_racket_vxy_penalty_weight=2.0,
            hit_racket_vxy_penalty_weight=2.0,
        )

    acquisition_name = f"fplc_v4_{gpu_role}_s1_launch_acquisition"
    acquisition = replace(
        v3[0],
        name=acquisition_name,
        cfg=renamed_cfg(v3[0].cfg, acquisition_name),
        notes=(
            "FIXED-PLANE-LIMIT-CYCLE-V4 preserves the proven V3 acquisition "
            "objective and explicitly graduates it with a stochastic block."
        ),
        advance_eval_deterministic=False,
    )

    precision_name = f"fplc_v4_{gpu_role}_s2_launch_precision"
    precision = replace(
        v3[1],
        name=precision_name,
        cfg=precision_cfg(v3[1].cfg, precision_name),
        notes=(
            "V4 precision makes confirmed-hit credit weakest-quality "
            "proportional, tightens rollout log_std to -1.5, and validates "
            "the deployed deterministic policy mean after stochastic rolling "
            "gates pass."
        ),
        policy_max_log_std=-1.5,
        advance_eval_deterministic=True,
    )

    two_hit_name = f"fplc_v4_{gpu_role}_s3_two_hit_transition"
    two_hit = replace(
        v3[2],
        name=two_hit_name,
        cfg=precision_cfg(v3[2].cfg, two_hit_name),
        notes=(
            "V4 preserves the two-hit transition target and cadence while "
            "retaining gate-aligned quality credit and bounded exploration."
        ),
        policy_max_log_std=-1.5,
        advance_eval_deterministic=True,
    )

    three_hit_name = f"fplc_v4_{gpu_role}_s4_three_hit_steady_entry"
    three_hit_cfg = replace(
        precision_cfg(v3[3].cfg, three_hit_name),
        horizon_sec=2.4,
        terminate_after_confirmed_hits=3,
        hit_cadence_target_interval=0.32,
        hit_cadence_sigma=0.080,
        hit_cadence_reward_weight=0.35,
        hit_min_interval=0.20,
        hit_max_interval=0.46,
        hit_min_interval_penalty_weight=0.25,
        hit_max_interval_penalty_weight=0.25,
        hit_max_interval_penalty_scale=0.080,
    )
    three_hit = replace(
        v3[3],
        name=three_hit_name,
        cfg=three_hit_cfg,
        notes=(
            "V4 explicitly trains the third counted hit that first enters the "
            "1.45 m steady target; it keeps launch-precision quality gates and "
            "does not yet demand a full six-second episode."
        ),
        target_mean_hits=2.20,
        target_mean_len_frac=0.0,
        target_hit1_rate=0.90,
        target_hit2_rate=0.70,
        target_hit3_rate=0.40,
        target_hit5_rate=None,
        target_hit6_rate=None,
        target_hit12_rate=None,
        target_episode_truncation_rate=None,
        target_min_hit_interval_s=0.20,
        target_max_hit_interval_s=0.46,
        max_recent_mean_hit_vxy=0.16,
        max_recent_rms_hit_vxy=0.23,
        max_recent_mean_hit_racket_vxy=0.080,
        max_recent_rms_hit_racket_vxy=0.120,
        max_recent_hit_racket_angular_speed_rad_s=1.00,
        min_recent_mean_hit_apex_abs_z_m=1.20,
        max_recent_mean_hit_apex_abs_z_m=1.38,
        min_recent_fixed_contact_quality_components=(0.30,) * 5,
        min_recent_fixed_contact_return_apex_score=0.35,
        min_recent_contact_edge_to_hit_conversion=0.85,
        fixed_contact_xy_bin_success_hit_count=0,
        min_advance_fixed_contact_xy_bin_success_rate=None,
        min_updates=180,
        convergence_hold_updates=24,
        policy_max_log_std=-1.75,
        advance_eval_deterministic=True,
    )

    short_name = f"fplc_v4_{gpu_role}_s5_short_center_steady_bridge"
    short_cfg = replace(
        precision_cfg(v3[3].cfg, short_name),
        horizon_sec=3.0,
        terminate_after_confirmed_hits=0,
        hit_cadence_target_interval=0.45,
        hit_cadence_sigma=0.120,
        hit_cadence_reward_weight=0.35,
        hit_min_interval=0.30,
        hit_max_interval=0.64,
        hit_min_interval_penalty_weight=0.25,
        hit_max_interval_penalty_weight=0.25,
        hit_max_interval_penalty_scale=0.10,
    )
    short_steady = replace(
        v3[3],
        name=short_name,
        cfg=short_cfg,
        notes=(
            "V4 first exposes post-third-hit steady recovery in a three-second "
            "center episode with intermediate motion and quality gates."
        ),
        target_mean_hits=3.50,
        target_mean_len_frac=0.45,
        target_hit1_rate=0.90,
        target_hit2_rate=0.75,
        target_hit3_rate=0.55,
        target_hit5_rate=None,
        target_hit6_rate=None,
        target_hit12_rate=None,
        target_episode_truncation_rate=0.45,
        target_min_hit_interval_s=0.30,
        target_max_hit_interval_s=0.64,
        max_recent_mean_hit_vxy=0.13,
        max_recent_rms_hit_vxy=0.20,
        max_recent_mean_hit_racket_vxy=0.065,
        max_recent_rms_hit_racket_vxy=0.100,
        max_recent_hit_racket_angular_speed_rad_s=0.80,
        min_recent_mean_hit_apex_abs_z_m=1.25,
        max_recent_mean_hit_apex_abs_z_m=1.45,
        min_recent_fixed_contact_quality_components=(0.35,) * 5,
        min_recent_fixed_contact_return_apex_score=0.40,
        min_recent_contact_edge_to_hit_conversion=0.88,
        fixed_contact_xy_bin_success_hit_count=0,
        min_advance_fixed_contact_xy_bin_success_rate=None,
        min_updates=200,
        convergence_hold_updates=28,
        policy_max_log_std=-2.0,
        advance_eval_deterministic=True,
    )

    downstream = []
    for index, (source, label) in enumerate(
        zip(
            v3[3:],
            ("center_steady", "local_bridge", "local_steady"),
            strict=True,
        ),
        start=6,
    ):
        name = f"fplc_v4_{gpu_role}_s{index}_{label}"
        downstream.append(
            replace(
                source,
                name=name,
                cfg=precision_cfg(source.cfg, name),
                notes=(
                    "V4 retains the corresponding strict V3 steady/workspace "
                    "contract after explicit third-hit and short-horizon "
                    "bridges, with deterministic block validation."
                ),
                policy_max_log_std=-2.0,
                advance_eval_deterministic=True,
            )
        )
    return [
        acquisition,
        precision,
        two_hit,
        three_hit,
        short_steady,
        *downstream,
    ]


