def _fixed_plane_limit_cycle_qvel_rmp_v5_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Restrict V4 to the demonstrated fixed-pose directional workspace."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V5 gpu_role must be gpu0 or gpu1")
    v4 = _fixed_plane_limit_cycle_qvel_rmp_v4_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )
    result: list[CurriculumStage] = []
    for index, source in enumerate(v4, start=1):
        label = source.name.split(f"fplc_v4_{gpu_role}_s{index}_", 1)[-1]
        name = f"fplc_v5_{gpu_role}_s{index}_{label}"
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        if index == 7:
            cfg_updates.update(
                episode_target_x_range_m=(0.0, 0.003125),
                episode_target_y_range_m=(-0.01, 0.0),
                fixed_contact_eval_grid_x_m=(0.0, 0.0015625, 0.003125),
                fixed_contact_eval_grid_y_m=(-0.01, -0.005, 0.0),
            )
        elif index == 8:
            cfg_updates.update(
                episode_target_x_range_m=(0.0, 0.00625),
                episode_target_y_range_m=(-0.02, 0.0),
                fixed_contact_eval_grid_x_m=(0.0, 0.003125, 0.00625),
                fixed_contact_eval_grid_y_m=(-0.02, -0.01, 0.0),
            )
        result.append(
            replace(
                source,
                name=name,
                cfg=replace(source.cfg, **cfg_updates),
                notes=(
                    "V5 preserves the complete V4 objective, plant, actor, "
                    "reward, gate and bridge sequence. Only the last two XY "
                    "supports are restricted to the fixed-pose directional "
                    "workspace demonstrated by the strict 3x3 reachability "
                    "screen."
                ),
            )
        )
    return result


