def _fixed_plane_limit_cycle_qvel_rmp_v6_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Repair V5's post-second-hit distribution and recurrent stroke credit."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V6 gpu_role must be gpu0 or gpu1")
    v5 = _fixed_plane_limit_cycle_qvel_rmp_v5_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )

    def repaired_cfg(
        source: MjxFixedContactPlaneVisionConfig,
        name: str,
        *,
        recurrent: bool,
        disable_transition_cadence: bool = False,
    ) -> MjxFixedContactPlaneVisionConfig:
        updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
            "fixed_contact_workspace_termination_penalty_enabled": True,
            "fixed_contact_workspace_z_barrier_weight": 20.0,
            "fixed_contact_workspace_z_barrier_margin_m": 0.008,
            # Preserve V5's demonstrated hard projection workspace exactly.
            # Both 4 mm and 1 mm inset candidates removed valid directional
            # witnesses; the dense 8 mm barrier supplies the guard signal
            # without changing the feasible action set.
            "cartesian_pose_position_lower_m": (-0.348, -0.70, 1.002),
            "cartesian_pose_position_upper_m": (0.348, -0.28, 1.120),
        }
        if recurrent:
            updates.update(
                # The V5 trace requires about +0.56 m/s at the third contact.
                # Use one causal, non-saturating target-error signal after two
                # confirmed hits.  It rises smoothly from zero to 0.55 m/s in
                # the final 120 ms and stops on the physical edge; no hidden
                # phase teacher or collision override is introduced.
                fixed_contact_recurrent_launch_vz_reward_weight=0.0,
                fixed_contact_smooth_stroke_vz_penalty_weight=8.0,
                fixed_contact_smooth_stroke_peak_m_s=0.55,
                fixed_contact_smooth_stroke_lead_s=0.12,
                fixed_contact_smooth_stroke_brake_lead_s=0.04,
                fixed_contact_smooth_stroke_error_scale_m_s=0.20,
                fixed_contact_smooth_stroke_min_hit_count=2,
                fixed_contact_edge_racket_vz_target_reward_weight=2.0,
                fixed_contact_edge_racket_vz_target_m_s=0.55,
                fixed_contact_edge_racket_vz_sigma_m_s=0.30,
                fixed_contact_edge_racket_vz_min_hit_count=2,
                fixed_contact_edge_racket_vz_qz_gate_mix=1.0,
            )
        if disable_transition_cadence:
            updates.update(
                hit_cadence_reward_weight=0.0,
                hit_min_interval_penalty_weight=0.0,
                hit_max_interval_penalty_weight=0.0,
            )
        return replace(source, **updates)

    result: list[CurriculumStage] = []

    for index, source in enumerate(v5[:2], start=1):
        label = source.name.split(f"fplc_v5_{gpu_role}_s{index}_", 1)[-1]
        name = f"fplc_v6_{gpu_role}_s{index}_{label}"
        result.append(
            replace(
                source,
                name=name,
                cfg=repaired_cfg(source.cfg, name, recurrent=False),
                notes=(
                    "V6 preserves V5 launch behavior while enabling the "
                    "actual fixed-workspace terminal penalty, a dense inner "
                    "Z barrier, and the unchanged reachable V5 hard bounds."
                ),
            )
        )

    exposure_source = v5[2]
    exposure_name = f"fplc_v6_{gpu_role}_s3_post_second_hit_exposure"
    exposure_cfg = replace(
        repaired_cfg(
            exposure_source.cfg,
            exposure_name,
            recurrent=True,
            disable_transition_cadence=True,
        ),
        horizon_sec=2.4,
        terminate_after_confirmed_hits=0,
    )
    result.append(
        replace(
            exposure_source,
            name=exposure_name,
            cfg=exposure_cfg,
            notes=(
                "V6 no longer terminates at the second confirmed hit. The "
                "actor is exposed to hit_count=2 and receives causal dense "
                "credit for the upward third stroke without making a third "
                "confirmed hit a graduation requirement yet."
            ),
            target_min_hit_interval_s=None,
            target_max_hit_interval_s=None,
            min_recent_contact_edge_to_hit_conversion=0.65,
            policy_max_log_std=-1.5,
        )
    )

    bridge_source = v5[3]
    bridge_name = f"fplc_v6_{gpu_role}_s4_third_contact_upstroke_bridge"
    bridge_cfg = repaired_cfg(
        bridge_source.cfg,
        bridge_name,
        recurrent=True,
        disable_transition_cadence=True,
    )
    result.append(
        replace(
            bridge_source,
            name=bridge_name,
            cfg=bridge_cfg,
            notes=(
                "V6 first graduates a low-rate third confirmed hit with "
                "relaxed contact conversion and motion-quality floors. The "
                "physical-edge vertical-speed reward remains q_z gated so "
                "an early/high collision cannot exploit the bridge."
            ),
            target_mean_hits=2.05,
            target_hit3_rate=0.10,
            target_min_hit_interval_s=None,
            target_max_hit_interval_s=None,
            max_recent_mean_hit_racket_vxy=0.12,
            max_recent_rms_hit_racket_vxy=0.18,
            max_recent_hit_racket_angular_speed_rad_s=1.35,
            min_recent_fixed_contact_quality_components=(0.20,) * 5,
            min_recent_fixed_contact_return_apex_score=0.20,
            min_recent_contact_edge_to_hit_conversion=0.65,
            min_updates=120,
            convergence_hold_updates=16,
            policy_max_log_std=-1.5,
        )
    )

    entry_source = v5[3]
    entry_name = f"fplc_v6_{gpu_role}_s5_three_hit_steady_entry"
    result.append(
        replace(
            entry_source,
            name=entry_name,
            cfg=repaired_cfg(
                entry_source.cfg,
                entry_name,
                recurrent=True,
                disable_transition_cadence=True,
            ),
            notes=(
                "V6 restores the strict V5 three-hit gates after the explicit "
                "upstroke bridge, but defers steady-orbit cadence until a "
                "post-third-hit interval actually exists."
            ),
            target_min_hit_interval_s=None,
            target_max_hit_interval_s=None,
            policy_max_log_std=-1.5,
        )
    )

    downstream_labels = (
        "short_center_steady_bridge",
        "center_steady",
        "local_bridge",
        "local_steady",
    )
    for index, (source, label) in enumerate(
        zip(v5[4:], downstream_labels, strict=True),
        start=6,
    ):
        name = f"fplc_v6_{gpu_role}_s{index}_{label}"
        result.append(
            replace(
                source,
                name=name,
                cfg=repaired_cfg(source.cfg, name, recurrent=True),
                notes=(
                    "V6 preserves the corresponding V5 steady/workspace "
                    "contract after repairing recurrent vertical credit, "
                    "workspace boundary incentives and transition exposure."
                ),
                policy_max_log_std=(
                    -1.75 if index == 6 else source.policy_max_log_std
                ),
            )
        )

    if len(result) != 9:
        raise ValueError("fixed-plane limit-cycle V6 must contain nine stages")
    return result


