def _fixed_plane_limit_cycle_qvel_rmp_v9_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Let the shaped bridge hand off before enforcing unshaped precision."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V9 gpu_role must be gpu0 or gpu1")
    v8 = _fixed_plane_limit_cycle_qvel_rmp_v8_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )
    result: list[CurriculumStage] = []
    for index, source in enumerate(v8, start=1):
        name = source.name.replace(
            f"fplc_v8_{gpu_role}_", f"fplc_v9_{gpu_role}_", 1
        )
        updates: dict[str, object] = {
            "name": name,
            "cfg": replace(
                source.cfg,
                fixed_contact_training_phase=name,
            ),
            "notes": "V9 preserves the corresponding V8 lesson exactly.",
        }
        if index == 3:
            updates.update(
                max_recent_mean_hit_racket_vxy=0.22,
                max_recent_rms_hit_racket_vxy=0.30,
                notes=(
                    "V9 makes this an acquisition-only bridge. Its temporary "
                    "upstroke reward must discover and validate hit two, but "
                    "uses motion limits that cover the measured V8 discovery "
                    "trajectory. The next lesson removes that reward and "
                    "restores the original strict motion-quality gates."
                ),
            )
        elif index == 4:
            updates["notes"] = (
                "V9 removes the temporary upstroke reward before restoring "
                "the original 0.08/0.12 m/s mean/RMS racket-VXY gates, full "
                "two-hit retention contract and independent self-validation."
            )
        result.append(replace(source, **updates))

    if len(result) != 11:
        raise ValueError("fixed-plane limit-cycle V9 must contain eleven stages")
    return result


