def _fixed_plane_limit_cycle_qvel_rmp_v10_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Acquire the sparse third hit, then restore its failure contract."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V10 gpu_role must be gpu0 or gpu1")
    v9 = _fixed_plane_limit_cycle_qvel_rmp_v9_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )

    def renamed(
        source: CurriculumStage,
        *,
        target_index: int,
        notes: str,
    ) -> CurriculumStage:
        name = source.name.replace(
            f"fplc_v9_{gpu_role}_s",
            f"fplc_v10_{gpu_role}_s",
            1,
        )
        source_index = int(name.split("_s", 1)[1].split("_", 1)[0])
        name = name.replace(
            f"_s{source_index}_",
            f"_s{target_index}_",
            1,
        )
        return replace(
            source,
            name=name,
            cfg=replace(source.cfg, fixed_contact_training_phase=name),
            notes=notes,
        )

    result = [
        renamed(
            source,
            target_index=index,
            notes=(
                "V10 preserves the corresponding validated V9 launch, "
                "two-hit acquisition, strict retention or positive-tail "
                "exposure lesson exactly."
            ),
        )
        for index, source in enumerate(v9[:5], start=1)
    ]

    third_hit_source = v9[5]
    acquisition_name = (
        f"fplc_v10_{gpu_role}_s6_third_contact_impulse_acquisition"
    )
    result.append(
        replace(
            third_hit_source,
            name=acquisition_name,
            cfg=replace(
                third_hit_source.cfg,
                fixed_contact_training_phase=acquisition_name,
                early_termination_remaining_horizon_penalty=0.0,
                failed_hit_penalty_weight=0.0,
                fixed_contact_smooth_stroke_vz_reward_weight=12.0,
                fixed_contact_edge_racket_vz_target_reward_weight=4.0,
            ),
            notes=(
                "V10 temporarily removes only the failed third-stroke and "
                "remaining-horizon liabilities while modestly increasing "
                "the existing bounded smooth/edge VZ credit. Graduation "
                "still requires a real height-confirmed third hit and all "
                "V9 bridge safety, conversion and motion-quality gates."
            ),
        )
    )

    result.append(
        renamed(
            third_hit_source,
            target_index=7,
            notes=(
                "V10 restores the complete V9 third-hit reward and failure "
                "contract, including weights 35/3 for remaining-horizon/"
                "failed-hit loss and the original 8/2 smooth/edge VZ credit, "
                "before any stricter three-hit lesson."
            ),
        )
    )

    for target_index, source in enumerate(v9[6:], start=8):
        result.append(
            renamed(
                source,
                target_index=target_index,
                notes=(
                    "V10 preserves the corresponding V9 strict three-hit, "
                    "steady-orbit or local-workspace lesson after the "
                    "third-hit acquisition/retention handoff."
                ),
            )
        )

    if len(result) != 12:
        raise ValueError("fixed-plane limit-cycle V10 must contain twelve stages")
    return result


