def _fixed_plane_limit_cycle_qvel_rmp_v11_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Acquire hit two before restoring failure liability and precision."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V11 gpu_role must be gpu0 or gpu1")
    v10 = _fixed_plane_limit_cycle_qvel_rmp_v10_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )

    def renamed(
        source: CurriculumStage,
        *,
        target_index: int,
        notes: str,
    ) -> CurriculumStage:
        source_prefix = f"fplc_v10_{gpu_role}_s"
        suffix = source.name.split(source_prefix, 1)[1]
        label = suffix.split("_", 1)[1]
        name = f"fplc_v11_{gpu_role}_s{target_index}_{label}"
        return replace(
            source,
            name=name,
            cfg=replace(source.cfg, fixed_contact_training_phase=name),
            notes=notes,
        )

    result = [
        renamed(
            source,
            target_index=index,
            notes=(
                "V11 preserves the corresponding V10 placed-launch lesson "
                "exactly."
            ),
        )
        for index, source in enumerate(v10[:2], start=1)
    ]

    second_hit_source = v10[2]
    acquisition_name = (
        f"fplc_v11_{gpu_role}_s3_second_contact_impulse_acquisition"
    )
    result.append(
        replace(
            second_hit_source,
            name=acquisition_name,
            cfg=replace(
                second_hit_source.cfg,
                fixed_contact_training_phase=acquisition_name,
                early_termination_remaining_horizon_penalty=0.0,
                failed_hit_penalty_weight=0.0,
                fixed_contact_recurrent_launch_vz_reward_weight=12.0,
            ),
            notes=(
                "V11 temporarily removes only failed-second-stroke and "
                "remaining-horizon liabilities while increasing the same "
                "bounded causal recurrent-upstroke credit from 8 to 12. "
                "Graduation still requires a real height-confirmed second "
                "hit and every original acquisition safety/quality gate."
            ),
        )
    )

    result.append(
        renamed(
            second_hit_source,
            target_index=4,
            notes=(
                "V11 restores the complete V10 hit-two acquisition contract, "
                "including remaining-horizon/failed-hit weights 12/3 and "
                "recurrent-upstroke weight 8, before shaping is removed."
            ),
        )
    )

    for target_index, source in enumerate(v10[3:], start=5):
        result.append(
            renamed(
                source,
                target_index=target_index,
                notes=(
                    "V11 preserves the corresponding V10 unshaped hit-two, "
                    "post-hit2, hit-three, steady-orbit or local-workspace "
                    "lesson after the second-hit credit handoff."
                ),
            )
        )

    if len(result) != 13:
        raise ValueError("fixed-plane limit-cycle V11 must contain thirteen stages")
    return result


