def _fixed_plane_limit_cycle_qvel_rmp_v12_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Re-test only V10's third-hit repair from V9's passed S5 state."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V12 gpu_role must be gpu0 or gpu1")
    v10 = _fixed_plane_limit_cycle_qvel_rmp_v10_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )
    result: list[CurriculumStage] = []
    for index, source in enumerate(v10, start=1):
        source_prefix = f"fplc_v10_{gpu_role}_s{index}_"
        label = source.name.split(source_prefix, 1)[1]
        name = f"fplc_v12_{gpu_role}_s{index}_{label}"
        result.append(
            replace(
                source,
                name=name,
                cfg=replace(source.cfg, fixed_contact_training_phase=name),
                notes=(
                    "V12 is configuration-identical to V10. Its launcher "
                    "must restore the pinned, passed V9 Stage-5 actor, "
                    "critic and Adam state and begin at Stage 6, isolating "
                    "the third-hit acquisition repair from random-init "
                    "second-hit seed sensitivity."
                ),
            )
        )
    if len(result) != 12:
        raise ValueError("fixed-plane limit-cycle V12 must contain twelve stages")
    return result


