def _fixed_plane_limit_cycle_qvel_rmp_v13_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Align the one-time low-apex to steady-apex contact velocity."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V13 gpu_role must be gpu0 or gpu1")
    v12 = _fixed_plane_limit_cycle_qvel_rmp_v12_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )
    result: list[CurriculumStage] = []
    for index, source in enumerate(v12, start=1):
        source_prefix = f"fplc_v12_{gpu_role}_s{index}_"
        label = source.name.split(source_prefix, 1)[1]
        if index == 6:
            label = "third_contact_velocity_bridge"
        name = f"fplc_v13_{gpu_role}_s{index}_{label}"
        cfg_updates: dict[str, object] = {
            "fixed_contact_training_phase": name,
        }
        if index == 6:
            # Frozen paired replay measured the failed third-contact incoming
            # ball vz at -2.204 m/s.  With the registered 1.045 m contact
            # centre, 1.45 m target apex and e=0.665, the required surface vz
            # was 0.792--0.830 m/s (mean 0.807).  V12's 0.55 m/s target was a
            # steady-orbit value applied one contact too early.
            cfg_updates.update(
                fixed_contact_smooth_stroke_peak_m_s=0.81,
                fixed_contact_edge_racket_vz_target_m_s=0.81,
            )
        result.append(
            replace(
                source,
                name=name,
                cfg=replace(source.cfg, **cfg_updates),
                notes=(
                    "V13 preserves V12 except that its Stage-6 one-time "
                    "1.275-to-1.45 m apex transition uses the measured "
                    "0.81 m/s contact-velocity target. Stage 7 immediately "
                    "restores V12's 0.55 m/s steady-orbit target and full "
                    "failure contract."
                    if index == 6
                    else "V13 preserves the corresponding V12 lesson exactly."
                ),
            )
        )
    if len(result) != 12:
        raise ValueError("fixed-plane limit-cycle V13 must contain twelve stages")
    return result


