def _fixed_plane_limit_cycle_qvel_rmp_v15_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Train one full launch-to-limit-cycle objective from the first update."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V15 gpu_role must be gpu0 or gpu1")
    v14 = _fixed_plane_limit_cycle_qvel_rmp_v14_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )

    # V14 Stage 10 already owns the complete six-second centered task.  V15
    # uses that one physical distribution from update zero instead of first
    # terminating after one, then two, then three hits.  Its causal apex
    # schedule remains 1.10 -> 1.275 -> 1.45 m, so the placed-ball launch is
    # feasible while every recurrent contact is immediately trained toward
    # the final 1.45 m orbit.
    source = v14[9]
    shared_cfg = replace(
        source.cfg,
        horizon_sec=6.0,
        terminate_after_confirmed_hits=0,
        episode_target_x_range_m=(0.0, 0.0),
        episode_target_y_range_m=(0.0, 0.0),
        fixed_contact_eval_grid_x_m=(0.0,),
        fixed_contact_eval_grid_y_m=(0.0,),
        fixed_contact_xy_bin_sampling_enabled=False,
        fixed_contact_xy_equal_bin_evaluation=False,
        fixed_contact_xy_equal_bin_seed_permutation=False,
        # Use the live inverse-impact target throughout, but keep its shaping
        # subordinate to the physical apex and low-motion outcome terms.
        fixed_contact_recurrent_launch_vz_reward_weight=0.0,
        fixed_contact_smooth_stroke_vz_reward_weight=4.0,
        fixed_contact_smooth_stroke_min_hit_count=1,
        fixed_contact_edge_racket_vz_target_reward_weight=1.0,
        fixed_contact_edge_racket_vz_min_hit_count=1,
        fixed_contact_phase_stroke_min_hit_count=1,
        fixed_contact_phase_stroke_replace_dense_z_target=True,
        # A single fixed 0.575 s cadence objective conflicts with the shorter
        # physically required launch/transition flights.  The scheduled apex
        # itself determines the correct cadence; only steady-course gates
        # measure the resulting interval.
        hit_cadence_reward_weight=0.0,
        hit_min_interval_penalty_weight=0.0,
        hit_max_interval_penalty_weight=0.0,
        # Reward the scheduled apex directly on every confirmed contact and
        # make low-horizontal/low-angular contacts more valuable from the
        # first launch rather than repairing motion in a later stage.
        hit_apex_target_reward_weight=3.0,
        hit_apex_target_reward_sigma_m=0.030,
        hit_apex_target_motion_quality_independent=True,
        hit_racket_vxy_penalty_weight=4.0,
        hit_racket_vxy_soft_limit_m_s=0.050,
        hit_racket_vxy_penalty_scale_m_s=0.080,
        hit_racket_vxy_apply_from_first_hit=True,
        contact_edge_racket_vxy_penalty_multiplier=0.5,
        hit_racket_angular_speed_penalty_weight=1.0,
        hit_racket_angular_speed_soft_limit_rad_s=0.65,
        hit_racket_angular_speed_scale_rad_s=0.50,
        hit_racket_angular_speed_reward_weight=0.50,
        hit_racket_angular_speed_reward_target_rad_s=0.65,
        hit_racket_angular_speed_reward_sigma_rad_s=0.35,
        hit_vxy_penalty_weight=1.0,
        hit_vxy_soft_limit_m_s=0.10,
        hit_vxy_penalty_scale_m_s=0.15,
        hit_vxy_zero_reward_weight=0.50,
        fixed_contact_survival_reward_weight=0.10,
        # Keep failure finite and identical in every lesson.  This avoids the
        # V9--V14 pattern where a newly exposed tail suddenly acquired a much
        # larger liability than the launch policy had ever optimized.
        early_termination_remaining_horizon_penalty=4.0,
        failed_hit_penalty_weight=1.0,
        domain_randomization=False,
    )

    specs = (
        {
            "label": "launch_transition_acquisition",
            "mean_hits": 2.0,
            "hit1": 0.75,
            "hit2": 0.45,
            "hit3": 0.05,
            "hit6": None,
            "hit12": None,
            "full": None,
            "mean_len": 0.10,
            "ball_vxy": (0.16, 0.23),
            "racket_vxy": (0.14, 0.20),
            "omega": 1.20,
            "apex": (1.15, 1.40),
            "quality": 0.25,
            "apex_score": 0.30,
            "conversion": 0.55,
            "cadence": (None, None),
            "xy": ((0.0, 0.0), (0.0, 0.0)),
            "grid": ((0.0,), (0.0,)),
            "xy_hits": 0,
            "xy_rate": None,
            "min_updates": 140,
            "hold_updates": 16,
        },
        {
            "label": "center_transition_retention",
            "mean_hits": 3.0,
            "hit1": 0.85,
            "hit2": 0.65,
            "hit3": 0.30,
            "hit6": 0.05,
            "hit12": None,
            "full": 0.15,
            "mean_len": 0.25,
            "ball_vxy": (0.13, 0.20),
            "racket_vxy": (0.10, 0.15),
            "omega": 1.00,
            "apex": (1.23, 1.43),
            "quality": 0.30,
            "apex_score": 0.35,
            "conversion": 0.70,
            "cadence": (None, None),
            "xy": ((0.0, 0.0), (0.0, 0.0)),
            "grid": ((0.0,), (0.0,)),
            "xy_hits": 0,
            "xy_rate": None,
            "min_updates": 180,
            "hold_updates": 20,
        },
        {
            "label": "center_limit_cycle",
            "mean_hits": 7.0,
            "hit1": 0.92,
            "hit2": 0.82,
            "hit3": 0.70,
            "hit6": 0.50,
            "hit12": 0.10,
            "full": 0.55,
            "mean_len": 0.55,
            "ball_vxy": (0.10, 0.16),
            "racket_vxy": (0.05, 0.08),
            "omega": 0.65,
            "apex": (1.34, 1.46),
            "quality": 0.45,
            "apex_score": 0.50,
            "conversion": 0.92,
            "cadence": (0.46, 0.64),
            "xy": ((0.0, 0.0), (0.0, 0.0)),
            "grid": ((0.0,), (0.0,)),
            "xy_hits": 0,
            "xy_rate": None,
            "min_updates": 260,
            "hold_updates": 32,
        },
    )

    result: list[CurriculumStage] = []
    for index, spec in enumerate(specs, start=1):
        name = f"fplc_v15_{gpu_role}_s{index}_{spec['label']}"
        xy_hits = int(spec["xy_hits"])
        cfg = replace(
            shared_cfg,
            fixed_contact_training_phase=name,
            episode_target_x_range_m=spec["xy"][0],
            episode_target_y_range_m=spec["xy"][1],
            fixed_contact_eval_grid_x_m=spec["grid"][0],
            fixed_contact_eval_grid_y_m=spec["grid"][1],
            fixed_contact_xy_bin_sampling_enabled=xy_hits > 0,
            fixed_contact_xy_equal_bin_evaluation=xy_hits > 0,
            fixed_contact_xy_equal_bin_seed_permutation=xy_hits > 0,
        )
        result.append(
            replace(
                source,
                name=name,
                cfg=cfg,
                notes=(
                    "FIXED-PLANE-LIMIT-CYCLE-V15 trains the same six-second "
                    "placed-launch -> 1.275 m transition -> 1.45 m steady "
                    "orbit from the first update. Center stages change only "
                    "graduation evidence; reward, horizon, reset and control "
                    "are invariant. V15 deliberately keeps the first course "
                    "on the independently reachable center cell; XY support "
                    "belongs to a later successor after this orbit passes. "
                    "GPU role="
                    f"{gpu_role}."
                ),
                target_mean_hits=float(spec["mean_hits"]),
                target_mean_len_frac=float(spec["mean_len"]),
                target_hit1_rate=float(spec["hit1"]),
                target_hit2_rate=float(spec["hit2"]),
                target_hit3_rate=float(spec["hit3"]),
                target_hit5_rate=None,
                target_hit6_rate=spec["hit6"],
                target_hit12_rate=spec["hit12"],
                target_episode_truncation_rate=spec["full"],
                target_min_hit_interval_s=spec["cadence"][0],
                target_max_hit_interval_s=spec["cadence"][1],
                hit_interval_gate_source="counted_hit_event",
                max_recent_mean_hit_vxy=float(spec["ball_vxy"][0]),
                max_recent_rms_hit_vxy=float(spec["ball_vxy"][1]),
                max_recent_mean_hit_racket_vxy=float(spec["racket_vxy"][0]),
                max_recent_rms_hit_racket_vxy=float(spec["racket_vxy"][1]),
                max_recent_hit_racket_angular_speed_rad_s=float(spec["omega"]),
                min_recent_mean_hit_apex_abs_z_m=float(spec["apex"][0]),
                max_recent_mean_hit_apex_abs_z_m=float(spec["apex"][1]),
                max_recent_hit_next_contact_anchor_err=0.050,
                target_racket_up_cos=float(np.cos(np.deg2rad(3.0))),
                min_recent_fixed_contact_quality_components=(
                    (float(spec["quality"]),) * 5
                ),
                min_recent_fixed_contact_return_apex_score=float(
                    spec["apex_score"]
                ),
                min_recent_contact_edge_to_hit_conversion=float(
                    spec["conversion"]
                ),
                fixed_contact_xy_bin_success_hit_count=xy_hits,
                min_advance_fixed_contact_xy_bin_success_rate=spec["xy_rate"],
                advance_validation_probe_mode="self",
                advance_transfer_cap_min_hits_at_stage_target=True,
                min_updates=int(spec["min_updates"]),
                convergence_hold_updates=int(spec["hold_updates"]),
                max_updates=None,
                policy_max_log_std=-1.5,
                advance_eval_deterministic=True,
            )
        )
    return result


