def _fixed_plane_limit_cycle_qvel_rmp_v16_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
    gpu_role: str,
) -> list[CurriculumStage]:
    """Repair only V15's premature launch-exploration ceiling."""

    if gpu_role not in {"gpu0", "gpu1"}:
        raise ValueError("fixed-plane limit-cycle V16 gpu_role must be gpu0 or gpu1")
    v15 = _fixed_plane_limit_cycle_qvel_rmp_v15_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        gpu_role=gpu_role,
    )
    result: list[CurriculumStage] = []
    for index, source in enumerate(v15, start=1):
        prefix = f"fplc_v15_{gpu_role}_s{index}_"
        label = source.name.split(prefix, 1)[1]
        name = f"fplc_v16_{gpu_role}_s{index}_{label}"
        result.append(
            replace(
                source,
                name=name,
                cfg=replace(
                    source.cfg,
                    fixed_contact_training_phase=name,
                ),
                notes=(
                    "FIXED-PLANE-LIMIT-CYCLE-V16 is a single-factor repair "
                    "of the negative V15 50-update probe. Stage 1 removes "
                    "only the premature -1.5 log-std ceiling so random-init "
                    "PPO can rediscover placed-ball launch; the complete "
                    "six-second objective, rewards, reset, gates, plant and "
                    "all later-stage exploration settings are unchanged. "
                    f"GPU role={gpu_role}."
                ),
                policy_max_log_std=(
                    None if index == 1 else source.policy_max_log_std
                ),
            )
        )
    return result


