def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v22_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Keep V21 lessons; make measured-q error envelope nonbinding."""

    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v21_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("fplc_v21_", "fplc_v22_", 1)
        result.append(replace(
            stage,
            name=name,
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=name,
                recovered_rmp_qvel_reference_error_horizon_s=0.0,
                recovered_rmp_qvel_reference_error_horizon_s_per_joint=(
                    10.0,
                ) * 7,
            ),
            notes=(
                "V22 alone makes the measured-q reference-error envelope "
                "nonbinding across the pinned XML joint range; persistent "
                "q_ref integration, QVEL and joint limits, Cartesian hard "
                "projection, RMP/PD, PPO, resets, rewards and gates stay "
                "identical to V21. " + stage.notes
            ),
        ))
    return result


