def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v30_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Learn quiet full-horizon transitions before tightening steady gates."""

    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v24_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    # Ball mean/RMS, racket mean/RMS, full omega, first-launch VXY,
    # next-contact anchor error, and five-component contact quality.
    limits = (
        (.18, .26, .16, .24, 1.10, .14, .10, .15),
        (.16, .24, .14, .21, 1.00, .12, .09, .18),
        (.14, .22, .12, .18, .90, .10, .08, .22),
        (.13, .20, .10, .15, .80, .09, .07, .28),
        (.12, .18, .08, .13, .70, .08, .06, .35),
        (.12, .18, .065, .105, .65, .07, .05, .45),
    )
    result: list[CurriculumStage] = []
    for index, (stage, gates) in enumerate(zip(source, limits), start=1):
        (
            ball_mean, ball_rms, racket_mean, racket_rms,
            omega, first_ball_vxy, anchor, quality,
        ) = gates
        name = stage.name.replace("fplc_v24_", "fplc_v30_", 1)
        cfg = replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            # V24's tiny delta cost is ineffective with a nonbinding,
            # persistent q_ref. Keep the same integration and projector.
            action_delta_penalty_weight=0.25,
            fixed_contact_s0_vxy_reward_weight=1.50,
            fixed_contact_s0_omega_reward_weight=1.00,
        )
        result.append(replace(
            stage,
            name=name,
            cfg=cfg,
            notes=(
                "V30 preserves V24's full six-second placed-ball course, "
                "1.10/1.249/1.40/1.45 m impact goals, 1.025 m surface, "
                "nonbinding integrated q_ref, Cartesian projection and "
                "RMP/PD. An effective action-delta cost and stronger "
                "precontact low-VXY/full-omega credit act from Stage 1; "
                "graduation gates reject high-motion launch and late hits. "
                "No episode ends on a hit count."
            ),
            target_mean_hits=(1.30 if index == 1 else stage.target_mean_hits),
            target_hit1_rate=(0.70 if index == 1 else stage.target_hit1_rate),
            target_hit2_rate=(0.25 if index == 1 else stage.target_hit2_rate),
            max_recent_mean_hit_vxy=float(ball_mean),
            max_recent_rms_hit_vxy=float(ball_rms),
            max_recent_mean_first_hit_ball_vxy=float(first_ball_vxy),
            require_aggregate_hit_vxy_with_first_hit=True,
            max_recent_mean_hit_racket_vxy=float(racket_mean),
            max_recent_rms_hit_racket_vxy=float(racket_rms),
            max_recent_rms_steady_hit_racket_vxy=(
                .18 if index == 4 else .12 if index == 5
                else .08 if index == 6 else None
            ),
            max_recent_hit_racket_angular_speed_rad_s=float(omega),
            max_recent_hit_next_contact_anchor_err=float(anchor),
            min_recent_fixed_contact_quality_components=(
                (float(quality),) * 5
            ),
            min_recent_fixed_contact_return_apex_score=float(quality),
            max_recent_rapid_steady_racket_vxy_rms_m_s=(
                .18 if index == 4 else .12 if index == 5
                else .08 if index == 6 else None
            ),
            max_recent_rapid_steady_racket_omega_rms_rad_s=(
                .80 if index == 4 else .70 if index == 5
                else .65 if index == 6 else None
            ),
        ))
    return result

def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v31_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Pay extra for confirmed contact quality, never for quiet misses."""

    v24 = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v24_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    quiet_gates = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v30_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    result: list[CurriculumStage] = []
    for base, gated in zip(v24, quiet_gates):
        name = base.name.replace("fplc_v24_", "fplc_v31_", 1)
        cfg = replace(
            base.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_quality_reward_weight=3.0,
        )
        result.append(replace(
            gated,
            name=name,
            cfg=cfg,
            notes=(
                "V31 preserves V24's full-horizon transition, nonbinding "
                "persistent QVEL reference, Cartesian projection, RMP/PD, "
                "placed-ball reset and entire physics contract. It uses "
                "V30's early quiet-motion graduation gates but restores "
                "V24's action-delta and precontact reward coefficients. "
                "Only confirmed-hit contact-quality credit rises 1.0 to "
                "3.0; a quiet miss earns no extra quality reward."
            ),
        ))
    return result


