def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v33_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Keep V24 behavior and put hit-VXY costs inside a useful event budget."""

