def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v34_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Learn clean 4 g juggling before adding small RMP/PD DR."""

    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v33_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("fplc_v33_", "fplc_v34_", 1)
        cfg = replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            # DR is active solely to patch the 2.7 g XML to an exact 4 g
            # episode body, with spherical inertia. All randomizers stay off.
            domain_randomization=True,
            dr_randomize_ball=True,
            dr_ball_mass_range=(0.004, 0.004),
            dr_ball_normalized_inertia_range=(0.4, 0.4),
            dr_randomize_contact=False,
            dr_randomize_pd=False,
            dr_randomize_recovered_rmp=False,
            dr_randomize_racket_mount=False,
            dr_randomize_latency=False,
            dr_randomize_ball_obs_frame=False,
            dr_damping_mult_range=(1.0, 1.0),
            dr_armature_mult_range=(1.0, 1.0),
            fixed_plane_rapid_steady_subfloor_bridge_enabled=False,
            fixed_plane_v34_quiet_motion_weight=1.0,
            fixed_plane_v34_weak_launch_weight=1.0,
            fixed_plane_v34_resolve_weak_launch=True,
            hit_failed_confirmation_termination_enabled=False,
        )
        result.append(replace(
            stage,
            name=name,
            cfg=cfg,
            notes=(
                "V34 clean 4 g lesson: physical weak launches receive bounded "
                "lift credit and resolve pending state without counting a hit. "
                "Early free-flight motion is quieted while the final 180 ms "
                "stroke is free. No stochastic DR precedes steady juggling."
            ),
        ))
    clean = result[-1]
    for index, (label, gain_half_width) in enumerate((
        ("clean_stability", 0.0),
        ("rmp_pd_dr_bridge", 0.01),
        ("rmp_pd_dr_commit", 0.02),
        ("rmp_pd_dr_consolidate", 0.02),
    ), start=7):
        name = f"fplc_v34_gpu0_s{index}_{label}"
        randomize = gain_half_width > 0.0
        cfg = replace(
            clean.cfg,
            fixed_contact_training_phase=name,
            dr_randomize_pd=randomize,
            dr_randomize_recovered_rmp=randomize,
            dr_pd_kp_mult_range=(1.0 - gain_half_width, 1.0 + gain_half_width),
            dr_pd_kv_mult_range=(1.0 - gain_half_width, 1.0 + gain_half_width),
            dr_rmp_jnt_kp_mult_range=(
                1.0 - gain_half_width, 1.0 + gain_half_width
            ),
            dr_rmp_jnt_kd_mult_range=(
                1.0 - gain_half_width, 1.0 + gain_half_width
            ),
            dr_rmp_estimator_process_mult_range=(1.0, 1.0),
            dr_rmp_estimator_measure_mult_range=(1.0, 1.0),
            dr_rmp_velocity_feedforward_range=(0.5, 0.5),
            dr_rmp_acceleration_weight_mult_range=(1.0, 1.0),
            dr_rmp_target_filter_length_range=(10, 10),
            dr_rmp_output_delay_offset_steps_range=(0, 0),
            dr_armature_mult_range=(1.0, 1.0),
            dr_damping_mult_range=(1.0, 1.0),
        )
        result.append(replace(
            clean,
            name=name,
            cfg=cfg,
            min_updates=max(clean.min_updates, 80),
            notes=(
                f"V34 Stage {index}: {label}; RMP/PD gain multiplier "
                f"half-width {gain_half_width:.1%}. The preceding clean "
                "steady stage must pass rolling and independent validation."
            ),
        ))
    return result


