def validate_fixed_plane_limit_cycle_v35_resume_payload(
    payload: dict[str, object],
    *,
    source_sha256: str,
    requested_start_stage: str,
    resume_curriculum_state: bool,
) -> None:
    """Fail closed on source and state for V33-to-4 g adaptation."""

    expected_sha = "10f59abe30be7e2ec5f3208b3191218522614359a1910601fb7409adc19d46ec"
    if source_sha256 != expected_sha:
        raise ValueError("V35 requires pinned V33 interrupted checkpoint SHA-256")
    if requested_start_stage != "fplc_v35_gpu0_s4_fourth_entry":
        raise ValueError("V35 must start at its fourth-entry bridge")
    if resume_curriculum_state:
        raise ValueError("V35 starts fresh stage/convergence history")
    source_args = payload.get("args")
    if not isinstance(source_args, dict) or source_args.get("curriculum_profile") != (
        "fixed_plane_limit_cycle_qvel_rmp_gpu0_v33"
    ):
        raise ValueError("V35 source must be fixed-plane V33")
    expected = {
        "stage_name": "fplc_v33_gpu0_s5_steady_quality",
        "stage_index": 5,
        "global_update": 3553,
        "step": 465698816,
        "obs_dim": 96,
        "critic_obs_dim": 417,
        "act_dim": 7,
    }
    for key, value in expected.items():
        if payload.get(key) != value:
            raise ValueError(f"V35 source {key} mismatch")
    if payload.get("params") is None or payload.get("opt") is None:
        raise ValueError("V35 must restore actor, critic and Adam moments")


