def validate_fixed_plane_v85_supervision_contract(
    *,
    obs_path: Path | None,
    actions_path: Path | None,
    expected_obs_sha: str,
    expected_actions_sha: str,
    coefficient: float,
    weight_mode: str,
    focus_tail_rows: int,
    focus_prob: float,
) -> None:
    """Pin V85 to finite, bounded 96-D/7-D precontact action labels."""

    if not np.isclose(coefficient, 0.02, rtol=0.0, atol=1e-12):
        raise ValueError("V85 counterfactual supervision coefficient must be 0.02")
    if weight_mode != "uniform":
        raise ValueError("V85 teacher labels require uniform sample weights")
    if focus_tail_rows != 0 or not np.isclose(focus_prob, 0.0):
        raise ValueError("V85 prohibits counterfactual focus-tail mixing")
    if obs_path is None or actions_path is None:
        raise ValueError("V85 requires both pinned teacher array paths")
    if (
        hashlib.sha256(obs_path.read_bytes()).hexdigest() != expected_obs_sha
        or hashlib.sha256(actions_path.read_bytes()).hexdigest()
        != expected_actions_sha
    ):
        raise ValueError("V85 teacher SHA mismatch")
    obs = np.load(obs_path, allow_pickle=False)
    actions = np.load(actions_path, allow_pickle=False)
    if (
        obs.ndim != 2 or actions.ndim != 2
        or obs.shape[1] != 96 or actions.shape[1] != 7
        or obs.shape[0] != actions.shape[0] or obs.shape[0] < 20
        or not np.isfinite(obs).all() or not np.isfinite(actions).all()
        or np.max(np.abs(actions)) > 1.0 + 1e-6
    ):
        raise ValueError("V85 teacher array shape/value contract failed")


