def validate_fixed_plane_v89_continuation_payload(
    payload: dict[str, object], *, requested_start_stage: str,
    resume_curriculum_state: bool, reset_optimizer: bool, reset_critic: bool,
    current_args: dict[str, object] | None = None,
) -> None:
    """Restore only exact V89 u570 actor, critic, Adam and stage history."""
    source_args = payload.get("args", {})
    if not isinstance(source_args, dict):
        raise ValueError("V89 continuation requires dictionary source arguments")
    expected_args = {
        "curriculum_profile": FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V89_PROFILE,
        "steady_band_focus": True,
        "n_steps": 128,
        "residual_action_scale": 0.2,
        "residual_l2_coef": 0.02,
        "max_stage_updates": -1,
    }
    for name, expected in expected_args.items():
        actual = source_args.get(name)
        if isinstance(expected, float):
            try:
                matches = bool(np.isclose(actual, expected, rtol=0.0, atol=1e-12))
            except (TypeError, ValueError):
                matches = False
            if not matches:
                raise ValueError(f"V89 source {name} mismatch")
        elif actual != expected:
            raise ValueError(f"V89 source {name} mismatch")
    if current_args is not None:
        fixed_fields = (
            "seed", "n_envs", "n_steps", "minibatch_size", "update_epochs",
            "learning_rate", "gamma", "gae_lambda", "clip_range",
            "target_kl", "ent_coef", "vf_coef", "max_grad_norm",
            "hidden_dim", "fourth_arrival_focus_tail_steps",
            "fourth_arrival_focus_mass", "fourth_arrival_focus_max_ordinal",
            "fourth_arrival_good_racket_vxy_limit_m_s",
            "convergence_window", "convergence_min_episodes",
            "residual_action_scale", "residual_l2_coef", "steady_band_focus",
            "max_stage_updates", "max_stages",
        )
        for name in fixed_fields:
            old, new = source_args.get(name), current_args.get(name)
            if isinstance(old, (int, float)) and not isinstance(old, bool):
                try:
                    same = bool(np.isclose(old, new, rtol=0.0, atol=1e-12))
                except (TypeError, ValueError):
                    same = False
            else:
                same = old is not None and old == new
            if not same:
                raise ValueError(f"V89 continuation changes {name}")
    required = {
        "stage_index": 4,
        "stage_name": "fplc_v89_gpu0_s4_fourth_entry",
        "stage_update": 570,
        "global_update": 570,
        "step": 685408256,
        "obs_dim": 98,
        "critic_obs_dim": 419,
        "act_dim": 7,
    }
    for name, expected in required.items():
        if payload.get(name) != expected:
            raise ValueError(f"V89 continuation {name} mismatch")
    if (
        requested_start_stage != required["stage_name"]
        or not resume_curriculum_state or reset_optimizer or reset_critic
    ):
        raise ValueError("V89 continuation requires exact stage/history/optimizer")
    params = payload.get("params")
    if not isinstance(params, dict) or not all(name in params for name in (
        "pi", "v", "teacher_pi", "residual_precontact_gate_v1",
        "teacher_obs_prefix96_v1",
    )) or payload.get("opt") is None:
        raise ValueError("V89 continuation actor/critic/Adam contract failed")
    cfg = payload.get("env_cfg")
    weight = cfg.get("fixed_plane_v88_positive_height_weight") if isinstance(cfg, dict) else None
    if weight is None or not np.isclose(weight, 1.0, rtol=0.0, atol=1e-12):
        raise ValueError("V89 continuation late-height reward contract failed")


