def validate_fixed_plane_v92_history_contract(
    *, xml_path: Path, requested_start_stage: str,
    resume_curriculum_state: bool, resume_from: Path | None,
    residual_teacher_checkpoint: Path | None, xla_flags: str,
    expected_xml_sha: str = (
        "7d98f2adfdbad6082be0defcec2dbd0cbbcaf1f0fc06ce45ba424b5b3257cc92"
    ),
) -> None:
    """Keep V92 causal-history training separate from velocity-input actors."""
    if hashlib.sha256(xml_path.read_bytes()).hexdigest() != expected_xml_sha:
        if expected_xml_sha == (
            "750ea510318622e8f6f00a23ebaa020d321528ac274f2623e17ceba65fcd2ce9"
        ):
            raise ValueError("V97 requires the pinned calibrated 62.5 us XML")
        raise ValueError("V92 requires the pinned original 1 ms XML")
    if requested_start_stage not in ("", "auto") or resume_curriculum_state:
        raise ValueError("V92 starts at Stage 1 with fresh curriculum history")
    if resume_from is not None or residual_teacher_checkpoint is not None:
        raise ValueError("V92 cannot load a velocity-input V53/V91 actor")
    if "--xla_gpu_deterministic_ops=true" not in xla_flags.split():
        raise ValueError("V92 requires deterministic GPU ops")



def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v92_stages(
    stages: list[CurriculumStage],
    *, measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Use V33 contact with a history-only actor and signed late height."""
    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v91_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    below_max = (0.55, 0.40, 0.15, 0.0)
    above_max = (0.25, 0.20, 0.10, 0.0)
    in_band_min = (0.25, 0.45, 0.70, 1.0)
    adjacent_max_m = (0.07, 0.06, 0.04, 0.025)
    result = []
    for index, stage in enumerate(source):
        name = stage.name.replace("fplc_v91_", "fplc_v92_", 1)
        cfg = replace(
            stage.cfg,
            fixed_contact_training_phase=name,
            fixed_contact_actor_observation_schema=V92_ACTOR_OBSERVATION_SCHEMA,
            fixed_contact_actor_obs_dim=V92_ACTOR_OBS_DIM,
            fixed_plane_v63_previous_apex_error_obs_enabled=False,
            fixed_plane_v92_history_obs_enabled=True,
            fixed_plane_v92_signed_height_enabled=index >= 3,
            fixed_plane_limit_cycle_steady_apex_z_m=1.425,
            fixed_plane_limit_cycle_apex_schedule_z_m=(
                1.10, 1.249, 1.400, 1.425,
            ),
            fixed_contact_target=replace(
                stage.cfg.fixed_contact_target, target_apex_z_m=1.425
            ),
        )
        gate_values = {}
        if index >= 3:
            late = index - 3
            gate_values = {
                "max_recent_late_physical_below_floor_rate": below_max[late],
                "max_recent_late_physical_above_ceiling_rate": above_max[late],
                "min_recent_late_physical_in_band_rate": in_band_min[late],
                "max_recent_late_adjacent_jump_m": adjacent_max_m[late],
            }
        result.append(replace(
            stage, name=name, cfg=cfg, **gate_values,
            notes=(
                "V92 keeps V91's 1 ms/4 g/V33 contact and measured-QVEL/RMP "
                "plant; its 137-D actor reads causal ball-position and racket "
                "pose history without ball velocity. Every fourth-plus true "
                "rebound receives signed 1.400--1.450 m height credit, "
                "including weak and fast contacts; unresolved contact is "
                "penalized. Independent final gate requires no out-of-band "
                "resolved impacts. From-scratch observation contract."
            ),
        ))
    return result



