def validate_fixed_plane_v116_resume_payload(
    payload: dict[str, object],
    *,
    requested_start_stage: str,
    resume_curriculum_state: bool,
    reset_optimizer: bool,
) -> None:
    """Pin V114 Stage-2 u529 or an exact V116 Stage-2 continuation."""

    source_args = payload.get("args")
    source_profile = (
        source_args.get("curriculum_profile")
        if isinstance(source_args, dict)
        else getattr(source_args, "curriculum_profile", None)
    )
    source_stage = str(payload.get("stage_name", ""))
    source_step = int(payload.get("step", -1))
    source_update = int(payload.get("stage_update", -1))
    target_stage = "fplc_v116_gpu0_s2_third_lift"
    if requested_start_stage != target_stage or reset_optimizer:
        raise ValueError("V116 must resume Stage 2 with actor, critic and Adam")
    if (
        int(payload.get("obs_dim", -1)) != 156
        or int(payload.get("critic_obs_dim", -1)) != 477
        or int(payload.get("act_dim", -1)) != 7
        or not isinstance(payload.get("params"), dict)
        or not {"pi", "v"}.issubset(payload["params"])
        or payload.get("opt") is None
    ):
        raise ValueError("V116 requires the matching 156-D actor and optimizer")
