def _fixed_plane_limit_cycle_qvel_rmp_gpu1_v150_stages(
    stages: list[CurriculumStage],
    *, measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Align onset centering before retaining GPU0's precision rewards."""
    simple = _fixed_plane_limit_cycle_qvel_rmp_gpu1_v149_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg)
    precision = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v149_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg)
    result = []
    late_fields = (
        'fixed_plane_v128_early_xy_motion_weight', 'racket_cycle_vxy_penalty_weight',
        'fixed_plane_v134_late_xy_anchor_penalty_weight',
        'hit_contact_center_excess_penalty_weight', 'hit_contact_center_excess_radius_m',
    )
    for index, (stage, gpu0) in enumerate(zip(simple, precision, strict=True)):
        name = stage.name.replace('fplc_v149_gpu1_', 'fplc_v150_gpu1_', 1)
        cfg = replace(stage.cfg, fixed_contact_training_phase=name)
        if index < 3:
            cfg = replace(
                cfg, fixed_contact_include_hit_contact_center_excess_penalty=True,
                fixed_contact_hit_center_penalty_outside_budget=True,
                fixed_contact_center_penalty_all_physical_outcomes=True,
                hit_contact_center_excess_penalty_weight=(2., 4., 8.)[index],
                hit_contact_center_excess_radius_m=.010,
                hit_contact_center_excess_sigma_m=.020,
                fixed_plane_v128_early_xy_motion_weight=(8., 16., 32.)[index],
                fixed_plane_v146_ball_anchor_xy_penalty_weight=(0., 1., 2.)[index],
            )
        else:
            cfg = replace(cfg, **{key: getattr(gpu0.cfg, key) for key in late_fields})
        result.append(replace(stage, name=name, cfg=cfg, notes=(
            'V150 retains the72-D position-only actor,90Hz camera, seven stages '
            'and every gate/control/physics/reset/DR value. First-three lessons '
            'include physical center costs outside the event budget and ramp '
            'early lateral costs; late precision rewards match GPU0 V149. '
            'Frozen GPU0 actions may supervise training through the existing '
            'uniform replay loss, without adding teacher features to the actor.')))
    return result


