def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v149_stages(
    stages: list[CurriculumStage],
    *, measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Refine motion and contact center while retaining the accepted policy."""
    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v148_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg)
    result = []
    for index, stage in enumerate(source, 1):
        name = stage.name.replace('fplc_v148_gpu0_', 'fplc_v149_gpu0_', 1)
        cfg = replace(stage.cfg, fixed_contact_training_phase=name)
        if index >= 4:
            cfg = replace(
                cfg, fixed_plane_v128_early_xy_motion_weight=480.0,
                racket_cycle_vxy_penalty_weight=9.0,
                fixed_plane_v134_late_xy_anchor_penalty_weight=100.0,
                hit_contact_center_excess_penalty_weight=160.0,
                hit_contact_center_excess_radius_m=0.003,
            )
        result.append(replace(stage, name=name, cfg=cfg, notes=(
            'V149 GPU0 changes only early XY speed320->480, whole speed6->9, '
            'late XY anchor80->100, physical center128->160 and deadband5->3mm. '
            'Frozen complete-component ranking preserves height/survival '
            'preference. Restore V148u447 actor/critic/Adam; retain calibrated '
            'physics, 156-D actor, bounded reference, resets, DR and all gates.')))
    return result


def validate_fixed_plane_v149_resume_payload(
    payload: dict[str, object], *, requested_start_stage: str,
    resume_curriculum_state: bool, reset_optimizer: bool,
) -> None:
    """Pin V148u447; retain actor/critic/Adam and start fresh reward convergence."""
    source_args = payload.get('args')
    source = (source_args.get('curriculum_profile') if isinstance(source_args, dict)
              else getattr(source_args, 'curriculum_profile', None))
    stage = str(payload.get('stage_name', ''))
    update, step = int(payload.get('stage_update', -1)), int(payload.get('step', -1))
    if (reset_optimizer or payload.get('opt') is None
            or int(payload.get('obs_dim', -1)) != 156
            or int(payload.get('critic_obs_dim', -1)) != 477
            or int(payload.get('act_dim', -1)) != 7
            or not isinstance(payload.get('params'), dict)
            or not {'pi', 'v'}.issubset(payload['params'])):
        raise ValueError('V149 requires the matching actor, critic and Adam')
    if source == FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V148_PROFILE:
        if (stage != 'fplc_v148_gpu0_s4_fourth_entry' or update != 447
                or step != 1444806656 or payload.get('stop_reason') != 'received SIGINT'
                or requested_start_stage != 'fplc_v149_gpu0_s4_fourth_entry'
                or resume_curriculum_state):
            raise ValueError('V149 requires pinned V148u447 with fresh convergence')
    elif source == FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V149_PROFILE:
        allowed = {f'fplc_v149_gpu0_s{i}_{name}' for i, name in (
            (4, 'fourth_entry'), (5, 'steady_quality'),
            (6, 'full_commit'), (7, 'clean_stability'))}
        if (stage not in allowed or requested_start_stage != stage
                or update < 1 or step <= 1444806656 or not resume_curriculum_state):
            raise ValueError('V149 continuation requires exact stage and history')
    else:
        raise ValueError('V149 rejects another source profile')


