def validate_fixed_plane_v110_resume_payload(
    payload: dict[str, object],
    *, requested_start_stage: str,
    resume_curriculum_state: bool,
    reset_optimizer: bool,
) -> None:
    """Pin V109 update 40 and allow only V110 exact-history continuation."""
    source_args = payload.get("args")
    source_profile = (
        source_args.get("curriculum_profile")
        if isinstance(source_args, dict)
        else getattr(source_args, "curriculum_profile", None)
    )
    source_stage = str(payload.get("stage_name", ""))
    source_step = int(payload.get("step", -1))
    source_update = int(payload.get("stage_update", -1))
    target_stage = "fplc_v110_gpu0_s1_launch_pair"
    if requested_start_stage != target_stage or reset_optimizer:
        raise ValueError("V110 must resume Stage 1 with actor, critic and Adam")
    if (
        int(payload.get("obs_dim", -1)) != 156
        or int(payload.get("critic_obs_dim", -1)) != 477
        or int(payload.get("act_dim", -1)) != 7
        or not isinstance(payload.get("params"), dict)
        or not {"pi", "v"}.issubset(payload["params"])
        or payload.get("opt") is None
    ):
        raise ValueError("V110 requires the matching 156-D actor and optimizer")
    if source_profile == FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V109_PROFILE:
        if (
            source_stage != "fplc_v109_gpu0_s1_launch_pair"
            or source_update != 40
            or source_step != 10485760
            or resume_curriculum_state
        ):
            raise ValueError("V110 requires the pinned V109 update-40 source")
    elif source_profile == FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V110_PROFILE:
        if (
            source_stage != target_stage
            or source_update < 1
            or source_step <= 10485760
            or not resume_curriculum_state
        ):
            raise ValueError("V110 same-stage resume requires its own history")
    else:
        raise ValueError("V110 rejects a checkpoint from another profile")


