def validate_fixed_plane_v86_residual_contract(
    *,
    source_path: Path,
    xml_path: Path,
    requested_start_stage: str,
    resume_curriculum_state: bool,
    residual_action_scale: float,
    residual_l2_coef: float,
) -> None:
    """Fail closed on the frozen V53 actor and original 1 ms V82 course."""

    if hashlib.sha256(source_path.read_bytes()).hexdigest() != (
        "fdd011c8c8884d10378d8ab80b8dd552cd5714170caba7f1972a1410b375e403"
    ):
        raise ValueError("V86 requires pinned V53 teacher SHA-256")
    if hashlib.sha256(xml_path.read_bytes()).hexdigest() != (
        "7d98f2adfdbad6082be0defcec2dbd0cbbcaf1f0fc06ce45ba424b5b3257cc92"
    ):
        raise ValueError("V86 requires original V53 1 ms XML")
    if requested_start_stage != "fplc_v86_gpu0_s4_fourth_entry":
        raise ValueError("V86 must start at its own Stage 4")
    if resume_curriculum_state:
        raise ValueError("V86 starts fresh critic, optimizer and convergence history")
    if not np.isclose(residual_action_scale, 0.2, rtol=0.0, atol=1e-12):
        raise ValueError("V86 residual action scale must be 0.2")
    if not np.isclose(residual_l2_coef, 0.02, rtol=0.0, atol=1e-12):
        raise ValueError("V86 residual L2 coefficient must be 0.02")


