def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v80_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Repair V53 late height regularity with all physical rebounds."""

    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v53_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    late_low_limits = (0.55, 0.40, 0.25, 0.10)
    late_event_min = (50.0, 80.0, 100.0, 120.0)
    survival_gates = (
        (5.0, 0.35, None),
        (6.0, 0.50, 0.02),
        (8.0, 0.60, 0.05),
        (8.0, 0.60, 0.10),
    )
    result: list[CurriculumStage] = []
    for index, stage in enumerate(source, start=1):
        name = stage.name.replace("fplc_v53_", "fplc_v80_", 1)
        if index < 4:
            result.append(replace(
                stage, name=name,
                cfg=replace(stage.cfg, fixed_contact_training_phase=name),
            ))
            continue
        mean_hits, hit6, hit12 = survival_gates[index - 4]
        result.append(replace(
            stage,
            name=name,
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=name,
                fixed_plane_v54_late_weak_credit_disabled=True,
                fixed_plane_v54_recovery_arrival_enabled=True,
                fixed_plane_v80_steady_height_weight=1.0,
            ),
            target_mean_hits=mean_hits,
            target_hit6_rate=hit6,
            target_hit12_rate=hit12,
            max_recent_late_physical_below_floor_rate=late_low_limits[index - 4],
            min_recent_late_physical_events=late_event_min[index - 4],
            min_recent_rapid_steady_hit4_apex_z_m=1.400,
            min_recent_rapid_steady_band_rate=None,
            max_recent_mean_hit_apex_abs_z_m=None,
            notes=(
                "V80 retains V53 1 ms 4 g control and acquired multihit policy. "
                "Every fourth-plus physical rebound, including weak ones, "
                "gets a floor/target/upper and adjacent-height score; later "
                "graduation requires physical-height and long-hit evidence."
            ),
        ))
    return result


