def validate_fixed_plane_limit_cycle_v73_resume_payload(
    payload: dict[str, object],
    *,
    source_path: Path,
    requested_start_stage: str,
    resume_curriculum_state: bool,
) -> None:
    """Accept only the stopped V72 Stage-1 u120 full optimizer checkpoint."""

    expected_path = Path(
        "/home/yangzhe/Project/pingpong_controller/pingpong_controller/outputs/rl_sim/"
        "fplc_v72_gpu0_probe400_seed20263572_20260926_180321/"
        "mjx_curriculum_last.pkl"
    )
    if source_path.resolve() != expected_path.resolve():
        raise ValueError("V73 requires the pinned V72 u120 checkpoint")
    if hashlib.sha256(source_path.read_bytes()).hexdigest() != (
        "0da94830d0bbebe98d1ce4b21d2a00ced014d0a817faabc8e32c162fec1e4371"
    ):
        raise ValueError("V73 source SHA-256 mismatch")
    if resume_curriculum_state:
        raise ValueError("V73 reward change requires fresh history")
    if requested_start_stage != "fplc_v73_gpu0_s1_launch_pair":
        raise ValueError("V73 must start at its own Stage 1")
    source_args = payload.get("args")
    if not isinstance(source_args, dict) or source_args.get(
        "curriculum_profile"
    ) != "fixed_plane_limit_cycle_qvel_rmp_gpu0_v72":
        raise ValueError("V73 source profile mismatch")
    for key, value in {
        "stage_name": "fplc_v72_gpu0_s1_launch_pair",
        "stage_index": 1,
        "stage_update": 120,
        "global_update": 120,
        "step": 1966080,
        "obs_dim": 96,
        "critic_obs_dim": 417,
        "act_dim": 7,
    }.items():
        if payload.get(key) != value:
            raise ValueError(f"V73 source {key} mismatch")
    if payload.get("params") is None or payload.get("opt") is None:
        raise ValueError("V73 requires actor, critic and Adam")


