def _fixed_plane_limit_cycle_qvel_rmp_gpu0_v50_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Pay one bounded physical four-component outcome at each rebound."""

    source = _fixed_plane_limit_cycle_qvel_rmp_gpu0_v49_stages(
        stages, measured_ball_mass_range_kg=measured_ball_mass_range_kg
    )
    result: list[CurriculumStage] = []
    for stage in source:
        name = stage.name.replace("fplc_v49_", "fplc_v50_", 1)
        result.append(replace(
            stage,
            name=name,
            cfg=replace(
                stage.cfg,
                fixed_contact_training_phase=name,
                fixed_plane_v41_outcome_credit_weight=0.25,
            ),
            notes=(
                "V50 restores V49 update-90 actor, critic and Adam. It pays "
                "a bounded 0--0.25 four-component result credit on actual "
                "weak or confirmed rebounds. Early V49 actor behavior is "
                "anchored; physics, control, reset and DR stay unchanged."
            ),
        ))
    return result


