def validate_fixed_plane_limit_cycle_v21_resume_payload(
    payload: dict[str, object],
    *,
    requested_start_stage: str | None,
    resume_curriculum_state: bool,
) -> None:
    """Pin V21 to the independently passed V20 Stage-5 boundary."""

    source_args = payload.get("args") or {}

    def source_arg(name: str, default=None):
        if isinstance(source_args, dict):
            return source_args.get(name, default)
        return getattr(source_args, name, default)

    expected_metadata = {
        "step": 231_997_440,
        "global_update": 1770,
        "stage_index": 5,
        "stage_name": "fplc_v20_gpu0_s5_steady_entry_prefix",
        "stage_update": 1027,
        "obs_dim": 96,
        "critic_obs_dim": 417,
        "act_dim": 7,
    }
    expected_args = {
        "seed": 20263401,
        "n_envs": 1024,
        "n_steps": 128,
        "minibatch_size": 16384,
        "update_epochs": 4,
        "learning_rate": 3.0e-4,
        "gamma": 0.9995,
        "gae_lambda": 0.99,
        "clip_range": 0.2,
        "target_kl": 0.012,
        "ent_coef": 0.001,
        "min_log_std": -3.0,
        "asymmetric_critic": True,
        "critic_command_history_steps": 12,
    }
    mismatches: list[str] = []
    if source_arg("curriculum_profile") != (
        FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V20_PROFILE
    ):
        mismatches.append(
            f"source curriculum_profile={source_arg('curriculum_profile')!r}"
        )
    for field, expected in expected_metadata.items():
        if payload.get(field) != expected:
            mismatches.append(f"{field}={payload.get(field)!r}")
    for field, expected in expected_args.items():
        actual = source_arg(field)
        if isinstance(expected, bool):
            equal = actual is expected
        else:
            try:
                equal = np.isclose(
                    float(actual), float(expected), rtol=0.0, atol=1.0e-12
                )
            except (TypeError, ValueError):
                equal = False
        if not equal:
            mismatches.append(f"source {field}={actual!r}")
    if source_arg("right_arm_pd_profile") != "recovered_rmp_rmpmd_v2":
        mismatches.append(
            "source right_arm_pd_profile="
            f"{source_arg('right_arm_pd_profile')!r}"
        )
    expected_start = "fplc_v21_gpu0_s6_steady_prefix_06"
    if requested_start_stage != expected_start:
        mismatches.append(f"requested_start_stage={requested_start_stage!r}")
    if resume_curriculum_state:
        mismatches.append("resume_curriculum_state=True")
    opt = payload.get("opt")
    if opt is None:
        mismatches.append("Adam moments missing")
    elif int(np.asarray(getattr(opt, "t", -1))) != 55754:
        mismatches.append(f"Adam t={getattr(opt, 't', None)!r}")
    last_row = payload.get("last_row") or {}
    if not isinstance(last_row, dict):
        mismatches.append("source last_row missing")
    else:
        if float(last_row.get("convergence/stage_converged", 0.0)) < 0.5:
            mismatches.append("source Stage-5 rolling gate did not pass")
        if float(last_row.get("advance_eval/passed", 0.0)) < 0.5:
            mismatches.append("source Stage-5 independent block did not pass")
    if mismatches:
        raise SystemExit(
            "[mjx_curriculum] V21 source is not the pinned V20 Stage-5 "
            "checkpoint: " + ", ".join(mismatches)
        )



