def validate_fixed_plane_v22_pair_metrics(report: dict[str, object]) -> None:
    """Require frozen-policy improvement without workspace/limit failure."""

    if report.get("schema") != "fixed_plane_v22_checkpoint_pair_v1":
        raise ValueError("V22 control-pair schema mismatch")
    if report.get("jax_backend") != "gpu" or not str(
        report.get("gpu_uuid", "")
    ).startswith("GPU-"):
        raise ValueError("V22 control-pair requires physical CUDA evidence")
    results = report.get("results")
    if not isinstance(results, list) or len(results) != 2:
        raise ValueError("V22 control-pair requires exactly two profiles")
    old, new = results
    if not isinstance(old, dict) or not isinstance(new, dict):
        raise ValueError("V22 control-pair result rows are invalid")
    if old.get("profile") != FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V21_PROFILE:
        raise ValueError("V22 control-pair baseline identity mismatch")
    if new.get("profile") != FIXED_PLANE_LIMIT_CYCLE_QVEL_RMP_GPU0_V22_PROFILE:
        raise ValueError("V22 control-pair candidate identity mismatch")
    if old.get("reset_qpos_sha256") != new.get("reset_qpos_sha256"):
        raise ValueError("V22 control-pair reset mismatch")
    required = (
        "first_episode_hits_mean", "hit3_fraction", "hit6_fraction",
        "max_actual_workspace_violation_m", "projection_fallback_fraction",
        "qvel_exceed_fraction", "qacc_exceed_fraction",
        "max_joint_velocity_limit_ratio",
    )
    for row in results:
        try:
            if not all(np.isfinite(float(row[key])) for key in required):
                raise ValueError("V22 control-pair has nonfinite metrics")
        except (KeyError, TypeError) as exc:
            raise ValueError("V22 control-pair is missing metrics") from exc
    if min(int(row.get("first_episode_completed_count", 0)) for row in results) < 16:
        raise ValueError("V22 control-pair incomplete first-episode population")
    old_hits = float(old["first_episode_hits_mean"])
    new_hits = float(new["first_episode_hits_mean"])
    if new_hits < old_hits + 0.5:
        raise ValueError("V22 control-pair mean hits did not improve")
    if float(new["hit3_fraction"]) < float(old["hit3_fraction"]) - 0.05:
        raise ValueError("V22 control-pair hit3 regressed")
    if float(new["hit6_fraction"]) < max(
        0.125, float(old["hit6_fraction"]) + 0.125
    ):
        raise ValueError("V22 control-pair hit6 did not improve")
    if float(new["max_actual_workspace_violation_m"]) > 1.0e-5:
        raise ValueError("V22 control-pair actual workspace violated")
    if float(new["qvel_exceed_fraction"]) > 1.0e-6:
        raise ValueError("V22 control-pair qvel limit violated")
    qacc = float(new["qacc_exceed_fraction"])
    if qacc > 0.02 or qacc > float(old["qacc_exceed_fraction"]) + 0.01:
        raise ValueError("V22 control-pair qacc limit regression")
    if float(new["max_joint_velocity_limit_ratio"]) > 1.01:
        raise ValueError("V22 control-pair joint velocity ratio exceeded")
    if float(new["projection_fallback_fraction"]) > (
        float(old["projection_fallback_fraction"]) + 0.01
    ):
        raise ValueError("V22 control-pair projection fallback regressed")


def validate_fixed_plane_v23_periodic_report(
    path: Path | None,
) -> dict[str, float]:
    """Pin and recompute the existing five-cycle RMP/projector result."""

    if path is None or not path.is_file():
        raise ValueError("V23 requires the pinned five-cycle report")
    report_bytes = path.read_bytes()
    if hashlib.sha256(report_bytes).hexdigest() != (
        "cde0f70415a70512252c151c8d1dc0092e8aef732d2795764da8e599ce5ae8db"
    ):
        raise ValueError("V23 five-cycle report SHA-256 mismatch")
    report = json.loads(report_bytes)
    if report.get("xml_sha256") != (
        "7d98f2adfdbad6082be0defcec2dbd0cbbcaf1f0fc06ce45ba424b5b3257cc92"
    ) or report.get("physical_gpu_uuid") != (
        "GPU-91f9b105-f5c8-b00e-de70-39d3ee1ce7b4"
    ) or float(report.get("reference_horizon_scale", 0.0)) != 2.0:
        raise ValueError("V23 five-cycle report physical contract mismatch")
    lanes = report.get("lanes")
    if not isinstance(lanes, list) or len(lanes) != 6:
        raise ValueError("V23 five-cycle report lanes missing")
    passing = []
    for lane in lanes:
        cycles = lane.get("cycles", [])
        if not lane.get("periodic_motion_pass") or len(cycles) < 6:
            continue
        late = [cycle["crossing"] for cycle in cycles[1:6]]
        passing.append((
            max(float(cross["surface_vxy_m_s"]) for cross in late),
            max(float(cross["racket_omega_rad_s"]) for cross in late),
        ))
    if len(passing) < 5:
        raise ValueError("V23 five-cycle report lacks five passing lanes")
    return {
        "passing_lanes": len(passing),
        "min_worst_five_vxy_m_s": min(value[0] for value in passing),
        "min_worst_five_omega_rad_s": min(value[1] for value in passing),
    }


def validate_fixed_plane_v22_pair_report(path: Path | None) -> None:
    """Bind V22's experimental evidence to current code and pinned inputs."""

    if path is None or not path.is_file():
        raise ValueError("V22 requires a frozen-policy control-pair report")
    try:
        report = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise ValueError("V22 control-pair report is unreadable") from exc
    expected_hashes = {
        "checkpoint_sha256": "5d72e382382a240fc5e1ccbf78d9bfeb64e878f856f4ea022cd8f1fac75557b8",
        "xml_sha256": "7d98f2adfdbad6082be0defcec2dbd0cbbcaf1f0fc06ce45ba424b5b3257cc92",
        "script_sha256": hashlib.sha256((
            Path(__file__).resolve().parent
            / "probe_fixed_plane_v22_checkpoint_pair.py"
        ).read_bytes()).hexdigest(),
        "trainer_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "environment_sha256": hashlib.sha256((
            Path(__file__).resolve().parent / "mjx_juggle_env.py"
        ).read_bytes()).hexdigest(),
    }
    for key, expected in expected_hashes.items():
        if report.get(key) != expected:
            raise ValueError(f"V22 control-pair {key} mismatch")
    results = report.get("results")
    if not isinstance(results, list) or len(results) != 2:
        raise ValueError("V22 control-pair profile count mismatch")
    if any(
        int(row.get("n_envs", 0)) != 16 or int(row.get("steps", 0)) != 1200
        for row in results
    ):
        raise ValueError("V22 control-pair population/horizon mismatch")
    validate_fixed_plane_v22_pair_metrics(report)


