def _sim2real_rootcause_homotopy_stages(
    source: CurriculumStage,
    *,
    name_prefix: str,
) -> list[CurriculumStage]:
    """Add two causal bridges before the full root-cause distribution.

    V17/V105 switched the deployed reset, record_new3 plant residuals, impact
    axes and 90 Hz observation scheduler at once.  GPU0 plateaued under that
    jump and GPU1 hit the lateral-velocity safety guard.  Keep the final
    distribution and gates unchanged, but expose the measured plant centre
    before widening impact and observation uncertainty.
    """

    full = _sim2real_rootcause_recovery_stages(
        source,
        name_prefix=name_prefix,
    )
    full_entry = full[0]
    source_cfg = source.cfg

    plant_cfg = replace(
        full_entry.cfg,
        # Preserve the measured record_new3 per-joint centre while narrowing
        # only its residual uncertainty for the first bridge.
        dr_second_order_frequency_scale_range=(0.97, 1.03),
        dr_second_order_damping_scale_range=(0.95, 1.10),
        dr_second_order_gain_scale_range=(0.995, 1.02),
        dr_second_order_delay_offset_steps_range=(-1, 1),
        dr_actuator_cmd_tau_range=(0.043, 0.050),
        dr_actuator_cmd_gain_range=(0.995, 1.02),
        # Do not introduce unsupported impact hypotheses in the plant bridge.
        dr_ball_normalized_inertia_range=(0.40, 0.40),
        dr_ball_spin_x_range_rad_s=(0.0, 0.0),
        dr_ball_friction_range=source_cfg.dr_ball_friction_range,
        dr_racket_friction_range=source_cfg.dr_racket_friction_range,
        dr_ball_solref_time_range=source_cfg.dr_ball_solref_time_range,
        dr_ball_solref_damping_range=source_cfg.dr_ball_solref_damping_range,
        dr_racket_rot_offset_rad=source_cfg.dr_racket_rot_offset_rad,
        dr_racket_radius_offset_m=source_cfg.dr_racket_radius_offset_m,
        # Keep the source scheduler until plant adaptation is demonstrated.
        dr_randomize_latency=False,
        ball_obs_rate_hz=float(source_cfg.ball_obs_rate_hz),
        ball_obs_fractional_rate=bool(source_cfg.ball_obs_fractional_rate),
    )
    plant = replace(
        full_entry,
        name=f"{name_prefix}_main_racket_launch_plant_bridge",
        cfg=plant_cfg,
        target_mean_hits=3.0,
        target_mean_hits_ge3=3.0,
        target_mean_len_frac=0.30,
        target_hit1_rate=0.80,
        target_hit3_rate=0.35,
        target_episode_truncation_rate=0.05,
        target_ball_view_in_bounds=0.82,
        max_recent_mean_hit_vxy=0.24,
        max_recent_rms_hit_vxy=0.34,
        min_updates=80,
        convergence_hold_updates=12,
        notes=(
            "record_new3 causal homotopy: measured per-joint plant centre with "
            "narrow residual DR; source impact axes and observation rate are "
            "retained. The 0.23 m target and 0.21--0.27 m apex gate are active. "
            + full_entry.notes
        ),
    )

    transition_cfg = replace(
        full_entry.cfg,
        dr_second_order_frequency_scale_range=(0.94, 1.08),
        dr_second_order_damping_scale_range=(0.90, 1.20),
        dr_second_order_gain_scale_range=(0.99, 1.04),
        dr_second_order_delay_offset_steps_range=(-1, 1),
        dr_actuator_cmd_tau_range=(0.041, 0.053),
        dr_actuator_cmd_gain_range=(0.99, 1.04),
        dr_ball_normalized_inertia_range=(0.40, 0.54),
        dr_ball_spin_x_range_rad_s=(-25.0, 25.0),
        dr_ball_solref_damping_range=(0.70, 1.09),
        dr_racket_rot_offset_rad=np.deg2rad(1.25),
        dr_randomize_latency=True,
        ball_obs_rate_hz=75.0,
        ball_obs_fractional_rate=True,
    )
    transition = replace(
        full_entry,
        name=f"{name_prefix}_main_racket_launch_impact_obs_bridge",
        cfg=transition_cfg,
        target_mean_hits=4.5,
        target_mean_hits_ge3=4.5,
        target_mean_len_frac=0.38,
        target_hit1_rate=0.84,
        target_hit3_rate=0.48,
        target_episode_truncation_rate=0.08,
        target_ball_view_in_bounds=0.86,
        max_recent_mean_hit_vxy=0.22,
        max_recent_rms_hit_vxy=0.30,
        min_updates=100,
        convergence_hold_updates=12,
        notes=(
            "record_new3 causal homotopy: intermediate plant residual, impact "
            "and 75 Hz fractional-observation support before the full 90 Hz "
            "distribution. "
            + full_entry.notes
        ),
    )
    return [plant, transition, *full]


