def _sim2real_rootcause_plant_ladder_stages(
    source: CurriculumStage,
    *,
    name_prefix: str,
    retain_transition_support: bool,
    include_execution_hold_ladder: bool = False,
) -> list[CurriculumStage]:
    """Graduate the independently fitted plant residual before other axes.

    V19/V107 both stayed in their first stage for more than 4,500 updates.
    V107 shows that widening the plant residual alone is sufficient to create
    the high-hit/high-lateral-energy plateau.  V19 additionally reverted its
    resume checkpoint from half-impact/75 Hz support to the source impact/60 Hz
    support, so its nominally single-axis stage was not actually single-axis.

    This course interpolates only residual support around the same measured
    seven-joint centre.  The QVEL branch retains the half-impact, randomized
    latency and 75 Hz support present in its V18 checkpoint until the complete
    plant range is learned.  The acceleration branch retains source impact and
    60 Hz observations while its plant range is widened.  Latency receives its
    own stage before observation-rate changes.  V21/V109 additionally keep
    discrete controller stalls disabled while continuous plant support grows,
    then introduce single-tick and measured tail holds on their own axis.
    Final task, B2/B3 and safety remain unchanged.  V21/V109 tighten the mean
    apex promotion band from 0.21--0.27 m to 0.215--0.26 m around the unchanged
    0.23 m physical target, preventing the QVEL branch from settling on its old
    lower-bound solution.
    """

    full = _sim2real_rootcause_recovery_stages(source, name_prefix=name_prefix)
    if include_execution_hold_ladder:
        # The QVEL continuation was already converging near the old 0.21 m
        # lower boundary.  Require a modest margin around the 0.23 m target
        # without changing the reward or the physical target definition.
        full = [
            replace(
                stage,
                min_recent_mean_hit_apex_rel_height_m=0.215,
                max_recent_mean_hit_apex_rel_height_m=0.26,
            )
            for stage in full
        ]
    full_entry = full[0]
    source_cfg = source.cfg

    if retain_transition_support:
        support_cfg = replace(
            full_entry.cfg,
            dr_ball_normalized_inertia_range=(0.40, 0.54),
            dr_ball_spin_x_range_rad_s=(-25.0, 25.0),
            dr_ball_solref_damping_range=(0.70, 1.09),
            dr_racket_rot_offset_rad=np.deg2rad(1.25),
            dr_randomize_latency=True,
            ball_obs_rate_hz=75.0,
            ball_obs_fractional_rate=True,
        )
    else:
        support_cfg = replace(
            full_entry.cfg,
            dr_ball_normalized_inertia_range=(0.40, 0.40),
            dr_ball_spin_x_range_rad_s=(0.0, 0.0),
            dr_ball_friction_range=source_cfg.dr_ball_friction_range,
            dr_racket_friction_range=source_cfg.dr_racket_friction_range,
            dr_ball_solref_time_range=source_cfg.dr_ball_solref_time_range,
            dr_ball_solref_damping_range=source_cfg.dr_ball_solref_damping_range,
            dr_racket_rot_offset_rad=source_cfg.dr_racket_rot_offset_rad,
            dr_racket_radius_offset_m=source_cfg.dr_racket_radius_offset_m,
            dr_randomize_latency=False,
            ball_obs_rate_hz=float(source_cfg.ball_obs_rate_hz),
            ball_obs_fractional_rate=bool(source_cfg.ball_obs_fractional_rate),
        )

    if include_execution_hold_ladder:
        # Continuous actuator variation and missed controller ticks are
        # independently identified mechanisms.  Do not expose a resumed
        # policy to both extrapolations in the first stage.
        support_cfg = replace(
            support_cfg,
            dr_execution_command_hold_probability=0.0,
            dr_execution_command_hold_tail_probability=0.0,
            dr_execution_command_hold_tail_steps_range=(2, 2),
        )

    narrow_ranges = {
        "frequency": (0.97, 1.03),
        "damping": (0.95, 1.10),
        "gain": (0.995, 1.02),
        "tau": (0.043, 0.050),
        "cmd_gain": (0.995, 1.02),
    }
    full_ranges = {
        "frequency": (0.88, 1.15),
        "damping": (0.80, 1.35),
        "gain": (0.97, 1.08),
        "tau": (0.040, 0.055),
        "cmd_gain": (0.98, 1.06),
    }

    def interpolate_pair(key: str, fraction: float) -> tuple[float, float]:
        narrow = narrow_ranges[key]
        target = full_ranges[key]
        return tuple(
            float(start + fraction * (end - start))
            for start, end in zip(narrow, target)
        )

    def with_plant_fraction(
        fraction: float,
        delay_range: tuple[int, int],
    ) -> MjxJuggleConfig:
        return replace(
            support_cfg,
            dr_second_order_frequency_scale_range=interpolate_pair(
                "frequency", fraction
            ),
            dr_second_order_damping_scale_range=interpolate_pair(
                "damping", fraction
            ),
            dr_second_order_gain_scale_range=interpolate_pair("gain", fraction),
            dr_second_order_delay_offset_steps_range=delay_range,
            dr_actuator_cmd_tau_range=interpolate_pair("tau", fraction),
            dr_actuator_cmd_gain_range=interpolate_pair("cmd_gain", fraction),
        )

    def bridge(
        label: str,
        cfg: MjxJuggleConfig,
        *,
        hits: float,
        length: float,
        view: float,
        mean_vxy: float,
        rms_vxy: float,
        max_interval: float = 0.58,
        min_updates: int = 80,
    ) -> CurriculumStage:
        apex_gate_note = (
            "0.215--0.26 m" if include_execution_hold_ladder else "0.21--0.27 m"
        )
        return replace(
            full_entry,
            name=f"{name_prefix}_{label}",
            cfg=cfg,
            target_mean_hits=hits,
            target_mean_hits_ge3=hits,
            target_mean_len_frac=length,
            target_hit1_rate=0.82,
            target_hit3_rate=0.42,
            target_episode_truncation_rate=0.06,
            target_ball_view_in_bounds=view,
            target_max_hit_interval_s=max_interval,
            max_recent_mean_hit_vxy=mean_vxy,
            max_recent_rms_hit_vxy=rms_vxy,
            min_updates=min_updates,
            convergence_hold_updates=12,
            notes=(
                "record_new3 plant-residual ladder: interpolate independent "
                "per-joint residual support around the unchanged fitted centre; "
                "impact, latency and observation rate are held fixed within "
                "each plant step. The target apex remains 0.23 m with a "
                f"{apex_gate_note} gate. "
                + full_entry.notes
            ),
        )

    if retain_transition_support:
        plant_specs = (
            (0.65, (-1, 1), 8.0, 0.62, 0.88, 0.20, 0.28, 0.62),
            (0.80, (-2, 1), 7.0, 0.55, 0.87, 0.21, 0.29, 0.60),
            (1.00, (-3, 3), 6.0, 0.48, 0.86, 0.22, 0.30, 0.58),
        )
    else:
        plant_specs = (
            (0.25, (-1, 1), 10.0, 0.70, 0.84, 0.20, 0.26, 0.58),
            (0.50, (-1, 1), 8.5, 0.60, 0.83, 0.21, 0.28, 0.58),
            (0.75, (-2, 1), 7.0, 0.50, 0.83, 0.22, 0.30, 0.58),
            (1.00, (-3, 3), 5.5, 0.42, 0.84, 0.22, 0.30, 0.58),
        )

    result = []
    for fraction, delay_range, hits, length, view, mean_vxy, rms_vxy, interval in plant_specs:
        percent = int(round(100.0 * fraction))
        result.append(
            bridge(
                f"main_racket_launch_plant_{percent}",
                with_plant_fraction(fraction, delay_range),
                hits=hits,
                length=length,
                view=view,
                mean_vxy=mean_vxy,
                rms_vxy=rms_vxy,
                max_interval=interval,
            )
        )

    if include_execution_hold_ladder:
        full_plant_no_hold_cfg = with_plant_fraction(1.0, (-3, 3))
        if retain_transition_support:
            hold_specs = (
                (
                    "execution_hold_3pct_single",
                    0.03, 0.0, (2, 2), 6.0, 0.48, 0.85, 0.22, 0.30,
                ),
                (
                    "execution_hold_8pct_single",
                    0.08, 0.0, (2, 2), 5.5, 0.44, 0.84, 0.22, 0.30,
                ),
                (
                    "execution_hold_8pct_tail_half",
                    0.08, 0.011, (2, 5), 5.0, 0.40, 0.83, 0.23, 0.31,
                ),
                (
                    "execution_hold_8pct_tail_full",
                    0.08, 0.022, (2, 9), 4.5, 0.36, 0.82, 0.24, 0.32,
                ),
            )
        else:
            hold_specs = (
                (
                    "execution_hold_3pct_single",
                    0.03, 0.0, (2, 2), 5.5, 0.42, 0.83, 0.22, 0.30,
                ),
                (
                    "execution_hold_8pct_single",
                    0.08, 0.0, (2, 2), 5.0, 0.39, 0.82, 0.23, 0.31,
                ),
                (
                    "execution_hold_8pct_tail_half",
                    0.08, 0.011, (2, 5), 4.5, 0.36, 0.81, 0.24, 0.32,
                ),
                (
                    "execution_hold_8pct_tail_full",
                    0.08, 0.022, (2, 9), 4.0, 0.33, 0.80, 0.25, 0.33,
                ),
            )
        for (
            label,
            hold_probability,
            tail_probability,
            tail_steps,
            hits,
            length,
            view,
            mean_vxy,
            rms_vxy,
        ) in hold_specs:
            result.append(
                bridge(
                    label,
                    replace(
                        full_plant_no_hold_cfg,
                        dr_execution_command_hold_probability=hold_probability,
                        dr_execution_command_hold_tail_probability=tail_probability,
                        dr_execution_command_hold_tail_steps_range=tail_steps,
                    ),
                    hits=hits,
                    length=length,
                    view=view,
                    mean_vxy=mean_vxy,
                    rms_vxy=rms_vxy,
                )
            )

    if retain_transition_support:
        result.extend(
            (
                bridge(
                    "main_racket_launch_full_impact_obs_75hz",
                    replace(
                        full_entry.cfg,
                        ball_obs_rate_hz=75.0,
                        ball_obs_fractional_rate=True,
                    ),
                    hits=5.5,
                    length=0.44,
                    view=0.85,
                    mean_vxy=0.21,
                    rms_vxy=0.29,
                ),
                bridge(
                    "main_racket_launch_full_impact_obs_82p5hz",
                    replace(
                        full_entry.cfg,
                        ball_obs_rate_hz=82.5,
                        ball_obs_fractional_rate=True,
                    ),
                    hits=5.2,
                    length=0.42,
                    view=0.87,
                    mean_vxy=0.21,
                    rms_vxy=0.29,
                    min_updates=100,
                ),
            )
        )
    else:
        half_impact_60_cfg = replace(
            full_entry.cfg,
            dr_ball_normalized_inertia_range=(0.40, 0.54),
            dr_ball_spin_x_range_rad_s=(-25.0, 25.0),
            dr_ball_solref_damping_range=(0.70, 1.09),
            dr_racket_rot_offset_rad=np.deg2rad(1.25),
            dr_randomize_latency=False,
            ball_obs_rate_hz=float(source_cfg.ball_obs_rate_hz),
            ball_obs_fractional_rate=bool(source_cfg.ball_obs_fractional_rate),
        )
        full_impact_60_cfg = replace(
            full_entry.cfg,
            dr_randomize_latency=False,
            ball_obs_rate_hz=float(source_cfg.ball_obs_rate_hz),
            ball_obs_fractional_rate=bool(source_cfg.ball_obs_fractional_rate),
        )
        latency_60_cfg = replace(
            full_entry.cfg,
            ball_obs_rate_hz=float(source_cfg.ball_obs_rate_hz),
            ball_obs_fractional_rate=bool(source_cfg.ball_obs_fractional_rate),
        )
        result.extend(
            (
                bridge(
                    "main_racket_launch_half_impact_60",
                    half_impact_60_cfg,
                    hits=5.0,
                    length=0.40,
                    view=0.84,
                    mean_vxy=0.22,
                    rms_vxy=0.30,
                ),
                bridge(
                    "main_racket_launch_full_impact_60",
                    full_impact_60_cfg,
                    hits=5.0,
                    length=0.40,
                    view=0.84,
                    mean_vxy=0.21,
                    rms_vxy=0.29,
                ),
                bridge(
                    "main_racket_launch_latency_60",
                    latency_60_cfg,
                    hits=5.0,
                    length=0.40,
                    view=0.84,
                    mean_vxy=0.21,
                    rms_vxy=0.29,
                ),
            )
        )
        for rate_hz, view, min_updates in (
            (67.5, 0.84, 80),
            (75.0, 0.85, 90),
            (82.5, 0.87, 100),
        ):
            result.append(
                bridge(
                    f"main_racket_launch_obs_{str(rate_hz).replace('.', 'p')}hz",
                    replace(
                        full_entry.cfg,
                        ball_obs_rate_hz=rate_hz,
                        ball_obs_fractional_rate=True,
                    ),
                    hits=5.0,
                    length=0.40,
                    view=view,
                    mean_vxy=0.21,
                    rms_vxy=0.29,
                    min_updates=min_updates,
                )
            )

    return [*result, *full]


