def _sport_taskspace_record_new3_sim2real_fixed_base_ball4g_viewbridge945_v146_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Calibrate only the Stage-50 view bridge after optimizer trials failed.

    V144 spent 3,308 Stage-50 updates below the 0.95 view gate while its other
    task gates passed.  A bounded V145 learning-rate trial did not improve
    paired frozen-policy view.  Preserve V144 Stages 1--49 and every behavioral
    field from Stage 50 through the final stage, except that Stage 50 alone uses
    the evidence-supported 0.945 bridge.  The 0.96/0.96/0.98 later view gates
    remain unchanged.
    """

    source = _sport_taskspace_record_new3_sim2real_fixed_base_ball4g_lr1e5_v144_stages(
        stages,
        measured_ball_mass_range_kg=measured_ball_mass_range_kg,
    )
    if len(source) != 53:
        raise ValueError(f"V146 expected 53 V144 source stages, got {len(source)}")
    if (
        source[49].name
        != "record_new3_sim2real_v144_ball_4g_measured_dr_consolidate"
    ):
        raise ValueError("V146 source Stage-50 identity changed")
    if not np.isclose(
        float(source[49].target_ball_view_in_bounds),
        0.95,
        rtol=0.0,
        atol=1.0e-12,
    ):
        raise ValueError("V146 source Stage-50 view gate changed")

    repaired: list[CurriculumStage] = list(source[:49])
    for index, stage in enumerate(source[49:], start=49):
        repaired.append(
            replace(
                stage,
                name=stage.name.replace(
                    "record_new3_sim2real_v144_",
                    "record_new3_sim2real_v146_",
                    1,
                ),
                target_ball_view_in_bounds=(
                    0.945 if index == 49 else stage.target_ball_view_in_bounds
                ),
                notes=(
                    "V146 evidence-calibrated Stage-50 bridge: revert to the "
                    "V144 1e-5 optimizer and screened update-1300 parent. "
                    "Only Stage 50 lowers view 0.950 -> 0.945 after V144's "
                    "3,308-update plateau and the negative V145 LR trial; "
                    "Stages 51--53 retain 0.960/0.960/0.980. Environment, "
                    "reward, cadence, control, observations and every other "
                    "gate remain unchanged. "
                    + stage.notes
                ),
            )
        )

    for index, (source_stage, candidate) in enumerate(
        zip(source[49:], repaired[49:], strict=True),
        start=49,
    ):
        if candidate.cfg != source_stage.cfg:
            raise ValueError("V146 may not change the V144 environment or reward")
        expected = replace(
            candidate,
            name=source_stage.name,
            notes=source_stage.notes,
            target_ball_view_in_bounds=source_stage.target_ball_view_in_bounds,
        )
        if expected != source_stage:
            raise ValueError("V146 changed outside the Stage-50 view bridge")
        if index > 49 and (
            candidate.target_ball_view_in_bounds
            != source_stage.target_ball_view_in_bounds
        ):
            raise ValueError("V146 weakened a post-Stage-50 view gate")
    if [stage.target_ball_view_in_bounds for stage in repaired[50:]] != [
        0.96,
        0.96,
        0.98,
    ]:
        raise ValueError("V146 post-bridge view gates changed")
    return repaired


def _sport_taskspace_record_new3_sim2real_fixed_base_ball4g_recovery_bridge_v147_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Bridge the measured B2/B3 recovery buckets without task collapse.

    V146 reached a stable Stage-51 B2 ceiling after 7,345 updates, but the
    proof-like gates inherited from the main racket-launch task remained well
    above that ceiling.  Keep Stages 1--50 exact, calibrate B2/B3 as recovery
    lessons, interpolate the real-data B2/B3 reset supports, then re-establish
    the main racket-launch distribution before the unchanged final proof.
    Optimizer, control, observation, reward, fixed-base and 4.0 g contracts do
    not change.
    """

    source = (
        _sport_taskspace_record_new3_sim2real_fixed_base_ball4g_viewbridge945_v146_stages(
            stages,
            measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        )
    )
    if len(source) != 53:
        raise ValueError(f"V147 expected 53 V146 source stages, got {len(source)}")
    expected_tail_names = (
        "record_new3_sim2real_v146_b2_low_energy_residual_recovery_60hz",
        "record_new3_sim2real_v146_b3_high_energy_normal_impulse_recovery_60hz",
        "record_new3_sim2real_v146_main_racket_launch_combined_proof_60hz",
    )
    if tuple(stage.name for stage in source[50:]) != expected_tail_names:
        raise ValueError("V147 source recovery/final identities changed")

    b2_source, b3_source, final_source = source[50:]
    b2 = replace(
        b2_source,
        name="record_new3_sim2real_v147_b2_stable_ceiling_recovery_60hz",
        target_mean_hits=9.5,
        target_mean_hits_ge3=11.5,
        target_mean_len_frac=0.72,
        target_episode_truncation_rate=0.60,
        target_ball_view_in_bounds=0.89,
        target_hit1_rate=0.96,
        target_hit3_rate=0.75,
        target_hit12_rate=0.50,
        max_recent_mean_hit_vxy=0.20,
        max_recent_rms_hit_vxy=0.29,
        min_updates=48,
        convergence_hold_updates=16,
        notes=(
            "V147 B2 stable-ceiling recovery gate, calibrated from the final "
            "V146 Stage-51 rolling distribution after 7,345 updates. This is "
            "a recovery-bucket competency gate, not the final deployed-task "
            "proof. Environment and reward remain exactly V146 B2. "
            + b2_source.notes
        ),
    )
    energy_bridge = replace(
        b2_source,
        name="record_new3_sim2real_v147_b2_b3_energy_bridge_60hz",
        cfg=replace(
            b2_source.cfg,
            falling_reset_time_to_contact_range_s=(0.18, 0.27),
            falling_reset_apex_height_range_m=(0.22, 0.35),
            falling_reset_vxy_max=0.08,
            falling_reset_contact_xy_jitter=0.030,
            falling_reset_contact_local_y_offset_range_m=(-0.16, 0.11),
        ),
        target_mean_hits=8.5,
        target_mean_hits_ge3=10.5,
        target_mean_len_frac=0.63,
        target_episode_truncation_rate=0.50,
        target_ball_view_in_bounds=0.88,
        target_hit1_rate=0.90,
        target_hit3_rate=0.65,
        target_hit12_rate=0.35,
        max_recent_mean_hit_vxy=0.22,
        max_recent_rms_hit_vxy=0.32,
        min_updates=96,
        convergence_hold_updates=16,
        notes=(
            "V147 B2-to-B3 energy bridge. Interpolate only the falling-contact "
            "time-to-contact, incoming-apex, XY speed/jitter and local-Y "
            "supports between the record_new3/4/5 B2 and B3 buckets; preserve "
            "all other physics, reward, observation and control fields. "
            + b2_source.notes
        ),
    )
    b3 = replace(
        b3_source,
        name=(
            "record_new3_sim2real_v147_b3_high_energy_normal_impulse_"
            "recovery_60hz"
        ),
        target_mean_hits=8.0,
        target_mean_hits_ge3=9.5,
        target_mean_len_frac=0.60,
        target_episode_truncation_rate=0.45,
        target_ball_view_in_bounds=0.88,
        target_hit1_rate=0.85,
        target_hit3_rate=0.60,
        target_hit12_rate=0.30,
        max_recent_mean_hit_vxy=0.21,
        max_recent_rms_hit_vxy=0.30,
        min_updates=120,
        convergence_hold_updates=16,
        notes=(
            "V147 B3 high-energy recovery gate. The record_new3/4/5 B3 "
            "population is retained as a hard recovery bucket, while its "
            "graduation threshold measures recovery rather than requiring "
            "final racket-launch proof performance inside another reset domain. "
            + b3_source.notes
        ),
    )
    retention = replace(
        final_source,
        name=(
            "record_new3_sim2real_v147_main_racket_launch_retention_bridge_60hz"
        ),
        target_mean_hits=11.5,
        target_mean_hits_ge3=12.0,
        target_mean_len_frac=0.88,
        target_episode_truncation_rate=0.75,
        target_ball_view_in_bounds=0.94,
        target_hit1_rate=0.96,
        target_hit3_rate=0.85,
        target_hit12_rate=0.60,
        max_recent_mean_hit_vxy=0.17,
        max_recent_rms_hit_vxy=0.23,
        min_updates=96,
        convergence_hold_updates=16,
        notes=(
            "V147 main-task retention bridge after the B2/B3 recovery "
            "curriculum. It restores the exact final racket-launch environment "
            "before the unchanged proof gate so cross-domain forgetting cannot "
            "silently advance into the final stage. "
            + final_source.notes
        ),
    )
    final = replace(
        final_source,
        name="record_new3_sim2real_v147_main_racket_launch_combined_proof_60hz",
        notes=(
            "V147 unchanged V146 final racket-launch proof after explicit "
            "recovery and retention bridges. "
            + final_source.notes
        ),
    )

    repaired = source[:50] + [b2, energy_bridge, b3, retention, final]
    for stage in repaired[50:]:
        if stage.cfg.simulation_base_mode != "aligned_fixed":
            raise ValueError("V147 recovery tail must remain fixed-base")
        if tuple(stage.cfg.dr_ball_mass_range) != tuple(
            measured_ball_mass_range_kg or ()
        ):
            raise ValueError("V147 recovery tail changed measured ball-mass DR")
    if b2.cfg != b2_source.cfg or b3.cfg != b3_source.cfg:
        raise ValueError("V147 changed a source B2/B3 environment")
    if retention.cfg != final_source.cfg or final.cfg != final_source.cfg:
        raise ValueError("V147 changed the main racket-launch environment")
    if final != replace(final_source, name=final.name, notes=final.notes):
        raise ValueError("V147 changed the unchanged final proof contract")
    return repaired


def _sport_taskspace_record_new3_sim2real_fixed_base_ball4g_nonregression_bridge_v148_stages(
    stages: list[CurriculumStage],
    *,
    measured_ball_mass_range_kg: tuple[float, float] | None,
) -> list[CurriculumStage]:
    """Split the B2/B3 reset jump while retaining every V146 proof gate.

    The V146 Stage-51 trace and the record_new3/4/5 branch audit isolate an
    abrupt, multi-axis reset-distribution transition: B2 and B3 are distinct
    low- and high-energy pre-second-contact populations, while PPO numerics
    and the existing reward signal remain healthy.  V148 therefore changes
    only curriculum resolution.  It keeps V146 Stages 1--50 byte-for-byte,
    inserts a mild B2 entry and a B2-to-B3 energy bridge, and repeats the
    original main-task proof so recovery training cannot silently trade away
    juggling or survival.  No reward, gate, control, observation, physics or
    DR field is weakened.
    """

    source = (
        _sport_taskspace_record_new3_sim2real_fixed_base_ball4g_viewbridge945_v146_stages(
            stages,
            measured_ball_mass_range_kg=measured_ball_mass_range_kg,
        )
    )
    if len(source) != 53:
        raise ValueError(f"V148 expected 53 V146 source stages, got {len(source)}")
    expected_tail_names = (
        "record_new3_sim2real_v146_b2_low_energy_residual_recovery_60hz",
        "record_new3_sim2real_v146_b3_high_energy_normal_impulse_recovery_60hz",
        "record_new3_sim2real_v146_main_racket_launch_combined_proof_60hz",
    )
    if tuple(stage.name for stage in source[50:]) != expected_tail_names:
        raise ValueError("V148 source recovery/final identities changed")

    b2_source, b3_source, final_source = source[50:]
    mild_b2 = replace(
        b2_source,
        name="record_new3_sim2real_v148_b2_low_energy_entry_bridge_60hz",
        cfg=replace(
            b2_source.cfg,
            falling_reset_time_to_contact_range_s=(0.12, 0.20),
            falling_reset_apex_height_range_m=(0.10, 0.20),
            falling_reset_vxy_max=0.03,
            falling_reset_contact_xy_jitter=0.0125,
            falling_reset_contact_local_y_offset_range_m=(-0.06, 0.04),
        ),
        notes=(
            "V148 non-regression B2 entry bridge. Narrow only the five "
            "falling-contact reset axes responsible for the abrupt V146 "
            "Stage-50-to-51 jump; retain the complete original B2 reward and "
            "proof gate. "
            + b2_source.notes
        ),
    )
    b2 = replace(
        b2_source,
        name="record_new3_sim2real_v148_b2_low_energy_residual_recovery_60hz",
        notes=(
            "V148 exact V146 B2 population and proof gate after the mild "
            "entry bridge. "
            + b2_source.notes
        ),
    )
    energy_bridge = replace(
        b3_source,
        name="record_new3_sim2real_v148_b2_b3_energy_bridge_60hz",
        cfg=replace(
            b3_source.cfg,
            falling_reset_time_to_contact_range_s=(0.18, 0.27),
            falling_reset_apex_height_range_m=(0.22, 0.35),
            falling_reset_vxy_max=0.08,
            falling_reset_contact_xy_jitter=0.030,
            falling_reset_contact_local_y_offset_range_m=(-0.16, 0.11),
        ),
        notes=(
            "V148 B2-to-B3 energy bridge. Interpolate only the five measured "
            "falling-contact reset supports while retaining the complete "
            "original B3 reward and proof gate. "
            + b3_source.notes
        ),
    )
    b3 = replace(
        b3_source,
        name=(
            "record_new3_sim2real_v148_b3_high_energy_normal_impulse_"
            "recovery_60hz"
        ),
        notes=(
            "V148 exact V146 B3 population and proof gate after the energy "
            "bridge. "
            + b3_source.notes
        ),
    )
    retention = replace(
        final_source,
        name=(
            "record_new3_sim2real_v148_main_racket_launch_retention_proof_60hz"
        ),
        notes=(
            "V148 unchanged V146 main-task proof, repeated immediately after "
            "the recovery buckets as a non-regression retention gate. "
            + final_source.notes
        ),
    )
    final = replace(
        final_source,
        name=(
            "record_new3_sim2real_v148_main_racket_launch_combined_proof_60hz"
        ),
        notes=(
            "V148 unchanged V146 final proof after an explicit retention "
            "stage. "
            + final_source.notes
        ),
    )

    repaired = source[:50] + [mild_b2, b2, energy_bridge, b3, retention, final]
    for candidate, source_stage in (
        (mild_b2, b2_source),
        (b2, b2_source),
        (energy_bridge, b3_source),
        (b3, b3_source),
        (retention, final_source),
        (final, final_source),
    ):
        if candidate.cfg.simulation_base_mode != "aligned_fixed":
            raise ValueError("V148 recovery tail must remain fixed-base")
        if tuple(candidate.cfg.dr_ball_mass_range) != tuple(
            measured_ball_mass_range_kg or ()
        ):
            raise ValueError("V148 recovery tail changed measured ball-mass DR")
        if candidate != replace(
            source_stage,
            name=candidate.name,
            notes=candidate.notes,
            cfg=candidate.cfg,
        ):
            raise ValueError("V148 changed a reward, gate, or non-reset contract")
    return repaired


