def validate_measured_qvel_rmp_v65_resume_payload(
    payload: dict[str, object],
) -> None:
    """Accept the pinned V29 source or a complete V65 CMDP continuation."""

    source_args = payload.get("args", {})

    def source_arg(name: str, default=None):
        if isinstance(source_args, dict):
            return source_args.get(name, default)
        return getattr(source_args, name, default)

    source_profile = source_arg("curriculum_profile")
    if source_profile == GOAL_D455_MEASURED_QVEL_RMP_VERTICAL_V29_PROFILE:
        try:
            validate_measured_qvel_rmp_v64_resume_payload(payload)
        except SystemExit as exc:
            raise SystemExit(str(exc).replace("V64 resume", "V65 resume")) from None
        return

    mismatches: list[str] = []
    if source_profile != GOAL_D455_MEASURED_QVEL_RMP_VERTICAL_V65_PROFILE:
        mismatches.append(f"curriculum_profile={source_profile!r}")
    expected_metadata = {
        "obs_dim": 57,
        "critic_obs_dim": 221,
        "act_dim": 7,
        "stage_index": 1,
        "stage_name": "rmp65_v29_stage21_cmdp_survival",
    }
    mismatches.extend(
        f"{name}={payload.get(name)!r}"
        for name, expected in expected_metadata.items()
        if payload.get(name) != expected
    )
    if int(payload.get("step", 0)) <= 2087190528:
        mismatches.append(f"step={payload.get('step')!r}")
    params = payload.get("params")
    if not isinstance(params, dict):
        mismatches.append("params missing")
    else:
        if "cmdp_cost_v" not in params:
            mismatches.append("cmdp_cost_v missing")
        if "cmdp_dual" not in params:
            mismatches.append("cmdp_dual missing")
        elif np.asarray(params["cmdp_dual"]).shape != (len(CMDP_COST_NAMES),):
            mismatches.append(
                f"cmdp_dual shape={np.asarray(params['cmdp_dual']).shape!r}"
            )
    opt = payload.get("opt")
    if opt is None:
        mismatches.append("Adam moments missing")
    else:
        for moment_name in ("m", "v"):
            moment = getattr(opt, moment_name, None)
            if not isinstance(moment, dict) or "cmdp_cost_v" not in moment:
                mismatches.append(f"Adam {moment_name} cmdp_cost_v missing")
    expected_source_values = {
        "cmdp_enabled": True,
        "n_steps": 128,
        "update_epochs": 3,
        "learning_rate": 1.0e-4,
        "gamma": 0.9995,
        "gae_lambda": 0.99,
        "clip_range": 0.15,
        "target_kl": 0.008,
        "ent_coef": 0.0002,
        "min_log_std": -4.8,
        "cmdp_cost_gae_lambda": 0.99,
        "cmdp_cost_vf_coef": 0.5,
        "cmdp_dual_learning_rate": 0.1,
        "cmdp_dual_max": 2.0,
    }
    for name, expected in expected_source_values.items():
        actual = source_arg(name)
        if isinstance(expected, bool):
            if bool(actual) is not expected:
                mismatches.append(f"source {name}={actual!r}")
        elif actual is None or not np.isclose(
            float(actual), float(expected), rtol=0.0, atol=1.0e-12
        ):
            mismatches.append(f"source {name}={actual!r}")
    if mismatches:
        raise SystemExit(
            "[mjx_curriculum] V65 resume checkpoint is neither the pinned "
            "V29 Stage-21 source nor a complete V65 CMDP continuation: "
            + ", ".join(mismatches)
        )


