def validate_measured_qvel_rmp_v72_resume_payload(
    payload: dict[str, object],
) -> None:
    """Pin initial V72 to V68 or resume an exact signal-stopped V72 state."""

    source_args = payload.get("args", {})

    def source_arg(name: str, default=None):
        if isinstance(source_args, dict):
            return source_args.get(name, default)
        return getattr(source_args, name, default)

    source_profile = source_arg("curriculum_profile")
    if source_profile == GOAL_D455_MEASURED_QVEL_RMP_VERTICAL_V72_PROFILE:
        mismatches: list[str] = []
        expected_metadata = {
            "obs_dim": 57,
            "critic_obs_dim": 368,
            "act_dim": 7,
        }
        mismatches.extend(
            f"{name}={payload.get(name)!r}"
            for name, expected in expected_metadata.items()
            if payload.get(name) != expected
        )

        stage_index_raw = payload.get("stage_index")
        try:
            stage_index = int(stage_index_raw)
        except (TypeError, ValueError):
            stage_index = -1
            mismatches.append(f"stage_index={stage_index_raw!r}")
        stages = build_curriculum(
            curriculum_profile=GOAL_D455_MEASURED_QVEL_RMP_VERTICAL_V72_PROFILE,
            measured_ball_mass_range_kg=(0.0030, 0.0040),
        )
        if not 7 <= stage_index <= len(stages):
            mismatches.append(f"stage_index={stage_index!r} is outside 7..28")
            expected_stage = None
        else:
            expected_stage = stages[stage_index - 1]
            if payload.get("stage_name") != expected_stage.name:
                mismatches.append(f"stage_name={payload.get('stage_name')!r}")
            if payload.get("env_cfg") != expected_stage.cfg.__dict__:
                mismatches.append("env_cfg is not the exact V72 stage domain")

        try:
            stage_update = int(payload.get("stage_update", -1))
            global_update = int(payload.get("global_update", -1))
            step = int(payload.get("step", -1))
        except (TypeError, ValueError):
            stage_update = global_update = step = -1
            mismatches.append("non-integer stage/global update or step")
        if stage_update < 0 or global_update < stage_update:
            mismatches.append(
                f"stage_update/global_update={stage_update}/{global_update}"
            )
        expected_step = 2250244096 + global_update * 1024 * 128
        if step != expected_step:
            mismatches.append(f"step={step!r}, expected {expected_step}")

        last_row = payload.get("last_row")
        if not isinstance(last_row, dict):
            mismatches.append("last_row missing")
        else:
            expected_last_row = {
                "stage_index": stage_index,
                "stage_name": (
                    expected_stage.name if expected_stage is not None else None
                ),
                "stage_update": stage_update,
                "global_update": global_update,
                "global_step": step,
            }
            for name, expected in expected_last_row.items():
                actual = last_row.get(name)
                if name != "stage_name":
                    try:
                        actual = int(float(actual))
                    except (TypeError, ValueError):
                        pass
                if actual != expected:
                    mismatches.append(f"last_row {name}={actual!r}")

        params = payload.get("params")
        if not isinstance(params, dict):
            mismatches.append("params missing")
        else:
            missing_params = {"pi", "v", "log_std"} - set(params)
            if missing_params:
                mismatches.append(
                    "parameter trees missing "
                    + ",".join(sorted(missing_params))
                )
            if "cmdp_cost_v" in params or "cmdp_dual" in params:
                mismatches.append("CMDP state present")
        opt = payload.get("opt")
        if opt is None:
            mismatches.append("Adam moments missing")
        else:
            opt_t = int(np.asarray(getattr(opt, "t", -1)))
            max_opt_t = 460120 + max(global_update, 0) * 16
            if not 460120 <= opt_t <= max_opt_t:
                mismatches.append(
                    f"Adam t={opt_t!r} outside [460120,{max_opt_t}]"
                )

        expected_source_args = {
            "n_envs": 1024,
            "n_steps": 128,
            "minibatch_size": 16384,
            "update_epochs": 2,
            "learning_rate": 5.0e-5,
            "gamma": 0.9995,
            "gae_lambda": 0.99,
            "clip_range": 0.10,
            "target_kl": 0.004,
            "ent_coef": 0.0002,
            "min_log_std": -4.8,
            "convergence_window": 48,
            "stage_metric_warmup_updates": 16,
        }
        for name, expected in expected_source_args.items():
            actual = source_arg(name)
            if actual is None or not np.isclose(
                float(actual), float(expected), rtol=0.0, atol=1.0e-12
            ):
                mismatches.append(f"source {name}={actual!r}")
        source_mass = source_arg("measured_ball_mass_range_kg")
        if source_mass is None or not np.allclose(
            np.asarray(source_mass, dtype=np.float64),
            (0.0030, 0.0040),
            rtol=0.0,
            atol=1.0e-12,
        ):
            mismatches.append(
                f"source measured_ball_mass_range_kg={source_mass!r}"
            )
        if bool(source_arg("cmdp_enabled", False)):
            mismatches.append("source cmdp_enabled=True")
        if payload.get("stage_actor_anchor_reference_params") is None:
            mismatches.append("stage actor anchor missing")
        if payload.get("stop_kind") != "signal":
            mismatches.append(f"stop_kind={payload.get('stop_kind')!r}")
        if payload.get("stop_reason") != "received SIGINT":
            mismatches.append(f"stop_reason={payload.get('stop_reason')!r}")

        if mismatches:
            raise SystemExit(
                "[mjx_curriculum] V72 self-resume checkpoint is not an exact "
                "signal-stopped V72 state with causal Stage-7+ history: "
                + ", ".join(mismatches)
            )
        return

    try:
        validate_measured_qvel_rmp_v70_resume_payload(payload)
    except SystemExit as exc:
        raise SystemExit(str(exc).replace("V70", "V72")) from exc


